def load_watchlist_db_for_user(owner_email):
    if IS_PUBLIC_DEMO:
        return []

    res = run_supabase(
        supabase.table("watchlist").select("name,ticker,is_etf,asset_class,sort_order,fin_score").eq("owner_email", owner_email),
        "load watchlist",
    )

