# SECTION 07: 돈흐름 & 로테이션 엔진
# flow score, rotation panel, ETF section, theme flow
# ════════════════════════════════════════════════════════════════════════════

def fmt_flow_pct(v):
    if not finite_num(v):
        return "-"
    return f"{float(v) * 100:.1f}%"


def fmt_flow_score(v):
    if not finite_num(v):
        return "-"
    return f"{float(v):.1f}"


FLOW_SCORE_PART_COLUMNS = [
    ("점수_1개월", "1M"),
    ("점수_3개월", "3M"),
    ("점수_6개월", "6M"),
    ("점수_가속도", "가속"),
    ("점수_거래량", "거래량"),
    ("점수_랭킹보조", "네이버랭킹"),
    ("점수_상승비율", "상승비율"),
    ("점수_쏠림패널티", "쏠림"),
    ("점수_과열패널티", "과열"),
]


def render_flow_score_breakdown(title, df, score_col="돈흐름점수", label_cols=None, top_n=8):
    if df is None or df.empty or score_col not in df.columns:
        return
    part_cols = [col for col, _ in FLOW_SCORE_PART_COLUMNS if col in df.columns]
    if not part_cols:
        return

    label_cols = [c for c in (label_cols or []) if c in df.columns]
    view = df.dropna(subset=[score_col]).copy()
    if view.empty:
        return
    view = view.sort_values(score_col, ascending=False).head(top_n)

    show_cols = label_cols + [score_col] + part_cols
    show = view[show_cols].copy()
    rename_map = {col: label for col, label in FLOW_SCORE_PART_COLUMNS if col in show.columns}
    show = show.rename(columns={score_col: "총점", **rename_map})
    for col in ["총점"] + [rename_map[c] for c in part_cols if c in rename_map]:
        if col in show.columns:
            show[col] = show[col].apply(lambda v: "-" if not finite_num(v) else f"{float(v):+.1f}")

    with st.expander(title, expanded=False):
        st.caption(
            "점수 구성요소를 분해한 표입니다. 양수는 점수를 올린 요인, 음수는 과열/쏠림처럼 점수를 깎은 요인입니다."
        )
        st.dataframe(show, width='stretch', hide_index=True)


def build_today_flow_rank_table(df, group_name, score_col="돈흐름점수", top_n=5):
    if df is None or df.empty or score_col not in df.columns:
        return pd.DataFrame()
    if "구분" not in df.columns:
        return pd.DataFrame()
    view = df[df["구분"].astype(str).eq(group_name)].dropna(subset=[score_col]).copy()
    if view.empty:
        return pd.DataFrame()
    # 스윙 점수 기준 필터 (하락·둔화·고점 추격 제외)
    if score_col == "스윙점수":
        if "2주수익률" in view.columns:
            # 2주 +1% 미만 제외 — 진짜 단기 모멘텀 없으면 스윙 자리 아님
            view = view[view["2주수익률"].apply(lambda v: finite_num(v) and float(v) >= 0.01)]
        if "단기가속도" in view.columns:
            # 단기가속도 음수 제외 — 둔화·역전 중인 섹터 차단
            view = view[view["단기가속도"].apply(lambda v: finite_num(v) and float(v) >= 0.0)]
        if "상태" in view.columns:
            # 과열경보 제외 — 고점 추격 방지
            view = view[view["상태"].astype(str) != "과열경보"]
    if view.empty:
        return pd.DataFrame()
    return view.sort_values(score_col, ascending=False).head(top_n)


def format_today_flow_rank_table(df, score_col="돈흐름점수"):
    if df is None or df.empty:
        return pd.DataFrame()
    view = df.copy()
    for col in ["1개월수익률", "2주수익률", "3개월수익률", "상대3개월수익률", "6개월수익률", "가속도", "단기가속도", "거래량증가", "상승종목비율"]:
        if col in view.columns:
            view[col] = view[col].apply(fmt_flow_pct)
    for sc in [score_col, "스윙점수"]:
        if sc in view.columns:
            view[sc] = view[sc].apply(fmt_flow_score)
    cols = list(dict.fromkeys([  # 중복 제거 (score_col == "스윙점수" 일 때)
        "섹터", "Ticker", "ETF 이름", score_col, "스윙점수", "상태", "추격위험",
        "2주수익률", "1개월수익률", "3개월수익률", "단기가속도", "거래량증가",
    ]))
    return view[[c for c in cols if c in view.columns]]


def format_today_theme_rank_table(df, score_col="테마돈흐름점수"):
    if df is None or df.empty:
        return pd.DataFrame()
    view = df.copy()
    for col in [
        "2주수익률", "1개월수익률", "3개월수익률", "상대3개월수익률", "6개월수익률",
        "가속도", "단기가속도", "거래량증가", "2주상승비율", "1개월상승비율",
        "상승종목비율", "네이버테마상승비율",
    ]:
        if col in view.columns:
            view[col] = view[col].apply(fmt_flow_pct)
    if score_col in view.columns:
        view[score_col] = view[score_col].apply(fmt_flow_score)
    cols = [
        "테마", "하위테마", "대표주", score_col, "테마판정", "상태", "추격위험",
        "2주수익률", "1개월수익률", "3개월수익률", "2주상승비율", "상승종목비율",
        "가속도", "단기가속도", "거래량증가", "네이버테마근거", "구성종목",
    ]
    return view[[c for c in cols if c in view.columns]]


def build_today_theme_flow_tables(theme_flow_df, rotation_df, group_df):
    if rotation_df is None or rotation_df.empty or "테마돈흐름점수" not in rotation_df.columns:
        return pd.DataFrame(), pd.DataFrame()

    theme_rank = rotation_df.dropna(subset=["테마돈흐름점수"]).copy()
    if theme_rank.empty:
        return pd.DataFrame(), pd.DataFrame()

    theme_rank = theme_rank.sort_values("테마돈흐름점수", ascending=False)
    top_theme = str(theme_rank.iloc[0].get("테마", "") or "")

    subtheme_rank = pd.DataFrame()
    if group_df is not None and not group_df.empty and top_theme:
        score_col = "돈흐름점수" if "돈흐름점수" in group_df.columns else "테마돈흐름점수"
        if score_col in group_df.columns:
            subtheme_rank = (
                group_df[group_df["테마"].astype(str).eq(top_theme)]
                .dropna(subset=[score_col])
                .sort_values(score_col, ascending=False)
                .head(3)
                .copy()
            )

    return theme_rank.head(5), subtheme_rank


@st.cache_data(ttl=900, show_spinner=False)
def get_today_market_flow_snapshot():
    flow_df = calculate_money_flow_df()
    us_top5 = build_today_flow_rank_table(flow_df, "미국 섹터", top_n=5)
    kr_top5 = build_today_flow_rank_table(flow_df, "한국 섹터", top_n=5)
    global_top = build_today_flow_rank_table(flow_df, "글로벌", top_n=1)
    local_top = build_today_flow_rank_table(flow_df, "국내상장 대표 ETF", top_n=1)
    # 스윙 점수 기준 TOP (스윙 트레이딩용 — 단기 방향 전환 민감)
    us_swing_top3  = build_today_flow_rank_table(flow_df, "미국 섹터",  score_col="스윙점수", top_n=3)
    kr_swing_top3  = build_today_flow_rank_table(flow_df, "한국 섹터",  score_col="스윙점수", top_n=3)
    global_swing_top = build_today_flow_rank_table(flow_df, "글로벌",   score_col="스윙점수", top_n=1)
    sector_rotation_df = calculate_sector_rotation_df(flow_df)

    theme_flow_df = pd.DataFrame()
    theme_rotation_df = pd.DataFrame()
    subtheme_group_df = pd.DataFrame()
    theme_top5 = pd.DataFrame()
    subtheme_top = pd.DataFrame()
    if IMAGE_THEME_FLOW_AVAILABLE:
        theme_flow_df = calculate_image_theme_flow_df("")
        theme_rotation_df = calculate_image_theme_rotation_df(theme_flow_df)
        subtheme_group_df = calculate_image_theme_group_df(theme_flow_df)
        theme_top5, subtheme_top = build_today_theme_flow_tables(
            theme_flow_df,
            theme_rotation_df,
            subtheme_group_df,
        )

    return {
        "flow_df": flow_df,
        "us_top5": us_top5,
        "kr_top5": kr_top5,
        "global_top": global_top,
        "local_top": local_top,
        "us_swing_top3": us_swing_top3,
        "kr_swing_top3": kr_swing_top3,
        "global_swing_top": global_swing_top,
        "sector_rotation_df": sector_rotation_df,
        "theme_flow_df": theme_flow_df,
        "theme_rotation_df": theme_rotation_df,
        "subtheme_group_df": subtheme_group_df,
        "theme_top5": theme_top5,
        "subtheme_top": subtheme_top,
    }


TODAY_MARKET_FLOW_SNAPSHOT_KEY = "today_market_flow_snapshot"
TODAY_MARKET_FLOW_LAST_RUN_KEY = "today_market_flow_snapshot_last_run"


def get_cached_today_market_flow_snapshot():
    snapshot = st.session_state.get(TODAY_MARKET_FLOW_SNAPSHOT_KEY)
    return snapshot if isinstance(snapshot, dict) else None


def clear_today_market_flow_snapshot_cache(clear_data_cache: bool = False):
    st.session_state.pop(TODAY_MARKET_FLOW_SNAPSHOT_KEY, None)
    st.session_state.pop(TODAY_MARKET_FLOW_LAST_RUN_KEY, None)
    if clear_data_cache:
        cache_clear(get_today_market_flow_snapshot)
        cache_clear(calculate_money_flow_df)
        cache_clear(download_money_flow_prices)
        if IMAGE_THEME_FLOW_AVAILABLE:
            cache_clear(calculate_image_theme_flow_df)


def refresh_today_market_flow_snapshot(include_theme: bool = True):
    """ETF/섹터 데이터 + 테마종목(옵션) 계산.
    include_theme=False이면 ETF/섹터만 빠르게 계산하고 기존 테마 결과를 유지.
    """
    _kst_now = datetime.now(timezone(timedelta(hours=9))).strftime("%Y-%m-%d %H:%M")

    if not include_theme:
        # ── 빠른 모드: ETF/섹터만 재계산, 기존 스냅샷의 테마 결과 유지 ──
        cache_clear(calculate_money_flow_df)
        cache_clear(download_money_flow_prices)
        flow_df = calculate_money_flow_df()
        sector_rotation_df = calculate_sector_rotation_df(flow_df)
        prev = get_cached_today_market_flow_snapshot() or {}
        snapshot = {
            **prev,  # 테마 결과는 기존 것 유지
            "flow_df":           flow_df,
            "us_top5":           build_today_flow_rank_table(flow_df, "미국 섹터", top_n=5),
            "kr_top5":           build_today_flow_rank_table(flow_df, "한국 섹터", top_n=5),
            "global_top":        build_today_flow_rank_table(flow_df, "글로벌",    top_n=1),
            "local_top":         build_today_flow_rank_table(flow_df, "국내상장 대표 ETF", top_n=1),
            "us_swing_top3":     build_today_flow_rank_table(flow_df, "미국 섹터", score_col="스윙점수", top_n=3),
            "kr_swing_top3":     build_today_flow_rank_table(flow_df, "한국 섹터", score_col="스윙점수", top_n=3),
            "global_swing_top":  build_today_flow_rank_table(flow_df, "글로벌",    score_col="스윙점수", top_n=1),
            "sector_rotation_df": sector_rotation_df,
        }
    else:
        # ── 전체 모드: ETF/섹터 + 테마종목 전부 재계산 ──
        clear_today_market_flow_snapshot_cache(clear_data_cache=True)
        snapshot = get_today_market_flow_snapshot()

    st.session_state[TODAY_MARKET_FLOW_SNAPSHOT_KEY] = snapshot
    st.session_state[TODAY_MARKET_FLOW_LAST_RUN_KEY] = _kst_now
    return snapshot


def add_money_flow_row_to_watchlist(row, is_stock: bool = False):
    """ETF/섹터 행 또는 테마 종목 행을 전광판에 추가.

    is_stock=True 이면 개별종목으로 취급(kr_stock / us_stock).
    """
    ticker = sanitize_ticker_value(row.get("Ticker", ""))
    if not ticker:
        return False, "티커가 없어 전광판에 보낼 수 없습니다."
    if is_in_watchlist(ticker):
        return False, f"{ticker}는 이미 전광판에 등록되어 있습니다."

    # ETF 이름 > 종목명 > 섹터 순으로 이름 결정
    name = sanitize_asset_name(
        row.get("ETF 이름", "") or row.get("종목명", "") or row.get("섹터", ""),
        ticker,
    )
    if is_stock:
        default_asset_class = "kr_stock" if is_kr_listed(ticker) else "us_stock"
        is_etf_flag = False
    else:
        default_asset_class = "kr_etf" if is_kr_listed(ticker) else "us_etf_other"
        is_etf_flag = True
    asset_class = infer_asset_class_for_ticker(ticker, default_asset_class)
    st.session_state.watchlist.append(sanitize_watchlist_item({
        "name": name,
        "ticker": ticker,
        "is_etf": is_etf_flag,
        "asset_class": asset_class,
        "fin_score": 0,
    }))
    persist_watchlist()
    return True, f"{name} ({ticker})를 전광판에 추가했습니다."


_LWC_CHART_OPTIONS = {
    "layout": {
        "background": {"type": "solid", "color": "transparent"},
        "textColor": "#94a3b8",
    },
    "grid": {
        "vertLines": {"color": "#1e293b"},
        "horzLines": {"color": "#1e293b"},
    },
    "crosshair": {"mode": 1},
    "rightPriceScale": {"borderColor": "#334155"},
    "timeScale": {"borderColor": "#334155", "timeVisible": False},
}


def render_lwc_candlestick(df: pd.DataFrame, avg_price: float = 0.0, key: str = "lwc_candle") -> bool:
    """TradingView Lightweight Charts 캔들스틱 + MA 라인 렌더링.

    df 컬럼: Open, High, Low, Close, MA5, MA20, MA50, MA120
    Returns True if rendered, False if fallback needed.
    """
    if not _LWC_AVAILABLE or df is None or df.empty:
        return False

    def _to_lwc_time(idx):
        try:
            return idx.strftime("%Y-%m-%d")
        except Exception:
            return str(idx)[:10]

    candle_data = [
        {"time": _to_lwc_time(t), "open": float(o), "high": float(h),
         "low": float(l), "close": float(c)}
        for t, o, h, l, c in zip(
            df.index, df["Open"], df["High"], df["Low"], df["Close"]
        )
        if all(pd.notna(v) for v in [o, h, l, c])
    ]
    if not candle_data:
        return False

    def _ma_series(col_name, color, width=1, dash=False):
        if col_name not in df.columns:
            return None
        data = [
            {"time": _to_lwc_time(t), "value": float(v)}
            for t, v in zip(df.index, df[col_name])
            if pd.notna(v)
        ]
        opts = {"color": color, "lineWidth": width, "title": col_name}
        if dash:
            opts["lineStyle"] = 2   # dashed
        return {"type": "Line", "data": data, "options": opts}

    series = [
        {
            "type": "Candlestick",
            "data": candle_data,
            "options": {
                "upColor": "#22c55e", "downColor": "#ef4444",
                "borderUpColor": "#22c55e", "borderDownColor": "#ef4444",
                "wickUpColor": "#22c55e", "wickDownColor": "#ef4444",
            },
        },
    ]
    for ma in [
        _ma_series("MA5",   "#22c55e", 1),
        _ma_series("MA20",  "#fbbf24", 2),
        _ma_series("MA50",  "#60a5fa", 2),
        _ma_series("MA120", "#94a3b8", 1, dash=True),
    ]:
        if ma:
            series.append(ma)

    # 평단가 기준선
    if avg_price and avg_price > 0:
        series.append({
            "type": "Line",
            "data": [
                {"time": candle_data[0]["time"],  "value": avg_price},
                {"time": candle_data[-1]["time"], "value": avg_price},
            ],
            "options": {"color": "#2ecc71", "lineWidth": 1,
                        "lineStyle": 2, "title": "평단가"},
        })

    chart_opts = {**_LWC_CHART_OPTIONS, "height": 600}
    renderLightweightCharts([{"chart": chart_opts, "series": series}], key=key)
    return True


def render_precision_candlestick_chart(df: pd.DataFrame, avg_price: float = 0.0, key: str = "precision_candle"):
    if df is None or df.empty:
        st.info("표시할 가격 데이터가 없습니다.")
        return
    if render_lwc_candlestick(df, avg_price=avg_price, key=key):
        return
    fig = go.Figure(data=[go.Candlestick(
        x=df.index, open=df["Open"], high=df["High"],
        low=df["Low"], close=df["Close"], name="Price",
    )])
    for col, color, width, dash in [
        ("MA5", "#22c55e", 1.4, None),
        ("MA20", "#fbbf24", 2, None),
        ("MA50", "#60a5fa", 1.6, None),
        ("MA120", "#94a3b8", 1.5, "dot"),
    ]:
        if col in df.columns:
            fig.add_trace(go.Scatter(
                x=df.index,
                y=df[col],
                line=dict(color=color, width=width, dash=dash),
                name=col,
            ))
    if avg_price and avg_price > 0:
        fig.add_hline(y=avg_price, line_dash="dash", line_color="#2ecc71", annotation_text="내 평단가")
    fig.update_layout(
        template="plotly_dark", height=600,
        xaxis_rangeslider_visible=False,
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
    )
    st.plotly_chart(fig, width='stretch')


def resample_ohlcv_timeframe(df: pd.DataFrame, rule) -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame()
    required_cols = ["Open", "High", "Low", "Close", "Volume"]
    if any(col not in df.columns for col in required_cols):
        return pd.DataFrame()
    source = df[required_cols].copy()
    source.index = pd.to_datetime(source.index)
    source = source.sort_index()
    agg_map = {
        "Open": "first",
        "High": "max",
        "Low": "min",
        "Close": "last",
        "Volume": "sum",
    }
    if isinstance(rule, pd.offsets.MonthEnd) or str(rule).upper() in {"M", "ME"}:
        month_source = source.copy()
        month_source["_year"] = source.index.year
        month_source["_month"] = source.index.month
        out = month_source.groupby(["_year", "_month"], sort=True).agg(agg_map)
        out.index = pd.to_datetime([f"{year}-{month:02d}-01" for year, month in out.index]) + pd.offsets.MonthEnd(0)
        out.index.name = source.index.name
        return out.dropna(subset=["Open", "High", "Low", "Close"])
    try:
        grouped = source.resample(rule)
    except ValueError:
        # Pandas 3 no longer accepts the old "M" month-end alias. Keep a
        # fallback here so Streamlit Cloud and local pandas versions both work.
        if str(rule).upper() in {"M", "ME"}:
            grouped = source.resample(pd.offsets.MonthEnd())
        else:
            raise
    out = grouped.agg(agg_map)
    return out.dropna(subset=["Open", "High", "Low", "Close"])


def get_precision_timeframe_trend(label: str, tf_df: pd.DataFrame, last) -> str:
    close = clean_float(last.get("Close"), np.nan)
    ma5 = clean_float(last.get("MA5"), np.nan)
    ma20 = clean_float(last.get("MA20"), np.nan)
    ma50 = clean_float(last.get("MA50"), np.nan)
    ma120 = clean_float(last.get("MA120"), np.nan)
    row_count = len(tf_df) if tf_df is not None else 0

    if label == "일봉":
        return get_trend(last)

    if label == "주봉":
        if np.isfinite(ma20) and np.isfinite(ma50):
            if ma20 > ma50 and (not np.isfinite(close) or close >= ma20 * 0.98):
                return "🚀정배열(상승)"
            if np.isfinite(close) and close < ma50 and ma20 < ma50:
                return "🌊역배열(하락)"
            return "⏳혼조세"
        if row_count >= 12 and np.isfinite(close) and np.isfinite(ma5):
            return "⏳단기상승" if close >= ma5 else "⏳단기혼조"
        return "자료제한"

    if label == "월봉":
        # 월봉 MA120은 10년 평균이라 정밀관측소 타점 보정에는 과하게 엄격합니다.
        # 월봉은 MA5/MA20(약 5개월/20개월) 중심으로 장기 위치를 봅니다.
        if np.isfinite(ma5) and np.isfinite(ma20):
            if ma5 > ma20 and (not np.isfinite(close) or close >= ma5 * 0.95):
                return "🚀정배열(상승)"
            if np.isfinite(close) and close < ma20 and ma5 < ma20:
                return "🌊역배열(하락)"
            return "⏳혼조세"
        if row_count >= 6 and np.isfinite(close) and np.isfinite(ma5):
            return "⏳단기상승" if close >= ma5 else "⏳단기혼조"
        return "자료제한"

    return get_trend(last)


def build_precision_timeframe_snapshot(label: str, df: pd.DataFrame) -> dict:
    if df is None or df.empty or len(df) < 3:
        return {
            "label": label,
            "state": "자료부족",
            "color": "#64748b",
            "summary": "가격 데이터가 부족해 상위 시간대 해석을 보류합니다.",
        }

    try:
        tf_df = build_indicators(df.copy())
    except Exception:
        tf_df = df.copy()
    if tf_df is None or tf_df.empty or len(tf_df) < 3:
        return {
            "label": label,
            "state": "자료부족",
            "color": "#64748b",
            "summary": "지표 계산에 필요한 데이터가 부족합니다.",
        }

    last, prev = tf_df.iloc[-1], tf_df.iloc[-2]
    close = clean_float(last.get("Close"), np.nan)
    high_ref = clean_float(tf_df["High"].tail(min(len(tf_df), 52)).max(), np.nan)
    dd = (close / high_ref - 1) * 100 if np.isfinite(close) and np.isfinite(high_ref) and high_ref > 0 else np.nan
    trend = get_precision_timeframe_trend(label, tf_df, last)
    macd = get_macd_state(last.get("MACD"), last.get("MACD_Sig"), prev.get("MACD"), prev.get("MACD_Sig"))
    rsi = clean_float(last.get("RSI"), np.nan)
    mfi = clean_float(last.get("MFI"), np.nan)
    pct_b = clean_float(last.get("%B"), np.nan)
    ma5 = clean_float(last.get("MA5"), np.nan)
    ma20 = clean_float(last.get("MA20"), np.nan)
    ma50 = clean_float(last.get("MA50"), np.nan)
    ma20_gap = (close / ma20 - 1) * 100 if np.isfinite(close) and np.isfinite(ma20) and ma20 > 0 else np.nan
    below_ma20 = np.isfinite(ma20_gap) and ma20_gap <= -2.0
    below_ma5 = np.isfinite(close) and np.isfinite(ma5) and ma5 > 0 and close < ma5
    is_uptrend = trend == "🚀정배열(상승)" or trend == "⏳단기상승"
    short_term_pressure = (
        is_uptrend and (
            below_ma20 or
            (label == "일봉" and below_ma5 and np.isfinite(pct_b) and pct_b <= 0.35) or
            macd in ["📉하락주의(데드크로스)", "⏳추세관망"]
        )
    )

    overheat = (
        (np.isfinite(rsi) and rsi >= 70) or
        (np.isfinite(mfi) and mfi >= 80) or
        (np.isfinite(pct_b) and pct_b >= 0.90)
    )
    pullback = (
        is_uptrend and
        (not np.isfinite(rsi) or 42 <= rsi <= 65) and
        (not np.isfinite(pct_b) or 0.25 <= pct_b <= 0.78)
    )
    damage = trend == "🌊역배열(하락)" or (np.isfinite(close) and np.isfinite(ma50) and ma50 > 0 and close < ma50)

    if trend == "자료제한":
        state, color = "자료제한", "#64748b"
        summary = f"{label} 데이터가 짧아 장기 이평 판정은 보류합니다. 차트 길이를 확인하고 일봉/주봉을 우선 참고하세요."
    elif damage:
        state, color = "추세훼손", "#ef4444"
        summary = f"{label} 기준 추세가 약합니다. 일봉 반등만 보고 크게 들어가기보다 구조 회복을 먼저 확인하세요."
    elif overheat and is_uptrend:
        state, color = "상승 과열권", "#f59e0b"
        summary = f"{label}은 상승 추세지만 가격대가 높습니다. 일봉 눌림 신호가 떠도 정찰/분할만 적합합니다."
    elif short_term_pressure:
        state, color = "상승추세 내 조정", "#f59e0b"
        summary = f"{label}은 큰 이평 배열은 상승이지만 현재가는 단기 이평 아래에서 조정 중입니다. 반등 확인 전 신규진입은 보류가 더 맞습니다."
    elif pullback:
        state, color = "상승 눌림권", "#22c55e"
        summary = f"{label}도 상승 추세 안의 눌림권입니다. 일봉 신호와 방향이 맞습니다."
    elif is_uptrend:
        state, color = "상승 유지", "#38bdf8"
        summary = f"{label}은 상승 추세를 유지 중입니다. 다만 실제 타점은 일봉 눌림으로 조절하세요."
    elif trend == "⏳혼조세":
        state, color = "혼조 확인", "#94a3b8"
        summary = f"{label}은 방향 확인이 필요한 구간입니다. 일봉 신호의 신뢰도를 한 단계 낮춰 보세요."
    else:
        state, color = "관찰", "#64748b"
        summary = f"{label} 해석은 중립입니다. 일봉 신호를 단독으로 크게 확대하지 않는 편이 좋습니다."

    return {
        "label": label,
        "state": state,
        "color": color,
        "summary": summary,
        "trend": trend,
        "macd": macd,
        "rsi": rsi,
        "mfi": mfi,
        "pct_b": pct_b,
        "ma20_gap": ma20_gap,
        "dd": dd,
        "rows": len(tf_df),
    }


def build_precision_multi_timeframe_pack(ticker: str, daily_df: pd.DataFrame) -> dict:
    raw_long = pd.DataFrame()
    for period in ("10y", "max", "5y", "2y"):
        try:
            candidate = load_price_df(ticker, period)
        except Exception:
            candidate = pd.DataFrame()
        if candidate is not None and not candidate.empty and len(candidate) > len(raw_long):
            raw_long = candidate
        if raw_long is not None and not raw_long.empty and len(raw_long) >= 520:
            break
    if raw_long is None or raw_long.empty:
        raw_long = daily_df.copy() if daily_df is not None else pd.DataFrame()

    weekly_raw = resample_ohlcv_timeframe(raw_long, "W-FRI")
    monthly_raw = resample_ohlcv_timeframe(raw_long, pd.offsets.MonthEnd())
    weekly_df = build_indicators(weekly_raw.tail(260)) if not weekly_raw.empty else pd.DataFrame()
    monthly_df = build_indicators(monthly_raw.tail(180)) if not monthly_raw.empty else pd.DataFrame()

    return {
        "일봉": {"df": daily_df, "snapshot": build_precision_timeframe_snapshot("일봉", daily_df)},
        "주봉": {"df": weekly_df, "snapshot": build_precision_timeframe_snapshot("주봉", weekly_df)},
        "월봉": {"df": monthly_df, "snapshot": build_precision_timeframe_snapshot("월봉", monthly_df)},
    }


def get_precision_mtf_bias(mtf_pack: dict, c: dict) -> dict:
    weekly = (mtf_pack.get("주봉") or {}).get("snapshot", {})
    monthly = (mtf_pack.get("월봉") or {}).get("snapshot", {})
    decision_code = str(c.get("decision_code", ""))
    is_entry_like = decision_code in {
        "QUALITY_PULLBACK_ENTRY",
        "TREND_PULLBACK_EXPLORE",
        "S_PULLBACK_ENTRY",
        "NEW_ENTRY_LEADER",
        "BREAKOUT_52W_ENTRY",
        "EARLY_REVERSAL_ENTRY",
        "OVERSOLD_NEW_ENTRY",
    }
    states = [weekly.get("state", ""), monthly.get("state", "")]
    if any(state == "추세훼손" for state in states):
        return {
            "label": "상위 시간대 경고",
            "color": "#ef4444",
            "text": "주봉/월봉 중 하나가 추세훼손입니다. 일봉 반등은 짧게 보고 신규 비중 확대는 보류가 안전합니다.",
        }
    if any(state == "상승 과열권" for state in states):
        return {
            "label": "정찰만 적합",
            "color": "#f59e0b",
            "text": "일봉 눌림 신호가 있어도 주봉/월봉 가격대가 높습니다. 풀진입이 아니라 목표비중의 1/3 이하 정찰 접근이 맞습니다.",
        }
    if is_entry_like and all(state in ("상승 눌림권", "상승 유지", "자료부족", "자료제한") for state in states):
        return {
            "label": "상위 시간대 우호",
            "color": "#22c55e",
            "text": "일봉 신호와 주봉/월봉 흐름이 크게 충돌하지 않습니다. 그래도 실행은 분할 기준을 우선합니다.",
        }
    return {
        "label": "중립 확인",
        "color": "#64748b",
        "text": "상위 시간대가 강한 반대 신호를 내지는 않습니다. 일봉 판정과 포지션 사이징을 함께 보세요.",
    }


def apply_precision_mtf_decision_guard(c: dict, mtf_pack: dict, has_pos: bool = False) -> dict:
    """Downgrade aggressive new-entry labels when weekly/monthly are too hot."""
    if not isinstance(c, dict):
        return c
    guarded = dict(c)
    bias = get_precision_mtf_bias(mtf_pack, guarded) if mtf_pack else {
        "label": "",
        "color": "#64748b",
        "text": "",
    }
    guarded["mtf_bias_label"] = bias.get("label", "")
    guarded["mtf_bias_text"] = bias.get("text", "")
    guarded["mtf_bias_color"] = bias.get("color", "#64748b")

    decision_code = str(guarded.get("decision_code", "") or "")
    decision_label = str(guarded.get("dec", "") or "")
    if any(word in decision_label for word in ("금지", "차단", "보류", "대기", "관망", "정리대상")):
        return guarded
    entry_like_codes = {
        "S_PULLBACK_ENTRY",
        "S_PULLBACK_ADD_ON",
        "QUALITY_PULLBACK_ENTRY",
        "TREND_PULLBACK_EXPLORE",
        "NEW_ENTRY_LEADER",
        "BREAKOUT_52W_ENTRY",
        "EARLY_REVERSAL_ENTRY",
        "UPTREND_PULLBACK_DCA",
        "COST_MINUS_3_7_DCA",
        "COST_MINUS_7_15_CONDITIONAL_DCA",
        "A_GRADE_TECH_REBOUND",
    }
    is_entry_like = (
        decision_code in entry_like_codes
        or any(word in decision_label for word in ("S급", "탑승", "분할매수", "추매", "진입"))
    )
    if not is_entry_like:
        return guarded

    bias_label = str(bias.get("label", "") or "")
    if has_pos and bias_label in ("상위 시간대 경고", "정찰만 적합"):
        if bias_label == "상위 시간대 경고":
            mtf_note = "상위 시간대 추세훼손: 기존 보유 분할 신호는 유지하되 추가매수보다 손절선과 훼손 원인 점검이 우선입니다."
        else:
            mtf_note = "상위 시간대 과열: 기존 보유 분할 신호는 유지하되 부족분 전체가 아니라 1차/소액 중심으로 제한하세요."
        old_hint = str(guarded.get("sizing_hint", "") or "")
        guarded["sizing_hint"] = f"{old_hint} / {mtf_note}" if old_hint else mtf_note
        return guarded

    old_reasons = tuple(guarded.get("decision_reasons") or ())
    if bias_label == "상위 시간대 경고":
        guarded.update({
            "dec": "⚠️상위시간대 경고: 신규/추매 보류",
            "col": "#d97706",
            "decision_code": "MTF_DAMAGE_NO_ADD",
            "decision_group": "caution",
            "decision_reasons": (
                f"기존 신호: {decision_label}",
                bias.get("text", "주봉/월봉 흐름이 일봉 신호와 충돌합니다."),
                "상위 시간대 회복 전까지 신규 비중 확대는 보류",
            ) + old_reasons[:2],
            "sizing_hint": "상위 시간대 추세훼손: 손절선과 원인 점검이 우선입니다. 신규/추매는 구조 회복 후 다시 판단하세요.",
        })
    elif bias_label == "정찰만 적합":
        guarded.update({
            "dec": "🟡상위과열 눌림: 1차 정찰만",
            "col": "#f59e0b",
            "decision_code": "MTF_OVERHEAT_SCOUT_ONLY",
            "decision_group": "caution",
            "decision_reasons": (
                f"기존 신호: {decision_label}",
                bias.get("text", "주봉/월봉 가격대가 높아 풀진입보다 정찰만 적합합니다."),
                "부족분 전체 매수가 아니라 1차 정찰 후 MA20/FVG/종가 확인",
            ) + old_reasons[:2],
            "sizing_hint": "상위 시간대 과열: 부족분 전부가 아니라 1차 정찰(목표비중 부족분의 30% 이하)만 열고, MA20/FVG 지지와 종가 확인 후 추가하세요.",
        })
    return guarded


def render_precision_multi_timeframe_summary(mtf_pack: dict, c: dict):
    if not mtf_pack:
        return
    bias = get_precision_mtf_bias(mtf_pack, c)
    st.markdown(
        f"""
<div class='info-panel' style='border-left:5px solid {bias['color']}; margin-bottom:12px;'>
<b>상위 시간대 보정: {escape_html_value(bias['label'])}</b><br>
{escape_html_value(bias['text'])}
</div>
        """,
        unsafe_allow_html=True,
    )
    rows = []
    for label in ["일봉", "주봉", "월봉"]:
        snap = (mtf_pack.get(label) or {}).get("snapshot", {})
        rows.append({
            "구분": label,
            "상태": snap.get("state", "-"),
            "추세": snap.get("trend", "-"),
            "MACD": snap.get("macd", "-"),
            "RSI": "-" if not np.isfinite(clean_float(snap.get("rsi"), np.nan)) else f"{clean_float(snap.get('rsi')):.0f}",
            "MFI": "-" if not np.isfinite(clean_float(snap.get("mfi"), np.nan)) else f"{clean_float(snap.get('mfi')):.0f}",
            "%B": "-" if not np.isfinite(clean_float(snap.get("pct_b"), np.nan)) else f"{clean_float(snap.get('pct_b')):.2f}",
            "MA20 이격": "-" if not np.isfinite(clean_float(snap.get("ma20_gap"), np.nan)) else f"{clean_float(snap.get('ma20_gap')):+.1f}%",
            "고점대비": "-" if not np.isfinite(clean_float(snap.get("dd"), np.nan)) else f"{clean_float(snap.get('dd')):+.1f}%",
            "해석": snap.get("summary", "-"),
        })
    st.dataframe(pd.DataFrame(rows), width='stretch', hide_index=True)


