def _fallback_flow_subtheme(theme_name="", candidate_name=""):
    theme = _flow_text(theme_name)
    candidate = _flow_text(candidate_name)
    return FLOW_FALLBACK_SUBTHEMES.get(theme) or FLOW_FALLBACK_SUBTHEMES.get(candidate, "")


def _fallback_flow_representative(theme_name="", subtheme_name="", candidate_name=""):
    theme = _flow_text(theme_name)
    subtheme = _flow_text(subtheme_name)
    candidate = _flow_text(candidate_name)
    for key in [(theme, subtheme), (candidate, subtheme)]:
        if key in FLOW_FALLBACK_REPRESENTATIVES:
            return FLOW_FALLBACK_REPRESENTATIVES[key]
    return ""


def _unified_flow_action(cluster_label="", theme_signal="", sector_state="", theme_state="",
                         sub_state="", price_level=np.nan, cluster_timing=""):
    """cluster_label(강도: 주도/부상/소외/중립)과 cluster_timing(타이밍: 진입 가능/눌림 대기/과열/하락 중)을
    독립 입력으로 받아, 강도와 타이밍이 둘 다 맞을 때만 '정밀관측'으로 묶는다."""
    text = " ".join(str(x or "") for x in [cluster_label, theme_signal, sector_state, theme_state, sub_state])
    if "하락중 관망" in text or "소외 지속" in text or "급락" in text or str(cluster_timing) == "하락 중":
        return "🔸 관망", "단기 흐름이 꺾인 구간입니다."
    if "극단과열" in text:
        return "🚫 추격금지", "종목 타점에서 과열이 풀릴 때까지 대기합니다."
    if "과열" in text or str(cluster_timing) in {"과열", "눌림 대기"} or (finite_num(price_level) and float(price_level) >= 0.90):
        return "⏳ 눌림대기", "큰 흐름은 강하지만 가격 위치가 높습니다."
    cluster_strong = str(cluster_label) in {"주도", "부상", "진입검토", "부상감시"}
    theme_strong = str(theme_signal) in {"진입검토", "부상감시", "주도 후 조정"}
    if cluster_strong and theme_strong and str(cluster_timing) in {"진입 가능", ""}:
        return "✅ 정밀관측", "연결 흐름과 타이밍이 같이 맞습니다. 종목별 과열/눌림을 확인합니다."
    if cluster_strong or theme_strong:
        return "👀 관심등록", "돈은 쏠리는 중입니다. 대표주를 전광판/정밀관측소에 올려두고 타이밍을 지켜봅니다."
    if str(cluster_label) == "주도 후 조정" or str(theme_signal) == "주도 후 조정":
        return "⏳ 눌림대기", "주도 테마지만 단기 조정 확인이 필요합니다."
    return "🔸 관망", "섹터·테마·타점 중 하나 이상이 아직 약합니다."


def _render_cluster_card(col, cl: dict, rank: int, delta: float | None = None):
    """클러스터 카드 단위 HTML 렌더링 — 하단에 구성 ETF 상세 표시."""
    rs3m   = cl["rs3m"]
    rsmom  = cl["rsmom"]
    is_sur = cl["is_surging"]
    qcnt   = cl["qcnt"]
    n      = cl["n"]
    strength_score = float(cl.get("strength_score", cl.get("heat", 0.0)) or 0.0)
    flow_label = cl.get("flow_label", "중립")
    timing_state = cl.get("timing_state", "확인 필요")
    breadth = float(cl.get("breadth", cl.get("pos_frac", 0.0)) or 0.0)
    avg_r1m = cl.get("r1m", float("nan"))
    avg_r2w = cl.get("r2w", float("nan"))
    volume_growth = cl.get("volume_growth", float("nan"))
    rank_bonus = float(cl.get("rank_bonus", 0.0) or 0.0)
    overheat_penalty = float(cl.get("overheat_penalty", 0.0) or 0.0)
    pullback_penalty = float(cl.get("pullback_penalty", 0.0) or 0.0)

    # ── ① 강도(쏠림) 색상 — 순수 3개월 RS·확산도 기준, 단기 흐름과 무관 ──
    if flow_label == "주도":
        main_clr = "#22c55e"
    elif flow_label == "부상":
        main_clr = "#60a5fa"
    elif flow_label == "소외":
        main_clr = "#ef4444"
    else:
        main_clr = "#94a3b8"
    border_clr = "#f97316" if is_sur else main_clr

    # ── ② 타이밍 색상 — 1M/2W·가격위치 기준, 강도와 별개 ──
    TIMING_COLORS = {
        "진입 가능": "#22c55e",
        "확인 필요": "#94a3b8",
        "눌림 대기": "#fbbf24",
        "과열":     "#fbbf24",
        "하락 중":   "#ef4444",
    }
    timing_clr = TIMING_COLORS.get(timing_state, "#94a3b8")

    # ── RS 방향 ──
    if   rsmom > 0.02: mom_clr, mom_sym = "#22c55e", "↑"
    elif rsmom > -0.02: mom_clr, mom_sym = "#fbbf24", "→"
    else:               mom_clr, mom_sym = "#ef4444",  "↓"

    # ── 4분면 도트 요약 ──
    QDOT = {"주도": "🟢", "개선": "🔵", "약화": "🟠", "소외": "🔴"}
    quad_str = " ".join(f"{QDOT[q]}{qcnt[q]}" for q in ["주도", "개선", "약화", "소외"] if qcnt.get(q, 0))

    # ── 배지: 강도 라벨과 타이밍 상태를 서로 다른 배지로 분리 표시 ──
    badge = (" <span style='background:#f97316;color:#fff;font-size:0.60em;"
             "padding:1px 5px;border-radius:3px;'>🔥쏠림+진입가능</span>") if is_sur else ""
    label_badge = (
        f" <span style='background:{main_clr}22;color:{main_clr};font-size:0.60em;"
        "padding:1px 5px;border-radius:3px;' title='강도: 돈이 쏠리는 정도'>"
        f"강도·{flow_label}</span>"
        f" <span style='background:{timing_clr}22;color:{timing_clr};font-size:0.60em;"
        "padding:1px 5px;border-radius:3px;' title='타이밍: 지금 들어가도 되는가'>"
        f"타이밍·{timing_state}</span>"
    )

    # ── 강도 막대 (-20~+40점 → 0~100%) ──
    bar_pct = min(100, max(4, int((strength_score + 20) / 60 * 100)))

    # ── 단기 확인 수치 ──
    r1m_html = ""
    if finite_num(avg_r1m):
        r1m_clr = "#22c55e" if avg_r1m > 0 else "#ef4444"
        r1m_html = (f"<span style='color:{r1m_clr};font-size:0.68em;'>"
                    f"&nbsp;1M {avg_r1m*100:+.1f}%</span>")
    r2w_html = ""
    if finite_num(avg_r2w):
        r2w_clr = "#22c55e" if avg_r2w > 0 else "#ef4444"
        r2w_html = (f"<span style='color:{r2w_clr};font-size:0.68em;'>"
                    f"&nbsp;2W {avg_r2w*100:+.1f}%</span>")
    vol_html = f"거래 {volume_growth*100:+.0f}%" if finite_num(volume_growth) else "거래 -"
    rank_html = f"랭킹 +{rank_bonus:.1f}" if rank_bonus else "랭킹 -"
    # ── 타이밍 사유 (왜 그 timing_state인지) ──
    timing_reason_bits = []
    if overheat_penalty > 0.1:
        timing_reason_bits.append(f"과열 -{overheat_penalty:.1f}")
    if pullback_penalty > 0.1:
        timing_reason_bits.append(f"눌림 -{pullback_penalty:.1f}")
    timing_reason_html = (
        f"<div style='font-size:0.66em;color:{timing_clr};margin-top:3px;'>"
        f"⏱ 타이밍 · {timing_state}{r1m_html}{r2w_html}"
        + (f"&nbsp;<span style='color:#fca5a5;'>({' / '.join(timing_reason_bits)})</span>" if timing_reason_bits else "")
        + "</div>"
    )

    # ── 구성 ETF 상세 (최근 확인이 강한 순 정렬) ──
    tickers = cl.get("tickers", [])
    ticker_codes = [str(t.get("ticker", "")).upper() for t in tickers if isinstance(t, dict)]
    market_hint = "한국 섹터" if any(is_kr_listed(t) for t in ticker_codes) else "미국 섹터"
    bridge = resolve_flow_theme_bridge(cl.get("name", ""), " ".join(ticker_codes), market_hint)
    bridge_html = ""
    if bridge.get("label"):
        bridge_html = (
            "<div style='font-size:0.66em;color:#bae6fd;margin-top:4px;'>"
            f"연결테마: {html.escape(str(bridge.get('label', '')))}</div>"
        )
    ticker_rows_html = ""
    if tickers:
        rows = []
        for t in tickers:
            q    = QDOT.get(t["quad"], "⚪")
            rm   = t["rsmom"]
            arr  = "↑" if rm > 0.01 else ("↓" if rm < -0.01 else "→")
            aclr = "#4ade80" if rm > 0.01 else ("#f87171" if rm < -0.01 else "#fbbf24")
            r3   = t["rs3m"] * 100
            r1   = t.get("r1m", float("nan"))
            rclr = "#4ade80" if r3 > 2 else ("#f87171" if r3 < -2 else "#fbbf24")
            r1_txt = f" 1M {r1*100:+.0f}%" if finite_num(r1) else ""
            label = t.get("name", t.get("ticker", "?"))
            rows.append(
                f"<span style='display:inline-block;margin:1px 4px 1px 0;white-space:nowrap;'>"
                f"{q}&nbsp;"
                f"<span style='color:#cbd5e1;'>{label}</span>"
                f"&nbsp;<span style='color:{rclr};font-size:0.9em;'>{r3:+.0f}%</span>"
                f"<span style='color:#94a3b8;font-size:0.82em;'>{r1_txt}</span>"
                f"<span style='color:{aclr};font-size:0.85em;'>{arr}</span>"
                f"</span>"
            )
        ticker_rows_html = (
            "<div style='border-top:1px solid #334155;margin-top:7px;padding-top:5px;"
            "font-size:0.63em;line-height:1.8;'>"
            + "".join(rows)
            + "</div>"
        )

    col.markdown(
        f"<div style='padding:10px 10px 8px;border-radius:10px;background:#1e293b;"
        f"border:1.5px solid {border_clr}55;'>"
        # 헤더
        f"<div style='font-size:0.71em;color:#94a3b8;margin-bottom:3px;'>"
        f"#{rank}&nbsp;{cl['name']}{badge}{label_badge}</div>"
        # ① 강도(쏠림) — 3개월 RS 기준, 단기 변동에 흔들리지 않는 점수
        f"<div style='font-size:1.05em;font-weight:700;color:{main_clr};'>"
        f"💰 강도 {strength_score:+.1f}점"
        + (
            f"<span style='font-size:0.65em;color:{'#4ade80' if delta > 0 else '#f87171' if delta < 0 else '#94a3b8'}"
            f";margin-left:5px;font-weight:500;' title='어제 대비 (파일 기준)'>{'▲' if delta > 0 else '▼' if delta < 0 else '─'}"
            f"{abs(delta):.1f} 어제比</span>"
            if delta is not None else ""
        )
        + "</div>"
        # RS 방향
        f"<div style='font-size:0.78em;color:{mom_clr};margin-bottom:5px;'>"
        f"{mom_sym}&nbsp;RS {rs3m*100:+.1f}% / 방향 {rsmom*100:+.1f}%</div>"
        # 강도 막대
        f"<div style='background:#0f172a;border-radius:3px;height:5px;margin-bottom:5px;'>"
        f"<div style='width:{bar_pct}%;height:5px;background:{main_clr};border-radius:3px;'>"
        f"</div></div>"
        f"<div style='font-size:0.68em;color:#94a3b8;'>"
        f"확산 {breadth*100:.0f}% · {vol_html} · {rank_html}</div>"
        # ② 타이밍(진입 가능 여부) — ①과 분리된 별도 영역
        f"{timing_reason_html}"
        f"{bridge_html}"
        # 4분면 분포 요약
        f"<div style='font-size:0.70em;color:#64748b;'>{quad_str}&nbsp;({n}개)</div>"
        # ETF 상세
        + ticker_rows_html
        + f"</div>",
        unsafe_allow_html=True,
    )


_CLUSTER_STRENGTH_HISTORY_PATH = Path(__file__).parent / "cache" / "cluster_strength_history.json"
_CLUSTER_STRENGTH_HISTORY_KEEP_DAYS = 14


def _load_cluster_strength_history() -> dict:
    """일자별 강도 점수 스냅샷을 파일에서 읽어온다. {날짜: {클러스터명: strength_score}}.

    세션 상태(st.session_state)는 새로고침/재방문 시 사라져 '어제 대비'를
    추적할 수 없으므로, 파일에 영속화해 진짜 일자 간 비교를 가능하게 한다.
    """
    try:
        with open(_CLUSTER_STRENGTH_HISTORY_PATH, encoding="utf-8") as f:
            raw = json.load(f)
        return raw if isinstance(raw, dict) else {}
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def _save_cluster_strength_snapshot(date_key: str, scores: dict) -> None:
    """오늘 날짜 키로 강도 점수 스냅샷을 저장하고 오래된 기록은 정리한다."""
    history = _load_cluster_strength_history()
    history[date_key] = {name: float(v) for name, v in scores.items()}
    # 최근 N일치만 유지
    kept_keys = sorted(history.keys())[-_CLUSTER_STRENGTH_HISTORY_KEEP_DAYS:]
    history = {k: history[k] for k in kept_keys}
    try:
        _CLUSTER_STRENGTH_HISTORY_PATH.parent.mkdir(parents=True, exist_ok=True)
        with open(_CLUSTER_STRENGTH_HISTORY_PATH, "w", encoding="utf-8") as f:
            json.dump(history, f, ensure_ascii=False, indent=2)
    except OSError:
        pass


def _prev_cluster_strength_scores(today_key: str) -> dict:
    """오늘이 아닌 가장 최근 날짜의 강도 점수 스냅샷을 돌려준다 ('어제 대비' 비교용)."""
    history = _load_cluster_strength_history()
    other_days = sorted(k for k in history.keys() if k != today_key)
    if not other_days:
        return {}
    return history[other_days[-1]]


def _build_cluster_list(rotation_df, clusters: dict) -> list:
    """rotation_df + clusters 로 클러스터 집계 리스트 생성 (내부 헬퍼).

    단순 RS 강도보다 실제 접근 가능성을 우선한다.
    """
    df = rotation_df.copy()
    if "RS_3m" in df.columns and "RS(3M)" not in df.columns:
        df["RS(3M)"] = df["RS_3m"]
    if "로테이션" in df.columns and "사분면" not in df.columns:
        df["사분면"] = df["로테이션"]
    for col, default in {
        "1개월수익률": np.nan,
        "2주수익률": np.nan,
        "단기가속도": np.nan,
        "거래량증가": np.nan,
        "가격수준": np.nan,
        "점수_랭킹보조": 0.0,
        "네이버랭킹": "",
        "돈흐름점수": np.nan,
        "상태": "",
    }.items():
        if col not in df.columns:
            df[col] = default

    def _num(value, default=np.nan):
        return float(value) if finite_num(value) else default

    def _clip_score(value, low, high):
        if not finite_num(value):
            return 0.0
        return min(max(float(value), low), high)

    def _avg(values):
        vals = [float(v) for v in values if finite_num(v)]
        return float(np.mean(vals)) if vals else float("nan")

    def _positive_fraction(values, threshold=0.0):
        vals = [float(v) for v in values if finite_num(v)]
        if not vals:
            return 0.0
        return sum(v >= threshold for v in vals) / len(vals)

    t2: dict = {}
    for _, r in df.iterrows():
        t     = str(r.get("Ticker", "")).upper()
        rs3m  = r.get("RS(3M)",   np.nan)
        rsmom = r.get("RS모멘텀", np.nan)
        quad  = str(r.get("사분면", "-"))
        r1m   = r.get("1개월수익률", np.nan)
        r2w   = r.get("2주수익률", np.nan)
        short_accel = r.get("단기가속도", np.nan)
        volume_growth = r.get("거래량증가", np.nan)
        price_level = r.get("가격수준", np.nan)
        rank_bonus = r.get("점수_랭킹보조", 0.0)
        flow_score = r.get("돈흐름점수", np.nan)
        # 섹터명 우선, 없으면 ticker 코드 그대로
        name  = str(r.get("섹터", r.get("name", t)))
        if finite_num(rs3m) and finite_num(rsmom):
            t2[t] = {
                "rs3m":  float(rs3m),
                "rsmom": float(rsmom),
                "quad":  quad,
                "r1m":   _num(r1m),
                "r2w":   _num(r2w),
                "short_accel": _num(short_accel),
                "volume_growth": _num(volume_growth),
                "price_level": _num(price_level),
                "rank_bonus": _num(rank_bonus, 0.0),
                "flow_score": _num(flow_score),
                "naver_rank": str(r.get("네이버랭킹", "")),
                "state": str(r.get("상태", "")),
                "name":  name,
                "ticker": t,
            }

    cl_list = []
    for cl_name, cl_tickers in clusters.items():
        matched = [{"ticker": t.upper(), **t2[t.upper()]}
                   for t in cl_tickers if t.upper() in t2]
        if not matched:
            continue
        n         = len(matched)
        avg_rs3m  = float(np.mean([m["rs3m"]  for m in matched]))
        avg_rsmom = float(np.mean([m["rsmom"] for m in matched]))
        avg_r1m   = _avg([m["r1m"] for m in matched])
        avg_r2w   = _avg([m["r2w"] for m in matched])
        avg_short_accel = _avg([m["short_accel"] for m in matched])
        avg_volume_growth = _avg([m["volume_growth"] for m in matched])
        avg_price_level = _avg([m["price_level"] for m in matched])
        rank_vals = [m["rank_bonus"] for m in matched if finite_num(m["rank_bonus"])]
        avg_rank_bonus = float(np.mean(rank_vals)) if rank_vals else 0.0
        max_rank_bonus = float(max(rank_vals)) if rank_vals else 0.0

        qcnt = {"주도": 0, "개선": 0, "약화": 0, "소외": 0}
        for m in matched:
            if m["quad"] in qcnt:
                qcnt[m["quad"]] += 1
        pos_frac = (qcnt["주도"] + qcnt["개선"]) / n
        r1m_pos_frac = _positive_fraction([m["r1m"] for m in matched])
        r2w_pos_frac = _positive_fraction([m["r2w"] for m in matched])
        breadth = pos_frac * 0.45 + r1m_pos_frac * 0.35 + r2w_pos_frac * 0.20

        short_down = (
            (finite_num(avg_r1m) and avg_r1m <= -0.02
             and (not finite_num(avg_r2w) or avg_r2w < 0))
            or (finite_num(avg_r2w) and avg_r2w <= -0.03
                and (not finite_num(avg_r1m) or avg_r1m <= 0))
        )
        short_confirm = (
            finite_num(avg_r1m) and avg_r1m >= 0
            and (not finite_num(avg_r2w) or avg_r2w >= 0)
        )
        overheated_members = [
            m for m in matched
            if finite_num(m["price_level"]) and m["price_level"] >= 0.90
        ]
        # 평균 가격위치만 보면 과열 멤버가 다른 멤버에 희석돼 라벨이 어긋난다
        # (예: SOXX/SMH는 이미 과열경보인데 클러스터 평균은 정상 범위로 보이는 경우).
        is_overheated = (
            (finite_num(avg_price_level) and avg_price_level >= 0.90 and avg_rs3m >= 0.08)
            or (len(overheated_members) / n >= 0.3 and avg_rs3m >= 0.08)
        )

        # ── ① 강도 점수 (돈이 어디로 쏠리는가 — 3개월 RS 기준, 단기 변동에 흔들리지 않음) ──
        lead_score = _clip_score(avg_rs3m * 95, -18, 28)
        momentum_score = _clip_score(avg_rsmom * 130, -20, 26)
        volume_score = _clip_score(avg_volume_growth * 7, -7, 11)
        rank_score = min(max(avg_rank_bonus * 0.8 + max_rank_bonus * 0.7, 0.0), 8.0)
        breadth_score = (breadth - 0.5) * 22
        strength_score = lead_score + momentum_score + volume_score + rank_score + breadth_score

        # 강도 라벨: 1개월/2주 단기 확인을 게이트로 쓰지 않는다
        # ("장기로는 강한데 최근 한 달이 약해서 관망"이라는 모순을 없애기 위함).
        if strength_score >= 12 and breadth >= 0.52:
            flow_label = "주도"
        elif strength_score >= 6 and avg_rsmom >= 0.02 and breadth >= 0.45:
            flow_label = "부상"
        elif strength_score <= -6 and breadth < 0.45:
            flow_label = "소외"
        else:
            flow_label = "중립"

        # ── ② 타이밍 상태 (지금 들어가도 되는가 — 1M/2W/가격위치만으로 독립 판정) ──
        short_score = (
            _clip_score(avg_r1m * 110, -18, 18)
            + _clip_score(avg_r2w * 120, -12, 14)
            + _clip_score(avg_short_accel * 45, -8, 10)
        )
        overheat_penalty = (
            max(0.0, (avg_price_level - 0.86) * 45)
            if finite_num(avg_price_level) else 0.0
        )
        if is_overheated:
            overheat_penalty += 6.0
        pullback_penalty = (
            max(0.0, -avg_r1m * 120) if finite_num(avg_r1m) else 0.0
        ) + (
            max(0.0, -avg_r2w * 140) if finite_num(avg_r2w) else 0.0
        )

        if short_down:
            timing_state = "하락 중"
        elif is_overheated:
            timing_state = "과열"
        elif short_confirm:
            timing_state = "진입 가능"
        elif pullback_penalty > 0.1:
            timing_state = "눌림 대기"
        else:
            timing_state = "확인 필요"

        # 하위 호환을 위해 fit_score/heat은 강도+타이밍 결합 점수로 유지 (정렬 등에서 참조)
        fit_score = strength_score + short_score - overheat_penalty - pullback_penalty
        is_surging = (
            flow_label in {"주도", "부상"}
            and timing_state == "진입 가능"
            and avg_rsmom >= 0.02
        )
        heat = strength_score

        # 최근 확인이 되는 ETF를 먼저 보여준다. 오래 강했지만 한 달 하락 중인 후보는 뒤로 밀린다.
        tickers_detail = sorted(
            matched,
            key=lambda x: (
                _num(x.get("r1m"), -9.0),
                _num(x.get("r2w"), -9.0),
                x["rsmom"],
                x["rs3m"],
            ),
            reverse=True,
        )

        cl_list.append({
            "name": cl_name, "rs3m": avg_rs3m, "rsmom": avg_rsmom,
            "r1m": avg_r1m, "r2w": avg_r2w, "qcnt": qcnt, "n": n,
            "pos_frac": pos_frac, "breadth": breadth,
            "volume_growth": avg_volume_growth,
            "price_level": avg_price_level,
            "rank_bonus": max_rank_bonus,
            "fit_score": fit_score,
            "strength_score": strength_score,
            "timing_state": timing_state,
            "flow_label": flow_label,
            "is_surging": is_surging, "heat": heat,
            "overheat_penalty": overheat_penalty,
            "pullback_penalty": pullback_penalty,
            "score_parts": {
                "주도": lead_score,
                "방향": momentum_score,
                "단기": short_score,
                "거래": volume_score,
                "랭킹": rank_score,
                "확산": breadth_score,
            },
            "tickers": tickers_detail,
        })

    # "어디로 쏠리는가" 랭킹은 단기 변동에 흔들리지 않는 strength_score 기준으로 정렬한다.
    cl_list.sort(key=lambda x: x["strength_score"], reverse=True)
    return cl_list


def _render_market_cluster_row(cl_list: list, top_n: int, market_label: str,
                               rank_offset: int = 0, prev_scores: dict | None = None):
    """한 시장(한국/미국)의 클러스터 상위 top_n 카드 행 렌더."""
    total_all = len(cl_list)
    visible   = cl_list[:top_n]
    if not visible:
        return

    # 시장 레이블 소제목
    surging_here = [c for c in visible if c["is_surging"]]
    fire = " 🔥" if surging_here else ""
    st.markdown(
        f"<div style='font-size:0.82em;font-weight:600;color:#94a3b8;"
        f"margin:6px 0 4px;'>{market_label}{fire} "
        f"<span style='font-weight:400;font-size:0.88em;'>"
        f"({total_all}개 중 상위 {len(visible)}개)</span></div>",
        unsafe_allow_html=True,
    )
    n_cols = min(len(visible), 3)
    cols   = st.columns(n_cols)
    for i, cl in enumerate(visible):
        _prev = (prev_scores or {}).get(cl["name"])
        _delta = (float(cl.get("strength_score", 0)) - float(_prev)) if _prev is not None else None
        _render_cluster_card(cols[i], cl, rank=rank_offset + i + 1, delta=_delta)


def _cluster_timing_axis_value(timing_state: str) -> float:
    """그래프 X축용 타이밍 점수. 높을수록 지금 접근하기 좋다."""
    timing_state = str(timing_state or "")
    return {
        "하락 중": -1.4,
        "과열": -0.7,
        "확인 필요": 0.2,
        "눌림 대기": 0.8,
        "진입 가능": 1.6,
    }.get(timing_state, 0.0)


