def macro_event_window(today):
    today = today or datetime.now(KST).date()
    return today - timedelta(days=AUTO_MACRO_EVENT_LOOKBACK_DAYS), today + timedelta(days=AUTO_MACRO_EVENT_LOOKAHEAD_DAYS)


def parse_macro_event_date(value):
    try:
        return pd.to_datetime(value).date()
    except Exception:
        return None


def macro_event_in_window(event, today):
    window_start, window_end = macro_event_window(today)
    start = parse_macro_event_date(event.get("date"))
    end = parse_macro_event_date(event.get("end_date") or event.get("date"))
    if start is None or end is None:
        return False
    return end >= window_start and start <= window_end


def canonical_macro_event_name(name):
    text = str(name or "").strip()
    low = text.lower()
    if "consumer price index" in low or "core cpi" in low or re.search(r"\bcpi\b", low):
        return "미국 CPI 발표"
    if "producer price index" in low or re.search(r"\bppi\b", low):
        return "미국 PPI 발표"
    if "fomc" in low or "federal funds" in low or "fed interest rate" in low:
        return "FOMC"
    if "non-farm" in low or "nonfarm" in low or "employment situation" in low:
        return "미국 고용지표"
    if "main refinancing rate" in low or "ecb press conference" in low or "monetary policy statement" in low:
        return "ECB 통화정책"
    if "boj" in low or "bank of japan" in low:
        return "BOJ 금융정책결정회의"
    return text


def macro_event_market_for_country(country):
    country = str(country or "").upper()
    if country == "USD":
        return "미국 주식/달러/금리"
    if country == "EUR":
        return "유럽 금리/달러/글로벌 수급"
    if country == "JPY":
        return "엔/금리/글로벌 수급"
    if country == "CNY":
        return "중국/원자재/한국 수출주"
    return "글로벌 수급/원자재"


def macro_event_default_weight(event_name):
    low = str(event_name or "").lower()
    if "fomc" in low:
        return 1.2
    if "cpi" in low or "고용" in event_name:
        return 1.0
    if "ppi" in low or "ecb" in low or "boj" in low:
        return 0.8
    return 0.7


def macro_event_impact_text(event_name):
    name = canonical_macro_event_name(event_name)
    if name == "미국 CPI 발표":
        return "예상 상회: 금리·달러 상승, 나스닥/성장주/레버리지 부담. 예상 하회: 금리 부담 완화와 성장주 반등 재료."
    if name == "미국 PPI 발표":
        return "생산자 물가가 높으면 CPI 재가속 우려로 금리 부담 확대. 낮으면 인플레 둔화 확인 재료."
    if name == "FOMC":
        return "성명·점도표·기자회견이 금리 경로를 바꿀 수 있어 달러, 장기금리, 성장주 변동성이 커집니다."
    if name == "ECB 통화정책":
        return "유로 금리와 달러 흐름에 영향. 매파적이면 글로벌 금리 부담, 완화적이면 위험자산 심리 개선 가능."
    if name == "BOJ 금융정책결정회의":
        return "일본 금리·엔화가 움직이면 글로벌 채권금리와 엔캐리 청산 우려가 커질 수 있습니다."
    if name == "미국 고용지표":
        return "고용이 강하면 금리 인하 기대가 밀리고, 약하면 경기 둔화 우려와 금리 하락 재료가 동시에 생깁니다."
    if "KOSPI 200" in name:
        return "파생 만기 수급으로 장중·종가 변동성이 커질 수 있어 국내 대형주 추격매수는 보수적으로 봅니다."
    if "IPO" in name:
        return "대형 IPO 전후로 성장주 자금이 분산될 수 있어 같은 테마의 단기 수급 공백을 확인합니다."
    return "고영향 일정 전후에는 포지션 확대보다 발표 결과와 시장 반응을 먼저 확인합니다."


def macro_event_context_note(event):
    name = canonical_macro_event_name(event.get("event", ""))
    source = str(event.get("source", ""))
    raw_title = str(event.get("raw_title", "")).strip()
    note = str(event.get("note", "") or "").strip()

    if name == "미국 CPI 발표":
        base = "Core/MoM/YoY 중 컨센서스 대비 방향이 핵심입니다."
    elif name == "미국 PPI 발표":
        base = "CPI보다 한발 앞선 비용 압력 확인용입니다."
    elif name == "FOMC":
        base = "정책금리보다 점도표, 물가 판단, 파월 발언 톤이 더 중요할 수 있습니다."
    elif name == "ECB 통화정책":
        base = "달러 인덱스와 글로벌 금리 방향에 간접 영향을 줍니다."
    elif name == "BOJ 금융정책결정회의":
        base = "국채매입 축소, 금리 인상, 엔화 급등 가능성을 봅니다."
    elif name == "미국 고용지표":
        base = "고용 강도와 임금 압력이 금리 기대를 흔듭니다."
    elif "KOSPI 200" in name:
        base = "종가 부근 외국인/기관 파생 수급 흔들림을 조심합니다."
    else:
        base = note or "-"

    if source == "자동: FF" and raw_title:
        return f"{base} 원문 일정: {raw_title}"
    if source == "fallback":
        return f"{base} 외부 수집 실패 시 보조 일정으로 표시됩니다."
    return note if note and "자동 수집" not in note and "fallback" not in note.lower() else base


def normalize_macro_event(event, source="수동"):
    item = dict(event or {})
    item["event"] = canonical_macro_event_name(item.get("event", ""))
    item.setdefault("end_date", item.get("date"))
    item.setdefault("source", source)
    item.setdefault("weight", macro_event_default_weight(item.get("event", "")))
    item.setdefault("pre_days", 2)
    item.setdefault("post_days", 1)
    item.setdefault("market", "글로벌 수급")
    item.setdefault("note", "-")
    return item


def add_macro_event(events, event, today, source="수동"):
    item = normalize_macro_event(event, source=source)
    if macro_event_in_window(item, today):
        events.append(item)


def second_thursday(year, month):
    first_day = datetime(year, month, 1).date()
    days_to_thursday = (3 - first_day.weekday()) % 7
    return first_day + timedelta(days=days_to_thursday + 7)


def add_months(year, month, offset):
    raw = (year * 12 + (month - 1)) + offset
    return raw // 12, raw % 12 + 1


def build_kospi_expiry_events(today):
    events = []
    for offset in range(-1, 5):
        year, month = add_months(today.year, today.month, offset)
        expiry = second_thursday(year, month)
        events.append({
            "date": expiry.isoformat(),
            "event": "KOSPI 200 옵션/선물 만기",
            "market": "국내 대형주/KOSPI",
            "weight": 0.7,
            "pre_days": 1,
            "post_days": 0,
            "note": "매월 2번째 목요일 기준 자동 계산. 종가 부근 수급 흔들림 주의",
            "source": "자동: 규칙",
        })
    return events


@st.cache_data(ttl=21600, show_spinner=False)
def fetch_fomc_calendar_events(years):
    try:
        res = requests.get(FED_FOMC_CALENDAR_URL, headers={"User-Agent": "Mozilla/5.0"}, timeout=6)
        if res.status_code != 200:
            return []
        text = html.unescape(re.sub(r"<[^>]+>", "\n", res.text))
        lines = [line.strip().replace("\xa0", " ") for line in text.splitlines() if line.strip()]
    except Exception:
        return []

    month_map = {
        "January": 1, "February": 2, "March": 3, "April": 4, "May": 5, "June": 6,
        "July": 7, "August": 8, "September": 9, "October": 10, "November": 11, "December": 12,
        "Jan/Feb": 1, "Apr/May": 4, "Oct/Nov": 10,
    }
    events = []
    for year in years:
        try:
            start_idx = next(i for i, line in enumerate(lines) if line == f"{year} FOMC Meetings")
        except StopIteration:
            continue
        current_month = None
        for line in lines[start_idx + 1:]:
            if re.match(r"^\d{4} FOMC Meetings$", line):
                break
            if line in month_map:
                current_month = month_map[line]
                continue
            date_match = re.match(r"^(\d{1,2})(?:-(\d{1,2}))?\*?$", line)
            if not date_match or current_month is None:
                continue
            start_day = int(date_match.group(1))
            end_day = int(date_match.group(2) or start_day)
            end_month = current_month + 1 if end_day < start_day else current_month
            end_year = year + 1 if end_month > 12 else year
            end_month = 1 if end_month > 12 else end_month
            try:
                start_date = datetime(year, current_month, start_day).date()
                end_date = datetime(end_year, end_month, end_day).date()
            except ValueError:
                continue
            has_sep = "*" in line
            events.append({
                "date": start_date.isoformat(),
                "end_date": end_date.isoformat(),
                "event": "FOMC",
                "market": "미국 주식/달러/금리",
                "weight": 1.2,
                "pre_days": 3,
                "post_days": 1,
                "note": "Fed 공식 일정 자동 수집. " + ("점도표 포함 회의" if has_sep else "성명·기자회견 전후 변동성 확대"),
                "source": "자동: Fed",
            })
    return events


def ff_macro_event_from_title(title, country):
    title = str(title or "").strip()
    event_name = canonical_macro_event_name(title)
    if event_name == title:
        return None
    country = str(country or "").upper()
    return {
        "event": event_name,
        "market": macro_event_market_for_country(country),
        "weight": macro_event_default_weight(event_name),
        "pre_days": 2 if event_name != "FOMC" else 3,
        "post_days": 1,
        "note": macro_event_context_note({"event": event_name, "source": "자동: FF", "raw_title": title}),
        "raw_title": title,
        "source": "자동: FF",
    }


@st.cache_data(ttl=21600, show_spinner=False)
def fetch_forexfactory_major_events():
    try:
        res = requests.get(FOREX_FACTORY_WEEKLY_CALENDAR_URL, headers={"User-Agent": "Mozilla/5.0"}, timeout=6)
        if res.status_code != 200:
            return []
        root = ET.fromstring(res.content)
    except Exception:
        return []

    events = []
    allowed_countries = {"USD", "EUR", "JPY", "CNY", "All"}
    for node in root.findall("event"):
        impact = str(node.findtext("impact") or "").strip()
        country = str(node.findtext("country") or "").strip()
        if impact != "High" or country not in allowed_countries:
            continue
        title = str(node.findtext("title") or "").strip()
        event = ff_macro_event_from_title(title, country)
        if not event:
            continue
        raw_date = str(node.findtext("date") or "").strip()
        try:
            event_date = datetime.strptime(raw_date, "%m-%d-%Y").date()
        except Exception:
            continue
        event["date"] = event_date.isoformat()
        event["end_date"] = event["date"]
        events.append(event)
    return events


def macro_event_source_rank(source):
    source_rank = {"자동: Fed": 0, "자동: FF": 1, "수동": 2, "자동: 규칙": 3, "fallback": 9}
    parts = [p.strip() for p in str(source or "").split("+") if p.strip()]
    if not parts:
        return 5
    return min(source_rank.get(part, 5) for part in parts)


def combine_macro_event_sources(*sources):
    order = ["자동: Fed", "자동: FF", "수동", "자동: 규칙", "fallback"]
    parts = []
    for source in sources:
        for part in str(source or "").split("+"):
            part = part.strip()
            if part and part not in parts:
                parts.append(part)
    if any(part != "fallback" for part in parts):
        parts = [part for part in parts if part != "fallback"]
    return "+".join(sorted(parts, key=lambda part: order.index(part) if part in order else len(order)))


def macro_event_date_range(event):
    start = parse_macro_event_date(event.get("date"))
    end = parse_macro_event_date(event.get("end_date") or event.get("date"))
    if start is None:
        return None, None
    if end is None or end < start:
        end = start
    return start, end


def macro_events_overlap(left, right):
    left_start, left_end = macro_event_date_range(left)
    right_start, right_end = macro_event_date_range(right)
    if None in (left_start, left_end, right_start, right_end):
        return False
    return left_start <= right_end and right_start <= left_end


def merge_macro_events(left, right):
    left_start, left_end = macro_event_date_range(left)
    right_start, right_end = macro_event_date_range(right)
    primary, secondary = (left, right)
    if macro_event_source_rank(right.get("source")) < macro_event_source_rank(left.get("source")):
        primary, secondary = right, left

    merged = dict(primary)
    if None not in (left_start, left_end, right_start, right_end):
        merged["date"] = min(left_start, right_start).isoformat()
        merged["end_date"] = max(left_end, right_end).isoformat()
    merged["weight"] = max(
        float(primary.get("weight", 0.0) or 0.0),
        float(secondary.get("weight", 0.0) or 0.0),
    )
    merged["pre_days"] = max(int(primary.get("pre_days", 0) or 0), int(secondary.get("pre_days", 0) or 0))
    merged["post_days"] = max(int(primary.get("post_days", 0) or 0), int(secondary.get("post_days", 0) or 0))

    primary_source = str(primary.get("source", "") or "").strip()
    secondary_source = str(secondary.get("source", "") or "").strip()
    merged["source"] = combine_macro_event_sources(primary_source, secondary_source)
    return merged


def dedupe_macro_events(events):
    deduped = []
    for event in events:
        name = canonical_macro_event_name(event.get("event", ""))
        match_idx = None
        for idx, old in enumerate(deduped):
            if canonical_macro_event_name(old.get("event", "")) == name and macro_events_overlap(old, event):
                match_idx = idx
                break
        if match_idx is None:
            deduped.append(event)
        else:
            deduped[match_idx] = merge_macro_events(deduped[match_idx], event)
    return deduped


def build_macro_event_candidates(today):
    today = today or datetime.now(KST).date()
    events = []
    for event in MACRO_EVENT_RISK_EVENTS:
        add_macro_event(events, event, today, source=event.get("source", "수동"))
    for event in build_kospi_expiry_events(today):
        add_macro_event(events, event, today, source=event.get("source", "자동: 규칙"))
    years = tuple(sorted({today.year, (today + timedelta(days=AUTO_MACRO_EVENT_LOOKAHEAD_DAYS)).year}))
    for event in fetch_fomc_calendar_events(years):
        add_macro_event(events, event, today, source=event.get("source", "자동: Fed"))
    for event in fetch_forexfactory_major_events():
        add_macro_event(events, event, today, source=event.get("source", "자동: FF"))
    for event in FALLBACK_AUTO_MACRO_EVENTS:
        add_macro_event(events, event, today, source=event.get("source", "fallback"))

    deduped = dedupe_macro_events(events)

    return sorted(
        deduped,
        key=lambda x: (
            parse_macro_event_date(x.get("date")) or datetime.max.date(),
            NEWS_CATEGORY_ORDER.get(x.get("category", ""), 9) if "NEWS_CATEGORY_ORDER" in globals() else 0,
            str(x.get("event", "")),
        ),
    )


def build_macro_event_risk_table(today=None):
    today = today or datetime.now(KST).date()
    rows = []
    total_risk = 0.0
    active_count = 0

    for event in build_macro_event_candidates(today):
        try:
            start = pd.to_datetime(event["date"]).date()
            end = pd.to_datetime(event.get("end_date") or event["date"]).date()
        except Exception:
            continue

        pre_start = start - timedelta(days=int(event.get("pre_days", 0)))
        post_end = end + timedelta(days=int(event.get("post_days", 0)))
        days_to_start = (start - today).days

        if today < pre_start:
            state = "대기"
            applied = 0.0
            timing = f"D-{days_to_start}"
        elif pre_start <= today < start:
            state = "임박"
            applied = float(event.get("weight", 0.0))
            timing = f"D-{days_to_start}"
        elif start <= today <= end:
            state = "당일"
            applied = float(event.get("weight", 0.0)) * 1.25
            timing = "D-Day"
        elif end < today <= post_end:
            state = "잔여"
            applied = float(event.get("weight", 0.0)) * 0.5
            timing = f"D+{(today - end).days}"
        else:
            state = "종료"
            applied = 0.0
            timing = f"D+{(today - end).days}"

        if applied > 0:
            active_count += 1
            total_risk += applied

        rows.append({
            "일정": f"{start:%m/%d}" if start == end else f"{start:%m/%d}~{end:%m/%d}",
            "이벤트": event.get("event", "-"),
            "시장": event.get("market", "-"),
            "상태": state,
            "D-Day": timing,
            "점수": round(applied, 2),
            "영향": macro_event_impact_text(event.get("event", "-")),
            "해석": macro_event_context_note(event),
            "출처": event.get("source", "수동"),
        })

    return pd.DataFrame(rows), round(min(total_risk, 3.0), 2), active_count


@st.cache_data(ttl=300)
def get_macro_analysis():
    tickers = {"10Y 금리": "^TNX", "유가": "CL=F", "환율": "USDKRW=X", "VIX": "^VIX", "MOVE": "^MOVE"}
    results = {}; macro_trend = 0; storm_count = 0

    try:
        data = yf.download(
            list(tickers.values()),
            period="2mo",
            interval="1d",
            progress=False,
            group_by="ticker",
            threads=False,
            auto_adjust=False,
        )
    except Exception:
        data = pd.DataFrame()

    if data.empty:
        return results, 0, 0, 0

    for name, tkr in tickers.items():
        try:
            if isinstance(data.columns, pd.MultiIndex):
                if tkr in data.columns.get_level_values(0):
                    ticker_df = data[tkr]
                elif tkr in data.columns.get_level_values(-1):
                    ticker_df = data.xs(tkr, axis=1, level=-1)
                else:
                    continue
            else:
                ticker_df = data

            close = ticker_df["Close"].ffill().dropna()
            if close.empty:
                continue

            cur = float(close.iloc[-1])
            prev_m = float(close.iloc[-22]) if len(close) >= 22 else float(close.iloc[0])
            if prev_m == 0:
                continue
        except Exception:
            continue

        chg = ((cur - prev_m) / prev_m) * 100
        icon = "🔺" if chg > 0.5 else ("🔻" if chg < -0.5 else "➖")
        if name in ["10Y 금리", "유가", "환율"]:
            if icon == "🔺": macro_trend += 0.5
            elif icon == "🔻": macro_trend -= 0.5
        is_storm = ((name == "VIX" and cur > 30) or (name == "환율" and cur > 1400) or (name == "10Y 금리" and cur > 4.7))
        if is_storm: storm_count += 1
        results[name] = {"val": cur, "icon": icon, "storm": is_storm, "chg": chg}
    move_val = results.get("MOVE", {"val": 0})["val"]
    move_score = 1.5 if move_val >= 120 else (0.5 if move_val >= 100 else 0)
    _, event_risk, _ = build_macro_event_risk_table()
    final_macro_risk = storm_count + macro_trend + move_score + event_risk
    macro_penalty = 2 if final_macro_risk >= 4 else (1.5 if final_macro_risk >= 2.5 else (0.5 if final_macro_risk >= 1.5 else 0))
    return results, final_macro_risk, macro_penalty, move_val

