def _load_sector_map() -> dict:
    """sector_map.json 에서 섹터 벤치마크 맵을 로드합니다.
    새 종목 추가 시 app.py 대신 sector_map.json 만 수정하면 됩니다."""
    _path = Path(__file__).parent / "sector_map.json"
    try:
        with open(_path, encoding="utf-8") as _f:
            _raw = json.load(_f)
        # "_"로 시작하는 메타 키 제외, 값이 리스트인 항목만 변환
        return {k: tuple(v) for k, v in _raw.items()
                if not k.startswith("_") and isinstance(v, list)}
    except FileNotFoundError:
        import warnings
        warnings.warn(f"sector_map.json 을 찾을 수 없습니다: {_path}")
        return {}

