# SECTION 09: 종목 분석 패널 (정밀 분석)
# build_precision_select_options, render_personal_stock_analysis_panel
# ════════════════════════════════════════════════════════════════════════════

def build_precision_select_options():
    options = [FREE_SEARCH_OPTION]
    option_map = {FREE_SEARCH_OPTION: {"type": "free"}}
    seen_labels = set(options)

    for item in st.session_state.get("watchlist", []):
        item = sanitize_watchlist_item(item)
        ticker = item.get("ticker", "")
        if not ticker:
            continue

        name = sanitize_asset_name(item.get("name", ticker), ticker)
        label = f"⭐ {name} ({ticker})"
        base_label = label
        suffix = 2
        while label in seen_labels:
            label = f"{base_label} #{suffix}"
            suffix += 1

        options.append(label)
        seen_labels.add(label)
        option_map[label] = {"type": "watchlist", "item": dict(item)}

    for label in TICKER_MAP.keys():
        if label in seen_labels:
            continue
        options.append(label)
        seen_labels.add(label)
        option_map[label] = {"type": "preset"}

    return options, option_map


def find_precision_select_label_by_ticker(ticker, option_map):
    target = normalize_ticker(ticker)
    if not target:
        return None

    for label, meta in option_map.items():
        if meta.get("type") != "watchlist":
            continue
        item = meta.get("item", {})
        if normalize_ticker(item.get("ticker", "")) == target:
            return label

    for label, meta in option_map.items():
        if meta.get("type") == "free":
            continue
        if label in TICKER_MAP and normalize_ticker(TICKER_MAP[label][0]) == target:
            return label
        if normalize_ticker(label) == target:
            return label

    return None


PRECISION_FREE_TICKER_KEY = "precision_free_ticker_input"
PRECISION_FREE_MARKET_KEY = "precision_free_market_option"


def _split_precision_free_ticker(ticker: str) -> tuple[str, str]:
    raw = sanitize_ticker_value(ticker)
    upper = raw.upper()
    if upper.endswith(".KQ"):
        return upper[:-3], "KOSDAQ (.KQ)"
    if upper.endswith(".KS"):
        return upper[:-3], "KOSPI (.KS)"
    return upper, st.session_state.get(PRECISION_FREE_MARKET_KEY, "KOSPI (.KS)")


def set_precision_target_ticker(ticker: str, option_map: dict | None = None) -> str:
    """정밀관측소 선택값을 안정적으로 세팅한다.

    전광판/프리셋에 없는 종목은 자유 종목 탐색 입력값에 고정 저장한다.
    """
    target = sanitize_ticker_value(ticker)
    if not target:
        return ""

    option_map = option_map or build_precision_select_options()[1]
    label = find_precision_select_label_by_ticker(target, option_map)
    if label:
        st.session_state["precision_selected_option"] = label
        return label

    base_ticker, market_option = _split_precision_free_ticker(target)
    st.session_state["precision_selected_option"] = FREE_SEARCH_OPTION
    st.session_state[PRECISION_FREE_TICKER_KEY] = base_ticker
    st.session_state[PRECISION_FREE_MARKET_KEY] = market_option
    st.session_state["_precision_prefill_ticker"] = target
    return FREE_SEARCH_OPTION


def get_saved_fin_score_fast(ticker, is_etf):
    if is_etf: return 0
    key = normalize_ticker(ticker)
    if key in st.session_state.fin_score_map: return int(st.session_state.fin_score_map[key])

    fin_scores_df = load_fin_scores_db()
    matched = fin_scores_df[fin_scores_df["ticker"] == key]

    if not matched.empty:
        row = matched.iloc[0]
        if pd.notna(row["final_score"]):
            score = int(row["final_score"])
            st.session_state.fin_score_map[key] = score
            return score

    return 3


def get_dashboard_market_label(ticker):
    return "한국" if is_kr_listed(ticker) else "미국"


def get_dashboard_type_label(is_etf):
    return "ETF" if clean_bool(is_etf) else "개별주"


def get_dashboard_group_label(ticker, is_etf):
    return f"{get_dashboard_market_label(ticker)} {get_dashboard_type_label(is_etf)}"


def get_dashboard_swing_status_maps():
    swing_df, _ = load_swing_radar_db_safe()
    status_map = {}
    decision_map = {}

    if swing_df is None or swing_df.empty:
        return status_map, decision_map

    for _, row in swing_df.iterrows():
        key = normalize_ticker(row.get("ticker", ""))
        if not key:
            continue
        status_map[key] = str(row.get("status", "") or "").strip() or "-"
        decision_map[key] = str(row.get("decision", "") or "").strip() or "-"

    return status_map, decision_map


def render_dashboard_group_summary(df, group_label):
    if group_label != "전체":
        view_df = df[df["전광판그룹"] == group_label].copy()
    else:
        view_df = df.copy()

    if view_df.empty:
        st.info(f"{group_label}에 표시할 종목이 없습니다.")
        return

    adj = pd.to_numeric(view_df["Adj점수"], errors="coerce")
    if "판정분류" in view_df.columns:
        signal_group = view_df["판정분류"].astype(str)
    else:
        signal_group = view_df["🔥기술적 타점"].astype(str).map(classify_decision_signal)
    buyish_count = int((signal_group == "buyish").sum())
    caution_count = int((signal_group == "caution").sum())

    m1, m2, m3, m4 = st.columns(4)
    m1.metric("표시 종목", f"{len(view_df)}개")
    m2.metric("평균 ADJ", "-" if adj.dropna().empty else f"{adj.mean():.1f}")
    m3.metric("매수/관심 신호", f"{buyish_count}개")
    m4.metric("차단/주의 신호", f"{caution_count}개")

    if "ETF" in group_label:
        show_cols = [
            "시장", "유형", "종목명", "티커", "현재가", "MDD",
            "📌후보등급", "RS", "시장벤치", "기초자산", "기초벤치", "RSI", "MFI", "볼린저 %B",
            "🔥기술적 타점", "핵심근거", "Adj점수"
        ]
    elif "개별주" in group_label:
        show_cols = [
            "시장", "유형", "종목명", "티커", "현재가", "MDD", "재무점수",
            "📌후보등급", "RS", "시장벤치", "섹터RS", "섹터벤치",
            "🔥기술적 타점", "핵심근거", "Adj점수"
        ]
    else:
        show_cols = [
            "시장", "유형", "종목명", "티커", "현재가", "MDD", "재무점수",
            "📌후보등급", "RS", "시장벤치", "기초자산", "기초벤치", "섹터RS", "섹터벤치",
            "🔥기술적 타점", "핵심근거", "Adj점수"
        ]
    st.dataframe(view_df[[c for c in show_cols if c in view_df.columns]], width='stretch', height=640, hide_index=True)


def build_precision_narrative(name, tkr, c, fin_score, has_p, my_p):
    """
    정밀관측소 차트 아래 표시할 종합 서술형 해설.
    외부 API 없이 이미 계산된 c 딕셔너리와 fin_score만 사용합니다.
    """
    dec         = c.get("dec", "")
    grade       = c.get("grade", "")
    t_score     = c.get("t_score", 0)
    tech_total  = c.get("tech_total", 0)
    trend       = c.get("trend", "")
    rs_label    = c.get("rs_label", "")
    rs_slope    = c.get("rs_slope_label", "")
    rsi         = c.get("rsi", 0.0)
    mfi         = c.get("mfi", 0.0)
    pct_b       = c.get("pct_b", 0.0)
    macd        = c.get("macd", "")
    sqz         = c.get("sqz", "")
    ext_struct  = c.get("ext_structure", "")
    int_struct  = c.get("int_structure", "")
    int_event   = c.get("int_event", "None")
    ext_event   = c.get("ext_event", "None")
    fvg_type    = c.get("fvg_type", "없음")
    fvg_active  = c.get("fvg_active", False)
    fvg_top     = c.get("fvg_top", 0)
    fvg_bottom  = c.get("fvg_bottom", 0)
    pd_zone     = c.get("pd_zone", "")
    smc_action  = c.get("smc_action", "")
    smc_insight = c.get("smc_insight", "")
    sector_flow = c.get("sector_flow_state", "-")
    is_52w      = c.get("is_52w_breakout", False)
    rr_ratio    = c.get("rr_ratio")
    rr_target   = c.get("rr_target", 0)
    rr_stop     = c.get("rr_stop", 0)
    rr_target_is_projection = bool(c.get("rr_target_is_projection", False))
    rr_target_source = str(c.get("rr_target_source", "") or "차트 구조 목표가")
    cur_p       = c.get("cur_p", 0)
    day_ret     = c.get("day_ret", 0.0)
    day_ret_label = c.get("day_ret_label", "전일등락")
    regular_day_ret = clean_float(c.get("regular_day_ret"), np.nan)
    live_ref_ret = clean_float(c.get("live_ref_ret"), np.nan)
    vol_ratio   = c.get("vol_ratio", 0.0)
    ma5         = c.get("ma5", 0)
    ma20        = c.get("ma20", 0)
    decision_code = c.get("decision_code", "")

    lines = []

    # ── 1. 현재 판정 한 줄 ──────────────────────────────────
    fin_labels = {4: "💎완성형 우량(4/4)", 3: "✅양호(3/4)", 2: "🔶보통(2/4)", 1: "⚠️주의(1/4)", 0: "🚨위험(0/4)"}
    fin_desc = fin_labels.get(fin_score, f"{fin_score}점")
    lines.append(
        f"<b>📋 현재 판정</b>: <b>{dec}</b> &nbsp;|&nbsp; "
        f"후보등급 {grade} &nbsp;|&nbsp; 종합점수 {t_score}점 "
        f"(기술 {tech_total}점 / 재무 {fin_desc})"
    )

    # ── 2. 기술 구조 ─────────────────────────────────────────
    # 추세
    trend_interp = {
        "🚀정배열(상승)": "장기 정배열 상승 구조",
        "🌊역배열(하락)": "역배열 하락 구조",
        "➡️횡보/혼조": "횡보·혼조 구간",
        "🆕신규상장/자료부족": "상장 초기(MA 미형성)",
    }.get(trend, trend)

    # RSI
    if rsi >= 70:
        rsi_interp = f"RSI <b>{rsi:.0f}</b> — 단기 과열 구간, 조정·횡보 가능성 있음"
    elif rsi >= 60:
        rsi_interp = f"RSI <b>{rsi:.0f}</b> — 강세 유지 중"
    elif rsi >= 45:
        rsi_interp = f"RSI <b>{rsi:.0f}</b> — 눌림 구간, 진입 적합 범위"
    elif rsi >= 30:
        rsi_interp = f"RSI <b>{rsi:.0f}</b> — 약세·바닥 탐색 중"
    else:
        rsi_interp = f"RSI <b>{rsi:.0f}</b> — 극단적 과매도"

    # %B
    if pct_b > 0.82:
        pb_interp = f"%B <b>{pct_b:.2f}</b> — 볼린저 상단 초과, 단기 과열"
    elif pct_b >= 0.75:
        pb_interp = f"%B <b>{pct_b:.2f}</b> — 볼린저 상단 근접"
    elif pct_b >= 0.35:
        pb_interp = f"%B <b>{pct_b:.2f}</b> — 볼린저 중립 구간"
    else:
        pb_interp = f"%B <b>{pct_b:.2f}</b> — 볼린저 하단 근접, 과매도 구간"

    # MFI
    if mfi >= 80:
        mfi_interp = f"MFI <b>{mfi:.0f}</b> — 자금 유입 과열(익절 주의)"
    elif mfi >= 55:
        mfi_interp = f"MFI <b>{mfi:.0f}</b> — 자금 유입 우세"
    elif mfi >= 40:
        mfi_interp = f"MFI <b>{mfi:.0f}</b> — 자금 중립"
    else:
        mfi_interp = f"MFI <b>{mfi:.0f}</b> — 자금 유출 우세"

    # RS slope
    slope_desc = ""
    if rs_slope == "📈RS상승중":
        slope_desc = ", 상대강도 가속 중"
    elif rs_slope == "📉RS하락중":
        slope_desc = ", 상대강도 약화 중(추격 주의)"

    lines.append(
        f"🔧 <b>기술 구조</b>: {trend_interp}, RS {rs_label}{slope_desc}. "
        f"{rsi_interp}. {pb_interp}. {mfi_interp}. "
        f"MACD: <b>{macd}</b> / SQZ: <b>{sqz}</b>."
    )

    # ── 3. SMC 구조 ──────────────────────────────────────────
    smc_parts = [f"외부구조 <b>{ext_struct}</b> / 내부구조 <b>{int_struct}</b>"]
    if int_event and int_event not in ("None", "없음", ""):
        smc_parts.append(f"내부 이벤트: <b>{int_event}</b>")
    if ext_event and ext_event not in ("None", "없음", ""):
        smc_parts.append(f"외부 이벤트: <b>{ext_event}</b>")
    if fvg_type != "없음" and fvg_type:
        fvg_status = "미충족(지지대 유효)" if fvg_active else "이미 터치됨"
        fvg_range = ""
        if fvg_bottom and fvg_top and fvg_bottom > 0:
            fvg_range = f" ({format_currency(fvg_bottom, tkr)}~{format_currency(fvg_top, tkr)})"
        smc_parts.append(f"FVG: <b>{fvg_type}</b> {fvg_status}{fvg_range}")
    smc_parts.append(f"현재 가격대: <b>{pd_zone}</b>")
    if is_52w:
        smc_parts.append("🚀 <b>52주 신고가 돌파</b>")
    lines.append("🛡️ <b>SMC 구조</b>: " + " | ".join(smc_parts))
    if smc_insight:
        lines.append(f"&nbsp;&nbsp;&nbsp;&nbsp;→ {smc_insight}")
    if smc_action:
        lines.append(f"&nbsp;&nbsp;&nbsp;&nbsp;🎯 실행 해석: <b>{smc_action}</b>")

    # ── 4. 수급·가격 흐름 ────────────────────────────────────
    flow_parts = [f"섹터 머니플로우: <b>{sector_flow}</b>"]
    if c.get("live_price_used") and finite_num(regular_day_ret):
        reg_emoji = "🔺" if regular_day_ret > 0 else "🔻"
        flow_parts.append(f"정규장 전일등락: {reg_emoji} <b>{regular_day_ret*100:.1f}%</b>")
        if finite_num(live_ref_ret) and abs(live_ref_ret) > 0.003:
            live_emoji = "🔺" if live_ref_ret > 0 else "🔻"
            flow_parts.append(f"최신가-종가: {live_emoji} <b>{live_ref_ret*100:.1f}%</b>")
    elif day_ret != 0:
        dr_emoji = "🔺" if day_ret > 0 else "🔻"
        flow_parts.append(f"{day_ret_label}: {dr_emoji} <b>{day_ret*100:.1f}%</b>")
    if vol_ratio > 0:
        vol_desc = "거래량 급증" if vol_ratio >= 2 else ("보통" if vol_ratio >= 0.7 else "거래량 감소")
        flow_parts.append(f"거래량 20일비: <b>{vol_ratio:.1f}x</b> ({vol_desc})")
    if ma5 > 0 and ma20 > 0 and cur_p > 0:
        pos_vs_ma5 = (cur_p / ma5 - 1) * 100
        pos_vs_ma20 = (cur_p / ma20 - 1) * 100
        flow_parts.append(f"MA5 대비 {pos_vs_ma5:+.1f}% / MA20 대비 {pos_vs_ma20:+.1f}%")
    lines.append("💸 <b>수급·가격 흐름</b>: " + " | ".join(flow_parts))

    # ── 5. 진입 조건 (핵심: 뭐가 부족한지) ──────────────────
    entry_hint = ""
    if decision_code == "S_UPTREND_WAIT_PULLBACK":
        missing = []
        if rsi > 65:
            missing.append(f"RSI {rsi:.0f} → <b>65 이하</b>")
        if pct_b > 0.75:
            missing.append(f"%B {pct_b:.2f} → <b>0.75 이하</b>")
        if mfi >= 75:
            missing.append(f"MFI {mfi:.0f} → <b>75 미만</b>")
        if missing:
            entry_hint = (
                f"⏳ <b>진입 전환 조건</b>: {', '.join(missing)} 충족 시 "
                f"<b>'우량주 눌림 구간: 정찰 진입 적합'</b>으로 신호 전환됩니다. "
                f"급락 없이도 며칠 <b>횡보·숨 고르기</b>만으로 충족될 수 있습니다."
            )
    elif decision_code == "A_UPTREND_WAIT_PULLBACK":
        missing = []
        if rsi > 65: missing.append(f"RSI {rsi:.0f} → <b>65 이하</b>")
        if pct_b > 0.75: missing.append(f"%B {pct_b:.2f} → <b>0.75 이하</b>")
        if missing:
            entry_hint = f"⏳ <b>진입 전환 조건 (A급)</b>: {', '.join(missing)} 충족 필요."
    elif decision_code in ("QUALITY_PULLBACK_ENTRY", "TREND_PULLBACK_EXPLORE"):
        entry_hint = "✅ <b>현재 진입 구간</b>: 눌림 매수 적합 시점입니다."
    elif decision_code == "CORE_ETF_DCA_BUY":
        entry_hint = "✅ <b>코어 ETF 분할매수</b> 적합 구간입니다."
    elif decision_code in ("REVERSE_TREND_NO_ENTRY", "STRONG_REVERSE_NO_ENTRY"):
        entry_hint = "🚫 <b>진입 보류</b>: 역배열·하락 구조. 추세 전환 확인 전까지 신규 진입은 위험합니다."
    elif decision_code == "PROFIT_TAKE_SIGNAL":
        entry_hint = "💰 <b>익절 신호</b>: MFI·%B 과열 + 평단 대비 수익 20% 이상. 일부 익절 고려."
    elif decision_code == "HOLD_QUALITY_UPTREND":
        entry_hint = "🏆 <b>홀드 구간</b>: 정배열 유지 중이나 추매보다 홀드가 우선인 타이밍."
    elif decision_code in ("LEADER_MA5_PULLBACK_ENTRY", "LEADER_MA5_FAST_PULLBACK_ENTRY",
                           "OVERHEAT_EXTENSION_WAIT_MA5"):
        _ma5_str = format_currency(ma5, tkr) if ma5 > 0 else "MA5"
        _curr_w  = c.get("current_w", 0.0)
        _targ_w  = c.get("target_w",  0.0)
        if has_p and _targ_w > 0 and _curr_w < _targ_w * 0.97:
            # 기존 보유 + 비중 부족 → "MA5 눌림 시 추가" 안내
            entry_hint = (
                f"⏳ <b>추매 대기 — MA5 눌림 확인 후 추가</b>: "
                f"볼린저 상단권(%B {pct_b:.2f})이라 지금 바로 추매는 불리합니다. "
                f"{_ma5_str} 근처로 조정 시 현재 비중 부족분 "
                f"(<b>{_curr_w:.1f}% → 목표 {_targ_w:.1f}%</b>) 일부 분할 추가를 검토하세요. "
                f"별도 급락 없이 며칠 <b>횡보·숨 고르기</b>만으로도 %B가 내려올 수 있습니다."
            )
        elif has_p:
            # 기존 보유 + 비중 충족·초과 → 홀드
            entry_hint = (
                f"🏆 <b>홀드 — MA5 눌림까지 관망</b>: "
                f"볼린저 상단권(%B {pct_b:.2f}). "
                f"비중이 충족된 상태이므로 추매보다 홀드 유지가 우선입니다. "
                f"{_ma5_str} 눌림 후 재평가하세요."
            )
        else:
            # 미보유 → 신규 진입 대기
            entry_hint = (
                f"⏳ <b>진입 대기 — MA5 눌림 확인 후 정찰</b>: "
                f"볼린저 상단권(%B {pct_b:.2f}) 추격 진입은 위험합니다. "
                f"{_ma5_str} 근처로 조정 시 목표비중의 1/3 소량 정찰 진입을 검토하세요."
            )

    if entry_hint:
        lines.append(entry_hint)

    # ── 6. R/R ───────────────────────────────────────────────
    if rr_ratio and rr_ratio > 0 and rr_target and rr_stop:
        if rr_target_is_projection:
            lines.append(
                f"📐 <b>R/R 비율</b>: <b>{rr_ratio:.2f}</b> — "
                f"강세 시나리오 상단 {format_currency(rr_target, tkr)} / 손절 {format_currency(rr_stop, tkr)}"
            )
            lines.append(
                f"    → 위 가격은 확정 목표가가 아니라 {escape_html_value(rr_target_source)}입니다. "
                "신고가 구간은 1~2ATR 분할익절 후 잔여 추적손절이 우선입니다."
            )
        else:
            lines.append(
                f"📐 <b>R/R 비율</b>: <b>{rr_ratio:.2f}</b> — "
                f"목표가 {format_currency(rr_target, tkr)} / 손절 {format_currency(rr_stop, tkr)}"
            )

    # ── 7. 내 포지션 손익 ─────────────────────────────────────
    if has_p and my_p > 0 and cur_p > 0:
        pnl_pct = (cur_p / my_p - 1) * 100
        pnl_emoji = "📈" if pnl_pct >= 0 else "📉"
        lines.append(
            f"{pnl_emoji} <b>내 손익</b>: 평단 {format_currency(my_p, tkr)} 대비 현재가 {pnl_pct:+.1f}%"
        )

    border_color = "#10b981" if "진입" in dec or "매수" in dec or "홀드" in dec else (
        "#ef4444" if "보류" in dec or "역배열" in dec else "#6366f1"
    )
    html = (
        f"<div class='info-panel' style='border-left:5px solid {border_color}; line-height:2.0;'>"
        f"<b>📖 종합 해설</b><br><br>"
        + "<br>".join(f"• {line}" for line in lines)
        + "</div>"
    )
    return html


PEER_COMPARE_ALIAS_MAP = {
    "SANDISK": "SNDK",
    "SANDISKCORP": "SNDK",
    "SANDISK CORPORATION": "SNDK",
    "SAN DISK": "SNDK",
    "샌디스크": "SNDK",
}


def resolve_peer_compare_ticker(raw_value: str) -> str:
    raw = str(raw_value or "").strip()
    if not raw:
        return ""
    if raw in TICKER_MAP:
        return sanitize_ticker_value(TICKER_MAP[raw][0])
    compact = re.sub(r"\s+", " ", raw.upper()).strip()
    no_space = compact.replace(" ", "")
    if compact in PEER_COMPARE_ALIAS_MAP:
        return sanitize_ticker_value(PEER_COMPARE_ALIAS_MAP[compact])
    if no_space in PEER_COMPARE_ALIAS_MAP:
        return sanitize_ticker_value(PEER_COMPARE_ALIAS_MAP[no_space])
    return sanitize_ticker_value(raw)


def parse_peer_compare_tickers(raw_text: str, max_items: int = 6) -> list[str]:
    parts = re.split(r"[,;/\n]+", str(raw_text or ""))
    tickers: list[str] = []
    seen: set[str] = set()
    for part in parts:
        ticker = resolve_peer_compare_ticker(part)
        key = normalize_ticker(ticker)
        if not key or key in seen:
            continue
        seen.add(key)
        tickers.append(ticker)
        if len(tickers) >= max_items:
            break
    return tickers


def _is_recent_us_daymarket_epoch(ts, max_age_seconds: int = 16 * 60 * 60) -> bool:
    try:
        epoch = int(float(ts))
    except Exception:
        return False
    age = datetime.now(timezone.utc).timestamp() - epoch
    return -300 <= age <= max_age_seconds


def fetch_yahoo_daymarket_price_direct(ticker: str) -> float:
    t = normalize_ticker(ticker)
    if not t or is_kr_listed(t):
        return 0.0
    try:
        url = f"https://finance.yahoo.com/quote/{urllib.parse.quote(t)}/"
        headers = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
            ),
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
            "Referer": "https://finance.yahoo.com/",
        }
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=8) as resp:
            text = resp.read().decode("utf-8", errors="ignore")

        symbol = re.escape(t)
        match = re.search(
            rf'\\"symbol\\":\\"{symbol}\\".*?\\"overnightMarketPrice\\":\{{\\"raw\\":([0-9.]+).*?\\"overnightMarketTime\\":\{{\\"raw\\":([0-9]+)',
            text,
            flags=re.DOTALL,
        )
        if not match:
            match = re.search(
                rf'\\"overnightMarketPrice\\":\{{\\"raw\\":([0-9.]+).*?\\"symbol\\":\\"{symbol}\\".*?\\"overnightMarketTime\\":\{{\\"raw\\":([0-9]+)',
                text,
                flags=re.DOTALL,
            )
        if not match:
            return 0.0
        price = clean_float(match.group(1), 0.0)
        ts = int(match.group(2))
        return price if price > 0 and _is_recent_us_daymarket_epoch(ts) else 0.0
    except Exception:
        return 0.0


def load_display_live_price(ticker: str) -> float:
    direct = fetch_yahoo_daymarket_price_direct(ticker)
    if direct > 0:
        return direct
    return clean_float(load_latest_price(ticker), 0.0)


def _period_return_from_close(close: pd.Series, bars: int) -> float:
    if close is None or len(close) <= bars:
        return np.nan
    start = clean_float(close.iloc[-bars - 1], np.nan)
    end = clean_float(close.iloc[-1], np.nan)
    if not finite_num(start) or not finite_num(end) or start <= 0:
        return np.nan
    return (end / start) - 1


def _rank_pct_series(values: pd.Series, *, ascending: bool = True) -> pd.Series:
    numeric = pd.to_numeric(values, errors="coerce")
    if numeric.notna().sum() <= 1:
        return pd.Series(0.5, index=values.index)
    ranked = numeric.rank(pct=True, ascending=ascending)
    return ranked.fillna(0.5)


def build_peer_comparison_data(tickers: list[str], base_asset_class: str = "", period: str = "6mo") -> tuple[pd.DataFrame, pd.DataFrame]:
    rows = []
    curve_parts = {}
    normalized_tickers = [sanitize_ticker_value(ticker) for ticker in tickers if sanitize_ticker_value(ticker)]
    try:
        live_price_map = load_latest_prices_batch(normalized_tickers)
    except Exception:
        live_price_map = {}

    for ticker in normalized_tickers:
        t = sanitize_ticker_value(ticker)
        if not t:
            continue
        df = load_price_df(t, period)
        if df is None or df.empty or "Close" not in df.columns:
            rows.append({"티커": t, "상태": "가격 데이터 부족"})
            continue

        live_price = fetch_yahoo_daymarket_price_direct(t)
        if live_price <= 0:
            live_price = clean_float(live_price_map.get(normalize_price_lookup_key(t)), 0.0)
        if live_price > 0:
            df, _ = apply_live_price_to_ohlcv(df, live_price, t)

        close = pd.to_numeric(df["Close"], errors="coerce").dropna()
        if close.empty:
            rows.append({"티커": t, "상태": "가격 데이터 부족"})
            continue

        name = sanitize_asset_name("", t)
        is_etf = is_fin_score_exempt_asset(t, False, "", name)
        asset_class = infer_asset_class_for_ticker(t, base_asset_class) if is_etf else (
            "kr_stock" if is_kr_listed(t) else "us_stock"
        )
        market_score, market_rs = get_rs_score(t, asset_class)
        rs_slope_val, rs_slope_label, _ = get_rs_slope(t, asset_class)
        bench_info = get_auto_benchmark_info(t, name, asset_class, is_etf)

        ret_2w = _period_return_from_close(close, 10)
        ret_1m = _period_return_from_close(close, 21)
        ret_3m = _period_return_from_close(close, 63)
        ret_6m = _period_return_from_close(close, 126)
        ret_selected = _period_return_from_close(close, len(close) - 1)
        accel = ret_1m - (ret_3m / 3.0) if finite_num(ret_1m) and finite_num(ret_3m) else np.nan
        high_3m = clean_float(close.tail(63).max(), np.nan)
        last = clean_float(close.iloc[-1], np.nan)
        dd_3m = (last / high_3m) - 1 if finite_num(last) and finite_num(high_3m) and high_3m > 0 else np.nan
        vol_3m = close.pct_change().tail(63).std() * np.sqrt(252) if len(close) >= 20 else np.nan

        if len(close) >= 2:
            curve_parts[t] = ((close / close.iloc[0] - 1) * 100).rename(t)

        rows.append({
            "티커": t,
            "상태": "OK",
            "2주": ret_2w,
            "1개월": ret_1m,
            "3개월": ret_3m,
            "6개월": ret_6m,
            "선택기간": ret_selected,
            "가속도": accel,
            "고점대비": dd_3m,
            "변동성": vol_3m,
            "시장RS": market_rs,
            "시장RS점수": market_score,
            "섹터RS": bench_info.get("sector_rs_label", "-"),
            "섹터벤치": bench_info.get("sector_bench", ""),
            "RS방향": rs_slope_label,
            "RS방향값": rs_slope_val,
        })

    result = pd.DataFrame(rows)
    if result.empty:
        return result, pd.DataFrame()

    ok_mask = result.get("상태", "") == "OK"
    ok = result[ok_mask].copy()
    if not ok.empty:
        peer_median_3m = pd.to_numeric(ok["3개월"], errors="coerce").median()
        ok["동종3M우위"] = pd.to_numeric(ok["3개월"], errors="coerce") - peer_median_3m
        ok["최근탄력점수"] = (
            _rank_pct_series(ok["3개월"]) * 35
            + _rank_pct_series(ok["1개월"]) * 25
            + _rank_pct_series(ok["2주"]) * 15
            + _rank_pct_series(ok["가속도"]) * 15
            + _rank_pct_series(ok["고점대비"]) * 10
        ).round(1)
        ok["누적주도점수"] = (
            _rank_pct_series(ok["선택기간"]) * 30
            + _rank_pct_series(ok["6개월"]) * 20
            + _rank_pct_series(ok["3개월"]) * 25
            + _rank_pct_series(ok["1개월"]) * 15
            + _rank_pct_series(ok["2주"]) * 5
            + _rank_pct_series(ok["가속도"]) * 5
            + _rank_pct_series(ok["고점대비"]) * 10
        ).round(1)
        ok["동종점수"] = ok["누적주도점수"]
        ok = ok.sort_values(["동종점수", "6개월", "3개월"], ascending=[False, False, False])
        ok.insert(0, "순위", range(1, len(ok) + 1))
        ok["동종판정"] = ok.apply(
            lambda r: (
                "누적 리더"
                if int(r.get("순위", 0) or 0) == 1
                else (
                    "강한 추격"
                    if clean_float(r.get("동종점수"), 0.0) >= 75
                    else (
                        "최근 탄력"
                        if clean_float(r.get("최근탄력점수"), 0.0) >= 75
                        else (
                            "강함"
                            if clean_float(r.get("동종점수"), 0.0) >= 60
                            else ("보통" if clean_float(r.get("동종점수"), 0.0) >= 45 else "약함")
                        )
                    )
                )
            ),
            axis=1,
        )
        result = pd.concat([ok, result[~ok_mask]], ignore_index=True)

    curve_df = pd.concat(curve_parts.values(), axis=1).ffill().dropna(how="all") if curve_parts else pd.DataFrame()
    return result, curve_df


def _format_peer_pct(value) -> str:
    v = clean_float(value, np.nan)
    return "-" if not finite_num(v) else f"{v * 100:+.1f}%"


def render_peer_comparison_panel(current_ticker: str, current_name: str = "", asset_class: str = ""):
    key_base = normalize_ticker(current_ticker) or "peer"
    with st.expander("🔬 동종 후보 상대비교", expanded=False):
        st.caption(
            "시장/섹터 벤치 대비 모두 강한 후보끼리 직접 비교합니다. "
            "쉼표로 2~6개를 입력하세요. 예: CRDO, MRVL, Sandisk"
        )
        raw = st.text_input(
            "비교 종목",
            value=st.session_state.get(f"peer_compare_text_{key_base}", current_ticker),
            key=f"peer_compare_text_{key_base}",
            help="티커를 쉼표로 구분합니다. Sandisk는 SNDK로 자동 변환됩니다.",
        )
        period = st.radio(
            "차트 기간",
            ["3mo", "6mo", "1y"],
            index=1,
            key=f"peer_compare_period_{key_base}",
            horizontal=True,
        )
        tickers = parse_peer_compare_tickers(raw)
        if len(tickers) < 2:
            st.info("비교할 종목을 2개 이상 입력하면 상대강도 표와 리베이스 차트가 표시됩니다.")
            return

        result, curve_df = build_peer_comparison_data(tickers, asset_class, period)
        ok = result[result.get("상태", "") == "OK"].copy() if not result.empty else pd.DataFrame()
        if ok.empty:
            st.warning("비교 가능한 가격 데이터가 부족합니다.")
            return

        leader = ok.iloc[0]
        recent_leader = ok.sort_values(["최근탄력점수", "3개월", "1개월"], ascending=[False, False, False]).iloc[0]
        st.markdown(
            f"<div class='info-panel' style='border-left:4px solid #22c55e;'>"
            f"<b>누적 주도 리더</b>: <span class='highlight'>{escape_html_value(leader.get('티커', '-'))}</span> "
            f"({leader.get('동종판정', '-')}, 누적점수 {clean_float(leader.get('동종점수'), 0.0):.1f})<br>"
            f"선택기간 {_format_peer_pct(leader.get('선택기간'))} / 6개월 {_format_peer_pct(leader.get('6개월'))} / "
            f"3개월 {_format_peer_pct(leader.get('3개월'))} / "
            f"동종 3M 우위 {_format_peer_pct(leader.get('동종3M우위'))}<br>"
            f"<span style='color:#94a3b8;'>최근 탄력 리더: {escape_html_value(recent_leader.get('티커', '-'))} "
            f"(최근점수 {clean_float(recent_leader.get('최근탄력점수'), 0.0):.1f})</span>"
            f"</div>",
            unsafe_allow_html=True,
        )

        if not curve_df.empty:
            fig = go.Figure()
            for t in ok["티커"].tolist():
                if t in curve_df.columns:
                    fig.add_trace(go.Scatter(x=curve_df.index, y=curve_df[t], mode="lines", name=t))
            fig.update_layout(
                template="plotly_dark",
                height=320,
                margin=dict(l=10, r=10, t=35, b=10),
                title=f"비교 시작일 대비 누적수익률 ({period})",
                yaxis_title="수익률(%)",
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
            )
            fig.add_hline(y=0, line_color="#64748b", line_dash="dash")
            st.plotly_chart(fig, width="stretch")

        show = ok[[
            "순위", "티커", "동종판정", "동종점수", "최근탄력점수", "선택기간", "2주", "1개월", "3개월", "6개월",
            "동종3M우위", "시장RS", "섹터RS", "RS방향", "고점대비", "변동성"
        ]].copy()
        show = show.rename(columns={"동종점수": "누적주도점수"})
        for col in ["선택기간", "2주", "1개월", "3개월", "6개월", "동종3M우위", "고점대비", "변동성"]:
            show[col] = show[col].apply(_format_peer_pct)
        st.dataframe(show, width="stretch", hide_index=True)

        failed = result[result.get("상태", "") != "OK"] if not result.empty else pd.DataFrame()
        if not failed.empty:
            st.caption("데이터 부족: " + ", ".join(failed["티커"].astype(str).tolist()))


def render_entry_execution_plan(name, ticker, c, has_pos=False, usdkrw=1400.0):
    """Show a concrete entry/exit plan using the app's existing R/R logic."""
    cur = clean_float(c.get("cur_p"), 0.0)
    atr = clean_float(c.get("atr"), 0.0)
    stop = clean_float(c.get("rr_stop"), 0.0)
    target = clean_float(c.get("rr_target"), 0.0)
    rr = clean_float(c.get("rr_ratio"), 0.0)
    buy_amt_krw = clean_float(c.get("buy_amt"), 0.0)
    target_w = clean_float(c.get("target_w"), 0.0)
    current_w = clean_float(c.get("current_w"), 0.0)
    weight_gap = max(clean_float(c.get("weight_gap"), target_w - current_w), 0.0)
    effective_total_asset = clean_float(c.get("effective_total_asset"), 0.0)
    if buy_amt_krw <= 0 and effective_total_asset > 0 and weight_gap > 0:
        buy_amt_krw = round(effective_total_asset * weight_gap / 100.0, 0)
    if buy_amt_krw <= 0 and str(c.get("app_mode", "")) != "범용모드":
        try:
            sheet_target_w = clean_float(get_target_weight_from_sheet(name, ticker), 0.0)
            sheet_current_w = clean_float(get_sheet_current_weight(name, ticker), 0.0)
            sheet_gap = max(sheet_target_w - sheet_current_w, 0.0)
            sheet_total = clean_float(globals().get("total_eval", 0.0), 0.0)
            if sheet_total > 0 and sheet_gap > 0:
                target_w = sheet_target_w
                current_w = sheet_current_w
                weight_gap = sheet_gap
                effective_total_asset = sheet_total
                buy_amt_krw = round(sheet_total * sheet_gap / 100.0, 0)
        except Exception:
            pass
    ma5 = clean_float(c.get("ma5"), 0.0)
    ma20 = clean_float(c.get("ma20"), 0.0)
    fvg_top = clean_float(c.get("fvg_top"), 0.0)
    fvg_bottom = clean_float(c.get("fvg_bottom"), 0.0)
    pct_b = clean_float(c.get("pct_b"), 0.0)
    decision_code = str(c.get("decision_code", "") or "")
    decision_label = str(c.get("dec", "") or "")
    pd_zone = str(c.get("pd_zone", "") or "")
    target_source = str(c.get("rr_target_source", "") or "차트 구조 목표가")
    stop_source = str(c.get("rr_stop_source", "") or "2ATR 손절")
    target_is_projection = bool(c.get("rr_target_is_projection", False))
    rr_tp1 = clean_float(c.get("rr_tp1"), 0.0)
    rr_tp2 = clean_float(c.get("rr_tp2"), 0.0)
    rr_tp3 = clean_float(c.get("rr_tp3"), 0.0)
    bucket = str(c.get("bucket", "") or "").lower()
    core_dca_rate = clean_float(c.get("core_dca_rate"), 0.0)
    core_dca_amt = clean_float(c.get("core_dca_amt"), 0.0)
    core_dca_label = str(c.get("core_dca_label", "") or "")
    history_days = clean_float(c.get("history_days"), np.nan)
    is_core_dca = bucket == "core" and core_dca_rate > 0 and target_w > 0 and weight_gap > 0
    is_new_core_etf = is_core_dca and (bool(c.get("short_history")) or (np.isfinite(history_days) and history_days < 80))
    new_core_verification = build_new_core_etf_verification(name, ticker, str(c.get("asset_class", "") or ""), c) if is_new_core_etf else {}

    if cur <= 0 or stop <= 0 or target <= 0 or stop >= cur:
        st.info("신규진입 실행 계획은 현재가, ATR 손절가, 목표가가 모두 계산될 때 표시됩니다.")
        return

    risk = cur - stop
    if risk <= 0:
        st.info("손절 폭을 산출할 수 없어 신규진입 실행 계획을 만들 수 없습니다.")
        return
    rr = round((target - cur) / risk, 2) if target > cur else rr

    block_codes = {
        "REVERSE_TREND_NO_ENTRY", "STRONG_REVERSE_NO_ENTRY", "DOWNTREND_NO_ENTRY",
        "SHORT_OVERHEAT_NO_ENTRY", "NEAR_UPPER_WAIT", "COST_MINUS_15_TREND_RISK",
        "STRUCTURE_DAMAGE_HOLDING_CHECK", "MTF_DAMAGE_NO_ADD",
        "TARGET_ZERO_NO_ADD", "LEVERAGED_DAILY_DROP_NO_ADD",
    }
    wait_codes = {
        "S_UPTREND_WAIT_PULLBACK", "A_UPTREND_SEARCH_ENTRY", "UPTREND_PULLBACK_CONFIRM",
        "OVERHEAT_EXTENSION_WAIT_MA5", "LEADER_MA5_PULLBACK_ENTRY",
        "LEADER_MA5_FAST_PULLBACK_ENTRY", "S_GRADE_OVERHEAT_WAIT",
        "PREMARKET_REBOUND_WAIT", "PREMARKET_REBOUND_HOLDING_WAIT",
        "MTF_OVERHEAT_SCOUT_ONLY",
    }
    is_wait = decision_code in wait_codes or (pct_b >= 0.78 and "Premium" in pd_zone)
    is_hard_blocked = decision_code in block_codes
    is_poor_rr = rr < 1.0

    if is_hard_blocked:
        status = "진입 보류"
        status_color = "#ef4444"
        if decision_code == "TARGET_ZERO_NO_ADD":
            status_note = "목표비중이 0%라 추가매수 계획을 만들지 않습니다. 보유분은 축소/정리 또는 별도 목표비중 재설정 후 판단합니다."
        elif decision_code == "LEVERAGED_DAILY_DROP_NO_ADD":
            status_note = "레버리지 상품의 큰 일간 급락입니다. 가격이 내려왔다는 이유로 추매하지 않고 종가, 기초지수, 다음 봉 회복을 먼저 확인합니다."
        else:
            status_note = "추세 조건이 부족합니다. 진입가가 내려오거나 구조가 회복될 때까지 대기합니다."
    elif is_poor_rr:
        status = "현재가 보류 / 눌림 대기"
        status_color = "#d97706"
        status_note = "현재가 기준 R/R이 1 미만입니다. 아래 금액/수량은 목표비중 기준의 대기 계획이며, 조건 확인 후만 사용하세요."
    elif is_new_core_etf:
        initial_cap_w = target_w * 0.33
        verification_code = str(new_core_verification.get("verdict_code", "wait"))
        verification_verdict = str(new_core_verification.get("verdict", "2차 검증 대기"))
        if has_pos and current_w >= initial_cap_w * 0.90 and verification_code in ("pass", "caution", "conditional"):
            status = verification_verdict
        else:
            status = "1차 정찰 완료 / 2차 검증 대기" if has_pos and current_w >= initial_cap_w * 0.90 else "신규 코어 ETF 1차 정찰"
        status_color = "#3b82f6"
        if has_pos and current_w >= initial_cap_w * 0.90 and verification_code in ("pass", "caution", "conditional"):
            status_note = (
                f"{new_core_verification.get('detail', '')} "
                "2차는 하락만 기다리는 규칙이 아니라 검증 통과 후 이번 회차 적립률 안에서 열 수 있고, "
                "120거래일은 풀코어 전환 기준입니다."
            )
        else:
            status_note = (
                "신규상장 코어 ETF는 총 부족분을 바로 채우지 않습니다. "
                "2차는 하락만 기다리는 규칙이 아니라 60거래일 이후 거래대금·괴리율·기초흐름 검증 또는 MA20/FVG 눌림 확인 때 열고, "
                "3차는 120거래일 이상 자료가 쌓인 뒤 정상 코어로 전환할 때 검토합니다."
            )
    elif target_is_projection:
        status = "신고가 추적 / 분할만"
        status_color = "#d97706"
        status_note = "+4ATR은 확정 목표가가 아니라 가격발견 구간의 강세 상단입니다. 신규/추매는 추격보다 눌림 또는 소액 분할, 익절은 +1ATR/+2ATR와 추적손절 중심으로 봅니다."
    elif rr < 1.5:
        status = "정찰만"
        status_color = "#d97706"
        status_note = "R/R이 1.5 미만이라 풀비중보다 1차 정찰 중심이 맞습니다."
    elif decision_code == "MTF_OVERHEAT_SCOUT_ONLY":
        status = "상위과열 / 1차 정찰만"
        status_color = "#d97706"
        status_note = "일봉은 눌림이지만 주봉/월봉 가격대가 높습니다. 부족분 전체가 아니라 1차 정찰 후 추가 확인이 맞습니다."
    elif is_wait:
        status = "정규장 확인대기" if decision_code.startswith("PREMARKET_REBOUND") else "눌림 대기"
        status_color = "#8b5cf6"
        status_note = (
            "프리/애프터 반등은 참고만 하고 정규장 초반 거래량, MA5/FVG 지지를 확인합니다."
            if decision_code.startswith("PREMARKET_REBOUND")
            else "추격보다 MA5/MA20/FVG 눌림 확인 후 분할 진입합니다."
        )
    else:
        status = "분할 진입 가능"
        status_color = "#10b981"
        status_note = "현재 앱 신호 기준으로 1차 정찰 후 눌림에서 추가하는 구간입니다."

    support_candidates = []
    for label, value in [
        ("MA5", ma5),
        ("MA20", ma20),
        ("FVG 상단", fvg_top),
        ("FVG 하단", fvg_bottom),
        ("0.5ATR 눌림", cur - atr * 0.5 if atr > 0 else 0.0),
        ("1ATR 눌림", cur - atr if atr > 0 else 0.0),
    ]:
        if finite_num(value) and stop < value < cur:
            support_candidates.append((label, float(value)))
    support_candidates = sorted(support_candidates, key=lambda item: item[1], reverse=True)
    unique_candidates = []
    min_gap = max(cur * 0.003, 1.0)
    for label, value in support_candidates:
        if all(abs(value - used_value) > min_gap for _, used_value in unique_candidates):
            unique_candidates.append((label, value))
    support_candidates = unique_candidates

    if is_wait and support_candidates:
        entry1_label, entry1 = support_candidates[0]
        entry1_cond = f"{entry1_label} 눌림 확인 후 1차"
    else:
        entry1 = cur
        entry1_cond = "현재가 부근 1차 정찰"

    if len(support_candidates) >= 2:
        entry2_label, entry2 = support_candidates[1]
    elif support_candidates:
        entry2_label, entry2 = support_candidates[0]
    else:
        entry2_label, entry2 = "0.5ATR 눌림", max(stop + risk * 0.45, cur - risk * 0.25)

    if len(support_candidates) >= 3:
        entry3_label, entry3 = support_candidates[2]
    else:
        entry3_label = "손절 전 마지막 방어선"
        entry3 = stop + risk * 0.25
        if abs(entry3 - entry2) <= min_gap:
            entry3 = max(stop + risk * 0.15, entry2 - risk * 0.25)

    if target_is_projection and atr > 0:
        tp1 = rr_tp1 if rr_tp1 > cur else cur + atr
        tp2 = rr_tp2 if rr_tp2 > cur else cur + atr * 2.0
        tp3 = rr_tp3 if rr_tp3 > cur else target
    else:
        tp1 = min(target, cur + risk)
        tp2 = target
        tp3 = target

    if is_hard_blocked:
        tranche_weights = [0.0, 0.0, 0.0]
    elif is_new_core_etf and has_pos and current_w >= (target_w * 0.33 * 0.90):
        tranche_weights = [0.0, 0.45, 0.55]
    elif is_new_core_etf:
        tranche_weights = [0.35, 0.35, 0.30]
    elif is_wait:
        tranche_weights = [0.30, 0.40, 0.30]
    elif rr < 1.5:
        tranche_weights = [0.30, 0.0, 0.0]
    else:
        tranche_weights = [0.40, 0.35, 0.25]

    def order_text(amount_krw, price):
        if amount_krw <= 0 or price <= 0:
            return "-"
        is_us = not is_kr_listed(ticker)
        if is_us:
            fx = clean_float(usdkrw, 1400.0) or 1400.0
            amount_usd = amount_krw / fx
            shares = amount_usd / price if price > 0 else 0.0
            return f"${amount_usd:,.0f} / {shares:.2f}주"
        shares = amount_krw / price if price > 0 else 0.0
        return f"{amount_krw:,.0f}원 / {shares:.2f}주"

    def rr_text(entry_price):
        entry = clean_float(entry_price, 0.0)
        if entry <= 0 or stop <= 0 or target <= entry or stop >= entry:
            return "-"
        return f"{(target - entry) / (entry - stop):.2f}"

    def tranche_label(label, weight):
        pct = clean_float(weight, 0.0) * 100
        return f"{label} ({pct:.0f}%)" if pct > 0 else label

    plan_buy_amt_krw = buy_amt_krw
    if is_core_dca and core_dca_amt > 0:
        plan_buy_amt_krw = min(core_dca_amt, buy_amt_krw) if buy_amt_krw > 0 else core_dca_amt

    rr_now_text = rr_text(cur)
    rr_entry1_text = rr_text(entry1)
    rr_entry2_text = rr_text(entry2)
    rr_entry3_text = rr_text(entry3)
    rr_entry2_display = rr_entry2_text
    rr_entry3_display = rr_entry3_text
    total_order_text = order_text(buy_amt_krw, cur)
    plan_order_text = order_text(plan_buy_amt_krw, cur)
    if weight_gap > 0:
        total_condition = f"목표 {target_w:.2f}% - 현재 {current_w:.2f}% = 부족 {weight_gap:.2f}%p"
    else:
        total_condition = "목표비중 기준 추가 필요 없음"

    if is_new_core_etf:
        initial_cap_w = target_w * 0.33
        entry1_cond = f"초기 정찰 한도 {initial_cap_w:.2f}% 확인 · 현재 {current_w:.2f}%"
        entry2_cond = "60거래일+거래대금/NAV 괴리율+동종·기초흐름 우호 확인. 현재가 추격보다 종가 유지 또는 MA20/FVG 눌림 우선"
        entry3_cond = "120거래일 이상 자료 확보 후 MA50/MA120, 장기 MDD, 기초지수 흐름으로 정상 코어 전환 확인"
        entry2_price_text = f"{format_currency(cur, ticker)} 또는 {format_currency(entry2, ticker)}"
        entry3_price_text = "120거래일 검증 후"
        rr_entry2_display = f"{rr_now_text}/{rr_entry2_text}"
        rr_entry3_display = "검증 후 재산출"
    else:
        entry2_cond = f"{entry2_label} 근처에서 반등 확인"
        entry3_cond = f"{entry3_label} 근처, 손절가 이탈 전까지만"
        entry2_price_text = format_currency(entry2, ticker)
        entry3_price_text = format_currency(entry3, ticker)

    rows = [
        {
            "단계": "총 추가 필요",
            "가격": format_currency(cur, ticker),
            "금액/수량": total_order_text,
            "예상 R/R": rr_now_text,
            "조건": total_condition,
        },
    ]
    if is_core_dca:
        rows.append({
            "단계": "이번 회차 적립 기준",
            "가격": format_currency(cur, ticker),
            "금액/수량": plan_order_text,
            "예상 R/R": rr_now_text,
            "조건": f"{core_dca_label or f'적립률 {core_dca_rate * 100:.0f}%'} 적용. 전체 부족분을 한 번에 채우지 않고 이번 회차만 나눕니다.",
        })
    rows += [
        {
            "단계": tranche_label("1차 진입", tranche_weights[0]),
            "가격": format_currency(entry1, ticker),
            "금액/수량": order_text(plan_buy_amt_krw * tranche_weights[0], entry1),
            "예상 R/R": rr_entry1_text,
            "조건": entry1_cond,
        },
        {
            "단계": tranche_label("2차 추가", tranche_weights[1]),
            "가격": entry2_price_text,
            "금액/수량": order_text(plan_buy_amt_krw * tranche_weights[1], entry2),
            "예상 R/R": rr_entry2_display,
            "조건": entry2_cond,
        },
        {
            "단계": tranche_label("3차 예비", tranche_weights[2]),
            "가격": entry3_price_text,
            "금액/수량": order_text(plan_buy_amt_krw * tranche_weights[2], entry3),
            "예상 R/R": rr_entry3_display,
            "조건": entry3_cond,
        },
    ]
    if target_is_projection:
        rows += [
            {
                "단계": "1차 익절(+1ATR)",
                "가격": format_currency(tp1, ticker),
                "금액/수량": "보유분 20~30%",
                "예상 R/R": "-",
                "조건": "신고가 가격발견 구간의 첫 변동성 목표. 체결 후 잔여 손절을 본전~MA5 근처로 상향",
            },
            {
                "단계": "2차 익절(+2ATR)",
                "가격": format_currency(tp2, ticker),
                "금액/수량": "보유분 30~40%",
                "예상 R/R": "-",
                "조건": "기본 변동성 목표. RSI/MFI/%B 과열이 동반되면 추가 회수",
            },
            {
                "단계": "강세 상단(+4ATR)",
                "가격": format_currency(tp3, ticker),
                "금액/수량": "잔여 일부만",
                "예상 R/R": "-",
                "조건": "확정 목표가가 아니라 공격 시나리오 상단. 전량 지정가보다 일부만 열어두기",
            },
            {
                "단계": "잔여 추적손절",
                "가격": "MA5/전일저가/1ATR 이탈",
                "금액/수량": "잔여분",
                "예상 R/R": "-",
                "조건": "상단 목표를 맞히기보다 추세가 꺾일 때 정리. 종가 기준 이탈 우선",
            },
        ]
    else:
        rows += [
            {
                "단계": "1차 익절",
                "가격": format_currency(tp1, ticker),
                "금액/수량": "보유분 30~50%",
                "예상 R/R": "-",
                "조건": "1R 도달 시 일부 회수, 잔여 손절은 본전 근처로 상향",
            },
            {
                "단계": "최종 익절",
                "가격": format_currency(tp2, ticker),
                "금액/수량": "잔여분",
                "예상 R/R": "-",
                "조건": "구조 목표가 도달 또는 MFI/%B 과열 동반 시",
            },
        ]
    rows.append({
        "단계": "손절",
        "가격": format_currency(stop, ticker),
        "금액/수량": "전량 또는 계획분",
        "예상 R/R": "-",
        "조건": "종가 기준 이탈 시 신규진입 시나리오 무효",
    })

    if buy_amt_krw <= 0 and not has_pos:
        amount_note = "목표비중 또는 총자산을 입력하면 단계별 금액/주수가 자동 계산됩니다."
    elif is_core_dca:
        amount_note = (
            f"총 추가 필요: {total_order_text}. 이번 회차 적립 기준: {plan_order_text}. "
            "아래 단계별 금액은 전체 부족분이 아니라 이번 회차 적립 기준금액을 나눈 값입니다."
        )
    elif has_pos:
        amount_note = f"총 추가 필요: {total_order_text}. 이미 보유 중이면 잔여 목표비중 기준 추가 계획으로 해석하세요."
    else:
        amount_note = f"총 추가 필요: {total_order_text}. 아래 1~3차 행은 이 금액을 신호/RR에 맞춰 나눈 실행 계획입니다."
    if buy_amt_krw > 0 and rr < 1.5 and not is_hard_blocked:
        amount_note += " R/R이 낮아 현재 실행분은 1차 정찰만 열어둡니다."
    if target_is_projection:
        amount_note += " 신고가/가격발견 구간이라 +4ATR은 확정 목표가가 아니라 강세 시나리오 상단이며, 실제 익절은 +1ATR/+2ATR 분할과 추적손절 중심으로 해석하세요."

    target_label = "강세 시나리오 상단" if target_is_projection else "목표가"
    rr_label = "투영 상단 기준 R/R" if target_is_projection else "현재가 기준 R/R"
    st.markdown(
        f"<div class='info-panel' style='border-left:5px solid {status_color}; line-height:1.8;'>"
        f"<b>🎯 신규진입 실행 계획</b><br>"
        f"<span class='highlight'>{status}</span> — {escape_html_value(status_note)}<br>"
        f"{target_label} {format_currency(target, ticker)} <span style='color:#94a3b8;'>({escape_html_value(target_source)})</span> / "
        f"손절 {format_currency(stop, ticker)} <span style='color:#94a3b8;'>({escape_html_value(stop_source)})</span><br>"
        f"기준가 {format_currency(cur, ticker)} / {rr_label} {rr_now_text} / "
        f"1차 {rr_entry1_text} · 2차 {rr_entry2_text} · 3차 {rr_entry3_text}<br>"
        f"{escape_html_value(amount_note)}<br>"
        f"<span style='color:#94a3b8;'>투자 권유가 아니라, 현재 앱 지표를 주문 전 체크리스트로 풀어쓴 값입니다.</span>"
        f"</div>",
        unsafe_allow_html=True,
    )
    st.dataframe(pd.DataFrame(rows), width='stretch', hide_index=True)


def render_personal_stock_analysis_panel(name, ticker, is_etf, asset_class, c, fin_score, fin_meta, has_pos, my_price):
    st.markdown("### 🧭 개인 주식분석")
    st.caption("스윙 신호를 장기 보유 후보로 바꿔도 되는지 점검하는 보조 패널입니다. 투자 권유가 아니라 의사결정 체크리스트입니다.")

    cur_p = clean_float(c.get("cur_p"), 0.0)
    my_price = clean_float(my_price, 0.0)
    price_vs_avg = (cur_p / my_price - 1) if has_pos and my_price > 0 else np.nan
    structure_risk = bool(c.get("structure_risk"))
    dd = clean_float(c.get("dd"), 0.0)
    ret_3m = clean_float(c.get("ret_3m"), 0.0)
    ret_6m = clean_float(c.get("ret_6m"), 0.0)
    trend = str(c.get("trend", ""))
    rs_label = str(c.get("rs_label", ""))
    decision = str(c.get("dec", ""))

    if is_etf:
        suitability_score = 0
        suitability_score += 1 if "🚀" in rs_label or "➖" in rs_label else 0
        suitability_score += 1 if "역배열" not in trend else 0
        suitability_score += 1 if dd > -0.2 else 0
        suitability_score += 1 if ret_3m >= -0.03 else 0
        suitability_score += 1 if not structure_risk else 0
    else:
        suitability_score = 0
        suitability_score += 2 if int(fin_score) >= 4 else (1 if int(fin_score) >= 3 else 0)
        suitability_score += 1 if "역배열" not in trend else 0
        suitability_score += 1 if "🚀" in rs_label or "➖" in rs_label else 0
        suitability_score += 1 if not structure_risk else 0
        suitability_score += 1 if dd > -0.2 else 0

    suitability_score = min(int(suitability_score), 5)
    if suitability_score >= 4:
        long_label, long_color = "장기 후보", "#16a34a"
    elif suitability_score >= 3:
        long_label, long_color = "조건부 장기 후보", "#d97706"
    else:
        long_label, long_color = "스윙/관망 우선", "#64748b"

    if not has_pos:
        position_label = "미보유"
        position_note = "신규 매수는 구조훼손/과열 해소 후 검토"
    elif structure_risk or dd <= -0.2:
        position_label = "보유 점검"
        position_note = "추매 금지, 손절/장투 기준 재확인"
    elif clean_float(c.get("current_w"), 0.0) >= clean_float(c.get("target_w"), 0.0) > 0:
        position_label = "비중 충족"
        position_note = "추가매수보다 보유/리스크 관리 우선"
    else:
        position_label = "보유 가능"
        position_note = "시스템 신호와 목표비중 안에서만 분할 접근"

    m1, m2, m3, m4 = st.columns(4)
    m1.metric("장기 적합도", f"{suitability_score}/5", long_label)
    m2.metric("내 손익률", "-" if not finite_num(price_vs_avg) else f"{price_vs_avg * 100:.1f}%")
    m3.metric("52주 고점대비", f"{dd * 100:.1f}%")
    m4.metric("포지션 판단", position_label)

    rows = [
        {
            "점검항목": "핵심 결론",
            "상태": long_label,
            "해석": f"{escape_html_value(name)}({escape_html_value(ticker)})는 현재 {long_label}입니다. {position_note}",
        },
        {
            "점검항목": "재무/기초체력",
            "상태": "ETF 해당없음" if is_etf else f"{fin_score}/4",
            "해석": "ETF는 재무점수보다 기초지수/돈흐름 중심으로 봅니다." if is_etf else ("장기 보유 후보로 볼 수 있는 점수입니다." if int(fin_score) >= 3 else "장기 보유 전 재무 훼손 여부를 먼저 확인해야 합니다."),
        },
        {
            "점검항목": "추세/상대강도",
            "상태": f"{trend} / {rs_label}",
            "해석": f"3개월 {ret_3m * 100:.1f}%, 6개월 {ret_6m * 100:.1f}%입니다.",
        },
        {
            "점검항목": "구조위험",
            "상태": "주의" if structure_risk else "정상",
            "해석": "구조훼손 구간에서는 신규/추매보다 원인 점검이 우선입니다." if structure_risk else "기술 구조상 즉시 하드 경고는 없습니다.",
        },
        {
            "점검항목": "현재 시스템 신호",
            "상태": decision,
            "해석": "앱 판정 문구입니다. 장기 전환은 이 신호와 재무/뉴스/비중을 함께 봅니다.",
        },
    ]
    st.dataframe(pd.DataFrame(rows), width='stretch', hide_index=True)

    with st.expander("장기 전환 체크리스트", expanded=False):
        checklist_rows = [
            {"구분": "장기 전환 가능", "조건": "재무 3점 이상, 추세 훼손 제한적, 투자 아이디어가 실적/수요로 설명 가능"},
            {"구분": "추매 금지", "조건": "고점대비 -20% 이하, MA50 이탈, RS 약화, 급락+거래량 증가"},
            {"구분": "손절/축소 점검", "조건": "처음 산 이유가 사라짐, 실적/가이던스 훼손, 손실 한도 초과"},
            {"구분": "다시 매수 검토", "조건": "MA20/MA50 회복, RS 회복, 과열 해소 후 거래량 동반 반등"},
        ]
        st.dataframe(pd.DataFrame(checklist_rows), width='stretch', hide_index=True)

    # ==========================================
    # [신규 추가] UI 렌더링: 신규 분석 기능 표출
    # ==========================================
    st.markdown("### 🔍 추가 인사이트 (독립 모듈)")
    
    # 1. 안전하게 주가 데이터 로드 (캐시되어 있어 매우 빠름)
    local_df = load_price_df(ticker, "1y")

    # 2. 3단 컬럼으로 정보 표시
    col_ins1, col_ins2, col_ins3, col_ins4 = st.columns(4)
    
    with col_ins1:
        if not local_df.empty:
            breakout_data = detect_52w_breakout(local_df)
            st.info(f"**수급/추세:**\n{breakout_data['label']}")
        else:
            st.info("**수급/추세:**\n데이터 없음")

    with col_ins2:
        earnings_data = fetch_earnings_date(ticker)
        if earnings_data.get("high_risk"):
            st.warning(f"**이벤트 리스크:**\n{earnings_data['label']}")
        else:
            st.success(f"**이벤트 리스크:**\n{earnings_data['label']}")

    with col_ins3:
        if not local_df.empty:
            current_price = clean_float(c.get("cur_p"), 0.0) or float(local_df['Close'].iloc[-1])
            atr_val = clean_float(c.get("atr"), 0.0) or calc_atr(local_df)
            stop_price = clean_float(c.get("rr_stop"), 0.0)
            # 기존 c 딕셔너리에서 값 안전하게 빼오기
            target_w = clean_float(c.get("target_w"), 0.0)
            curr_w = clean_float(c.get("current_w"), 0.0)

            # 총자산은 임시로 1억 세팅 (이후 필요시 portfolio_summary와 연동)
            size_data = calc_position_size(100000000, target_w, curr_w, current_price, atr_val)
            if stop_price <= 0:
                stop_price = clean_float(size_data.get("stop_price"), 0.0)
            st.info(f"**손절 가이드 (2 ATR):**\n권장 손절가: {stop_price:,.0f}\n정밀관측소 R/R과 동일 기준")
        else:
            st.info("**진입/손절 가이드:**\n데이터 없음")

    with col_ins4:
        if not local_df.empty:
            smc_data = detect_smc_features(local_df)
            st.info(f"**스마트머니(SMC):**\n{smc_data['fvg_label']}\n{smc_data['ob_label']}")
        else:
            st.info("**스마트머니(SMC):**\n데이터 없음")

    # ── 한국 종목 전용: 외국인/기관 수급 + 재무 트렌드 + 공시 ────────────────────
    if is_kr_listed(ticker):
        with st.expander("📊 투자자별 수급 현황 (최근 20거래일)", expanded=False):
            render_investor_trend_panel(ticker, name)
        if not is_etf:
            with st.expander("📈 재무 트렌드 (연간 DART)", expanded=False):
                render_financial_trend_chart(ticker, name)
        _render_dart_disclosure_single(ticker, name)

    render_hold_decision_panel(name, ticker, is_etf, c, fin_score, has_pos, my_price)

VALUATION_INFO_KEYS = [
    "currentPrice",
    "regularMarketPrice",
    "targetMeanPrice",
    "targetMedianPrice",
    "numberOfAnalystOpinions",
    "trailingPE",
    "forwardPE",
    "priceToBook",
    "priceToSalesTrailing12Months",
    "enterpriseToRevenue",
    "enterpriseToEbitda",
    "pegRatio",
    "revenueGrowth",
    "earningsGrowth",
    "profitMargins",
    "operatingMargins",
    "grossMargins",
    "returnOnEquity",
    "debtToEquity",
    "recommendationKey",
    "recommendationMean",
    "trailingEps",
    "bookValue",
]


@st.cache_data(ttl=21600, show_spinner=False)
def fetch_valuation_snapshot(ticker):
    ticker = sanitize_ticker_value(ticker)
    if not ticker:
        return {"ok": False, "reason": "티커 없음", "data": {}}
    try:
        info = yf.Ticker(ticker).get_info()
    except Exception as _e:
        return {"ok": False, "reason": f"yfinance 오류: {_e}", "data": {}}
    if not isinstance(info, dict):
        info = {}

    data = {key: info.get(key) for key in VALUATION_INFO_KEYS}
    has_any = any(data.get(k) not in [None, ""] for k in VALUATION_INFO_KEYS)

    # ── 한국 종목: yfinance에 데이터가 없으면 네이버 증권으로 보완 ──────────────
    if is_kr_listed(ticker):
        naver = fetch_naver_kr_snapshot(ticker)
        if naver.get("ok"):
            nd = naver.get("data", {})
            for key in VALUATION_INFO_KEYS:
                if data.get(key) in [None, ""] and nd.get(key) not in [None, ""]:
                    data[key] = nd[key]
            has_any = any(data.get(k) not in [None, ""] for k in VALUATION_INFO_KEYS)

    if not has_any:
        reason = "yfinance/네이버 밸류 데이터 없음" if is_kr_listed(ticker) else "yfinance 밸류 데이터 없음"
        return {"ok": False, "reason": reason, "data": data}
    return {"ok": True, "reason": "", "data": data}


def fmt_multiple(value, digits=1):
    number = clean_float(value, np.nan)
    if not finite_num(number) or number <= 0:
        return "-"
    return f"{number:.{digits}f}x"


def fmt_growth_pct(value):
    number = clean_float(value, np.nan)
    if not finite_num(number):
        return "-"
    if abs(number) <= 3:
        number = number * 100
    return f"{number:.1f}%"


def valuation_factor_label(kind, value):
    number = clean_float(value, np.nan)
    if not finite_num(number):
        return "데이터 없음", 0

    if kind == "target_upside":
        if number >= 20:
            return "매력", 2
        if number >= 8:
            return "양호", 1
        if number >= -5:
            return "중립", 0
        return "부담", -1

    if kind == "pe":
        if number <= 20:
            return "낮음", 2
        if number <= 35:
            return "적정", 1
        if number <= 55:
            return "성장프리미엄", 0
        return "높음", -1

    if kind == "pbr":
        if number <= 1.0:
            return "자산가치 이하", 2
        if number <= 2.0:
            return "적정", 1
        if number <= 4.0:
            return "프리미엄", 0
        return "고평가", -1

    if kind == "ps":
        if number <= 3:
            return "낮음", 2
        if number <= 8:
            return "적정", 1
        if number <= 15:
            return "높음", 0
        return "매우 높음", -1

    if kind == "peg":
        if number <= 0:
            return "해석주의", 0
        if number <= 1.2:
            return "매력", 2
        if number <= 2.0:
            return "양호", 1
        if number <= 3.0:
            return "중립", 0
        return "부담", -1

    if kind == "growth":
        if abs(number) <= 3:
            number = number * 100
        if number >= 25:
            return "고성장", 2
        if number >= 10:
            return "성장", 1
        if number >= 0:
            return "둔화", 0
        return "역성장", -1

    if kind == "margin":
        if abs(number) <= 3:
            number = number * 100
        if number >= 25:
            return "우수", 2
        if number >= 10:
            return "양호", 1
        if number >= 0:
            return "낮음", 0
        return "적자", -1

    return "중립", 0


def build_valuation_interpretation(data, current_price, ticker):
    cur = clean_float(current_price, np.nan)
    target_mean = clean_float(data.get("targetMeanPrice"), np.nan)
    target_upside = np.nan
    if finite_num(target_mean) and finite_num(cur) and cur > 0:
        target_upside = (target_mean / cur - 1) * 100

    forward_pe = clean_float(data.get("forwardPE"), np.nan)
    trailing_pe = clean_float(data.get("trailingPE"), np.nan)
    pe_for_score = forward_pe if finite_num(forward_pe) else trailing_pe
    pbr = clean_float(data.get("priceToBook"), np.nan)
    ps = clean_float(data.get("priceToSalesTrailing12Months"), np.nan)
    peg = clean_float(data.get("pegRatio"), np.nan)
    revenue_growth = clean_float(data.get("revenueGrowth"), np.nan)
    earnings_growth = clean_float(data.get("earningsGrowth"), np.nan)
    profit_margin = clean_float(data.get("profitMargins"), np.nan)
    operating_margin = clean_float(data.get("operatingMargins"), np.nan)

    factors = [
        ("목표가 업사이드", "target_upside", target_upside, format_backtest_percent(target_upside)),
        ("PER", "pe", pe_for_score, fmt_multiple(pe_for_score)),
        ("PBR", "pbr", pbr, fmt_multiple(pbr)),
        ("PSR", "ps", ps, fmt_multiple(ps)),
        ("PEG", "peg", peg, fmt_multiple(peg)),
        ("매출 성장", "growth", revenue_growth, fmt_growth_pct(revenue_growth)),
        ("이익 성장", "growth", earnings_growth, fmt_growth_pct(earnings_growth)),
        ("순이익률", "margin", profit_margin, fmt_growth_pct(profit_margin)),
        ("영업이익률", "margin", operating_margin, fmt_growth_pct(operating_margin)),
    ]

    rows = []
    valuation_score = 0
    quality_score = 0
    data_count = 0
    for title, kind, value, display_value in factors:
        label, score = valuation_factor_label(kind, value)
        if finite_num(value):
            data_count += 1
            if kind in ["target_upside", "pe", "pbr", "ps", "peg"]:
                valuation_score += score
            else:
                quality_score += score
        rows.append({"항목": title, "값": display_value or "-", "판정": label})

    if data_count == 0:
        headline = "밸류 데이터 부족"
        color = "#64748b"
        is_kr = is_kr_listed(ticker)
        note = (
            "yfinance 및 네이버 증권에서 현재 종목의 밸류/성장 지표를 가져오지 못했습니다. "
            "네이버 증권 앱에서 직접 확인하세요."
            if is_kr else
            "yfinance에서 현재 종목의 밸류/성장 지표를 충분히 제공하지 않았습니다."
        )
    elif valuation_score >= 4 and quality_score >= 3:
        headline = "가격매력 우수"
        color = "#16a34a"
        note = "목표가/멀티플 부담 대비 성장성과 마진이 같이 뒷받침되는 구간입니다."
    elif valuation_score >= 2 and quality_score >= 2:
        headline = "조건부 적정"
        color = "#22c55e"
        note = "기업 체력은 양호하나 신호, 실적 발표, 목표비중 안에서 분할 접근이 적합합니다."
    elif valuation_score <= 0 and quality_score >= 3:
        headline = "성장 프리미엄"
        color = "#d97706"
        note = "좋은 회사일 수 있지만 가격에는 기대가 많이 반영된 구간입니다."
    elif valuation_score <= 0:
        headline = "밸류 부담"
        color = "#dc2626"
        note = "재무점수가 좋아도 현재 가격 매력은 약할 수 있어 추격매수는 보수적으로 봅니다."
    else:
        headline = "중립"
        color = "#64748b"
        note = "밸류만으로 강한 결론을 내리기 어려워 기술 신호와 실적 뉴스를 함께 봅니다."

    return {
        "headline": headline,
        "color": color,
        "note": note,
        "rows": rows,
        "target_upside": target_upside,
        "target_mean": target_mean,
        "forward_pe": forward_pe,
        "trailing_pe": trailing_pe,
        "ps": ps,
        "peg": peg,
        "revenue_growth": revenue_growth,
        "profit_margin": profit_margin,
    }


def render_valuation_price_panel(name, ticker, is_etf, c, fin_score):
    st.markdown("### 💎 밸류 / 가격매력 점검")

    if is_etf:
        st.info(
            "ETF는 개별 기업 PER/애널리스트 목표가보다 기초지수 흐름, 돈흐름 레이더, 운용보수, 괴리율을 보는 편이 더 적합합니다. "
            "단, 신규진입 실행계획의 R/R 목표가는 애널리스트 목표가가 아니라 최근 고점과 ATR로 계산한 차트 구조 목표가입니다."
        )
        return

    snapshot = fetch_valuation_snapshot(ticker)
    data = snapshot.get("data", {}) if snapshot.get("ok") else {}
    analyst_snapshot = get_analyst_snapshot(ticker)
    analyst_data = analyst_snapshot.get("data", {}) if analyst_snapshot.get("ok") else {}
    for key in ["targetMeanPrice", "targetMedianPrice", "numberOfAnalystOpinions", "recommendationKey", "currentPrice", "regularMarketPrice"]:
        if data.get(key) in [None, ""] and analyst_data.get(key) not in [None, ""]:
            data[key] = analyst_data.get(key)

    cur_p = clean_float(c.get("cur_p"), np.nan)
    valuation = build_valuation_interpretation(data, cur_p, ticker)

    v1, v2, v3, v4 = st.columns(4)
    v1.metric("밸류 판정", valuation["headline"])
    v2.metric("목표가 업사이드", format_backtest_percent(valuation["target_upside"]) or "-")
    pe_display = fmt_multiple(valuation["forward_pe"]) if finite_num(valuation["forward_pe"]) else fmt_multiple(valuation["trailing_pe"])
    v3.metric("PER", pe_display)
    v4.metric("PSR", fmt_multiple(valuation["ps"]))

    st.markdown(
        f"<div class='info-panel' style='border-left: 5px solid {valuation['color']};'>"
        f"<b>{escape_html_value(name)} 가격매력 해석</b><br>"
        f"<span class='highlight' style='font-size:1.05em;'>{valuation['headline']}</span><br>"
        f"{escape_html_value(valuation['note'])}<br>"
        f"<span style='color:#cbd5e1;'>재무점수 {fin_score}/4 종목이라도, 밸류 부담이 높으면 분할/대기가 더 유리할 수 있습니다.</span>"
        f"</div>",
        unsafe_allow_html=True,
    )

    show_rows = valuation["rows"]
    if show_rows:
        with st.expander("밸류 세부 지표", expanded=False):
            st.dataframe(pd.DataFrame(show_rows), width='stretch', hide_index=True)
    if not snapshot.get("ok"):
        st.caption(f"밸류 데이터 참고: {snapshot.get('reason', '제공 데이터 없음')}")


def get_valuation_headline_for_final_check(ticker, is_etf, current_price):
    if is_etf:
        return "ETF 별도판단", "ETF는 밸류보다 추세/돈흐름/괴리율 중심으로 봅니다.", np.nan

    snapshot = fetch_valuation_snapshot(ticker)
    data = snapshot.get("data", {}) if snapshot.get("ok") else {}
    analyst_snapshot = get_analyst_snapshot(ticker)
    analyst_data = analyst_snapshot.get("data", {}) if analyst_snapshot.get("ok") else {}
    for key in ["targetMeanPrice", "targetMedianPrice", "numberOfAnalystOpinions", "recommendationKey", "currentPrice", "regularMarketPrice"]:
        if data.get(key) in [None, ""] and analyst_data.get(key) not in [None, ""]:
            data[key] = analyst_data.get(key)

    valuation = build_valuation_interpretation(data, current_price, ticker)
    return valuation["headline"], valuation["note"], valuation["target_upside"]


def final_check_status_style(status):
    if status == "통과":
        return "#16a34a"
    if status == "주의":
        return "#d97706"
    if status == "차단":
        return "#dc2626"
    return "#64748b"


def build_pre_buy_final_checks(name, ticker, is_etf, c, fin_score, has_pos, my_price):
    rows = []

    def add_check(category, status, detail):
        rows.append({"점검항목": category, "상태": status, "해석": detail})

    dec = str(c.get("dec", ""))
    trend = str(c.get("trend", ""))
    rs_label = str(c.get("rs_label", ""))
    structure_risk = bool(c.get("structure_risk"))
    live_gap_shock = bool(c.get("live_gap_shock"))
    mfi = clean_float(c.get("mfi"), np.nan)
    rsi = clean_float(c.get("rsi"), np.nan)
    pct_b = clean_float(c.get("pct_b"), np.nan)
    dd = clean_float(c.get("dd"), 0.0)
    day_ret = clean_float(c.get("day_ret"), 0.0)
    curr_w = clean_float(c.get("current_w"), 0.0)
    target_w = clean_float(c.get("target_w"), 0.0)
    weight_gap = target_w - curr_w
    core_dca_rate = clean_float(c.get("core_dca_rate"), 0.0)
    is_core_dca = core_dca_rate > 0 and str(c.get("bucket", "")) == "core"
    macro_risk = clean_float(st.session_state.get("_app_final_macro_risk", np.nan), np.nan)
    mtf_bias_label = str(c.get("mtf_bias_label", ""))
    mtf_bias_text = str(c.get("mtf_bias_text", ""))
    rr_ratio = clean_float(c.get("rr_ratio"), np.nan)
    price_vs_avg = np.nan
    if has_pos and clean_float(my_price, 0.0) > 0 and clean_float(c.get("cur_p"), 0.0) > 0:
        price_vs_avg = clean_float(c.get("cur_p"), 0.0) / clean_float(my_price, 0.0) - 1

    hard_words = ["하드차단", "진입보류", "추격금지", "구조훼손", "추매금지", "현금 확보", "원인 점검", "실시간 급락", "레버리지 급락"]
    positive_words = ["매수", "진입", "S급", "적립", "승인", "탑승", "반등"]
    if any(word in dec for word in hard_words):
        add_check("시스템 타점", "차단", f"현재 판정이 '{dec}'입니다. 신호가 풀릴 때까지 신규/추매는 보수적으로 봅니다.")
    elif "프리장 반등" in dec:
        add_check("시스템 타점", "주의", f"현재 판정이 '{dec}'입니다. 프리장 반등은 정규장 초반 거래량과 지지 확인 후 판단합니다.")
    elif any(word in dec for word in positive_words):
        add_check("시스템 타점", "통과", f"현재 판정이 '{dec}'입니다. 다만 비중과 과열 여부를 함께 봅니다.")
    else:
        add_check("시스템 타점", "주의", f"현재 판정이 '{dec}'입니다. 강한 매수 신호라기보다 확인 구간입니다.")

    if is_etf:
        add_check("재무/상품", "통과", "ETF/ETN류는 개별기업 재무점수 대신 기초자산, 돈흐름, 추세를 봅니다.")
    elif int(fin_score) >= 4:
        add_check("재무/상품", "통과", "재무 4점입니다. 장기 후보로 볼 수 있는 기본 체력은 양호합니다.")
    elif int(fin_score) >= 3:
        add_check("재무/상품", "주의", "재무 3점입니다. 장기보유보다는 실적 개선 지속 여부 확인이 필요합니다.")
    else:
        add_check("재무/상품", "차단", "재무점수가 낮습니다. 기술 신호가 좋아도 장기보유 후보로 보기 어렵습니다.")

    is_leveraged_product = bool(c.get("is_leveraged_or_inverse")) or is_leveraged_or_inverse_product(name, ticker, "")
    if is_leveraged_product and day_ret <= -0.08:
        add_check("레버리지", "차단", f"현재/전거래일 대비 {day_ret * 100:.1f}% 급락입니다. 레버리지 상품은 가격이 내려왔다는 이유만으로 추매하지 않고 종가·기초지수 회복을 먼저 확인합니다.")
    elif is_leveraged_product:
        add_check("레버리지", "주의", "레버리지/인버스 상품입니다. 일반 ETF보다 손실 속도와 복리 훼손이 커서 목표비중과 손절 기준을 더 엄격하게 봅니다.")

    if is_etf and bool(c.get("short_history")):
        add_check("데이터", "주의", f"가격 데이터가 {int(clean_float(c.get('history_days'), 0))}거래일 수준입니다. MA50/MA120 같은 장기 추세보다 RSI/MFI/볼린저/평단 기준 단기 관측을 우선합니다.")

    if is_etf and is_core_dca and bool(c.get("short_history")):
        verification = build_new_core_etf_verification(name, ticker, str(c.get("asset_class", "") or ""), c)
        code = str(verification.get("verdict_code", "wait"))
        if code == "pass":
            add_check("신규ETF 2차검증", "통과", f"{verification.get('verdict')}: {verification.get('detail')}")
        elif code in ("caution", "conditional"):
            add_check("신규ETF 2차검증", "주의", f"{verification.get('verdict')}: {verification.get('detail')}")
        else:
            add_check("신규ETF 2차검증", "차단", f"{verification.get('verdict')}: {verification.get('detail')}")

    valuation_headline, valuation_note, target_upside = get_valuation_headline_for_final_check(ticker, is_etf, c.get("cur_p"))
    if valuation_headline in ["가격매력 우수", "조건부 적정", "ETF 별도판단"]:
        val_status = "통과"
    elif valuation_headline in ["성장 프리미엄", "중립", "밸류 데이터 부족"]:
        val_status = "주의"
    else:
        val_status = "차단"
    upside_text = "" if not finite_num(target_upside) else f" 목표가 업사이드 {target_upside:.1f}%."
    add_check("밸류/가격", val_status, f"{valuation_headline}. {valuation_note}{upside_text}")

    if is_core_dca and dd <= -0.2:
        add_check("구조/추세", "주의", f"52주 고점대비 {dd * 100:.1f}%. 코어 ETF 급락 구간은 원인 확인 후 파킹자산 일부 투입 후보로 봅니다.")
    elif live_gap_shock:
        add_check("구조/추세", "차단", f"현재/전거래일 대비 {clean_float(c.get('day_ret'), 0.0) * 100:.1f}% 실시간 급락 구간입니다. 정규장 종가와 거래량 확인 전 신규/추매는 보류합니다.")
    elif structure_risk or dd <= -0.2:
        add_check("구조/추세", "차단", f"52주 고점대비 {dd * 100:.1f}% 또는 구조위험이 있습니다. 원인 확인 전 추매는 금지에 가깝게 봅니다.")
    elif "역배열" in trend or "약함" in rs_label:
        add_check("구조/추세", "주의", f"{trend} / {rs_label}. 추세 회복을 확인하고 접근하는 쪽이 낫습니다.")
    else:
        add_check("구조/추세", "통과", f"{trend} / {rs_label}. 즉시 구조 경고는 크지 않습니다.")

    if mtf_bias_label == "상위 시간대 경고":
        add_check("상위 시간대", "차단", mtf_bias_text or "주봉/월봉 흐름이 일봉 신호와 충돌합니다. 신규/추매는 보류가 우선입니다.")
    elif mtf_bias_label == "정찰만 적합":
        add_check("상위 시간대", "주의", mtf_bias_text or "주봉/월봉 가격대가 높아 풀진입보다 1차 정찰만 적합합니다.")
    elif mtf_bias_label == "상위 시간대 우호":
        add_check("상위 시간대", "통과", mtf_bias_text or "일봉과 주봉/월봉 흐름이 크게 충돌하지 않습니다.")
    elif mtf_bias_label:
        add_check("상위 시간대", "주의", mtf_bias_text or "상위 시간대 확인이 필요합니다.")

    if is_core_dca and ((finite_num(mfi) and mfi >= 85) or (finite_num(rsi) and rsi >= 75) or (finite_num(pct_b) and pct_b >= 1.02)):
        add_check("과열", "주의", f"MFI {mfi:.1f}, RSI {rsi:.1f}, %B {pct_b:.2f}. 코어 ETF라 추격매수 대신 {c.get('core_dca_label', '속도 조절 적립')}으로 제한합니다.")
    elif (finite_num(mfi) and mfi >= 85) or (finite_num(rsi) and rsi >= 75) or (finite_num(pct_b) and pct_b >= 1.02):
        add_check("과열", "차단", f"MFI {mfi:.1f}, RSI {rsi:.1f}, %B {pct_b:.2f}. 추격매수 부담이 큽니다.")
    elif (finite_num(mfi) and mfi >= 80) or (finite_num(rsi) and rsi >= 70) or (finite_num(pct_b) and pct_b >= 0.95):
        add_check("과열", "주의", f"MFI {mfi:.1f}, RSI {rsi:.1f}, %B {pct_b:.2f}. 눌림 대기가 더 유리할 수 있습니다.")
    else:
        add_check("과열", "통과", f"MFI {mfi:.1f}, RSI {rsi:.1f}, %B {pct_b:.2f}. 극단 과열은 아닙니다.")

    if finite_num(rr_ratio):
        if bool(c.get("rr_target_is_projection", False)):
            add_check("손익비", "주의", f"현재가 기준 R/R {rr_ratio:.2f}. +4ATR 투영값 기준이라 확정 목표가로 보지 말고 +1ATR/+2ATR 분할익절과 추적손절을 우선하세요.")
        elif rr_ratio < 1.0:
            add_check("손익비", "차단", f"현재가 기준 R/R {rr_ratio:.2f}. 기대수익보다 손절폭이 커서 현재가 실행은 보류가 맞습니다.")
        elif rr_ratio < 1.5:
            add_check("손익비", "주의", f"현재가 기준 R/R {rr_ratio:.2f}. 풀비중보다 1차 정찰 중심이 맞습니다.")
        else:
            add_check("손익비", "통과", f"현재가 기준 R/R {rr_ratio:.2f}. 최소 손익비 조건은 충족합니다.")
    else:
        add_check("손익비", "주의", "R/R을 산출하지 못했습니다. 목표가/손절가 확인 전에는 분할 규모를 낮추세요.")

    if has_pos and target_w <= 0 and curr_w > 0:
        add_check("비중", "차단", f"현재 {curr_w:.2f}% / 목표 {target_w:.2f}%. 목표비중이 0%라 추가매수 대상이 아닙니다.")
    elif target_w > 0 and curr_w >= target_w:
        add_check("비중", "차단", f"현재 {curr_w:.2f}% / 목표 {target_w:.2f}%. 목표비중을 이미 채웠습니다.")
    elif target_w > 0 and weight_gap > 0:
        add_check("비중", "통과", f"현재 {curr_w:.2f}% / 목표 {target_w:.2f}%. 남은 여유비중 {weight_gap:.2f}%p입니다.")
    else:
        add_check("비중", "주의", "목표비중이 없거나 부족 매수액 계산이 약합니다. 먼저 목표비중을 정하는 편이 좋습니다.")

    if finite_num(macro_risk) and macro_risk >= 4.5:
        add_check("매크로", "차단", f"매크로 리스크 {macro_risk:.1f}. 시장 환경상 대피/관망 우선입니다.")
    elif finite_num(macro_risk) and macro_risk >= 2.5:
        add_check("매크로", "주의", f"매크로 리스크 {macro_risk:.1f}. 분할 접근이 적합합니다.")
    else:
        add_check("매크로", "통과", "-" if not finite_num(macro_risk) else f"매크로 리스크 {macro_risk:.1f}. 큰 차단 신호는 아닙니다.")

    if not has_pos:
        if trend == "🚀정배열(상승)" and rs_label == "🚀강함":
            add_check("보유상태", "통과", "신규 진입. 추세/RS가 양호해 정찰 비중으로 시작 가능합니다.")
        else:
            add_check("보유상태", "주의", "신규 진입. 첫 진입은 정찰 비중으로 시작하는 편이 안전합니다.")
    elif finite_num(price_vs_avg) and price_vs_avg < -0.07:
        add_check("보유상태", "주의", f"평단 대비 {price_vs_avg * 100:.1f}%. 추가매수보다 손상 원인 확인이 먼저입니다.")
    elif finite_num(price_vs_avg):
        add_check("보유상태", "통과", f"평단 대비 {price_vs_avg * 100:.1f}%. 보유 관리 범위 안에서 판단 가능합니다.")
    else:
        add_check("보유상태", "통과", "보유 정보 기준의 특이 위험은 크지 않습니다.")

    status_counts = pd.Series([row["상태"] for row in rows]).value_counts().to_dict()
    block_count = int(status_counts.get("차단", 0))
    caution_count = int(status_counts.get("주의", 0))
    pass_count = int(status_counts.get("통과", 0))

    if block_count >= 2:
        final_label, final_color, action = "매수 금지", "#dc2626", "차단 항목이 2개 이상입니다. 신규/추매보다 원인 점검과 비중 관리가 우선입니다."
    elif block_count == 1:
        final_label, final_color, action = "대기", "#d97706", "차단 항목이 남아 있습니다. 해당 항목이 해소될 때까지 정찰 이상은 보류합니다."
    elif caution_count >= 3:
        final_label, final_color, action = "소액 분할", "#d97706", "주의 항목이 많습니다. 매수한다면 소액 정찰 또는 분할 접근이 적합합니다."
    elif pass_count >= 6 and caution_count <= 2:
        final_label, final_color, action = "분할 가능", "#16a34a", "대부분의 점검을 통과했습니다. 목표비중 안에서 분할 접근을 검토할 수 있습니다."
    else:
        final_label, final_color, action = "조건부 관망", "#64748b", "강한 결론은 아닙니다. 신호, 실적 뉴스, 밸류 중 하나가 더 확인되면 좋습니다."

    return rows, {
        "final_label": final_label,
        "final_color": final_color,
        "action": action,
        "pass_count": pass_count,
        "caution_count": caution_count,
        "block_count": block_count,
    }


def render_pre_buy_final_check_panel(name, ticker, is_etf, c, fin_score, has_pos, my_price):
    st.markdown("### ✅ 매수 전 최종 체크")
    rows, summary = build_pre_buy_final_checks(name, ticker, is_etf, c, fin_score, has_pos, my_price)

    k1, k2, k3, k4 = st.columns(4)
    k1.metric("최종 판정", summary["final_label"])
    k2.metric("통과", f"{summary['pass_count']}개")
    k3.metric("주의", f"{summary['caution_count']}개")
    k4.metric("차단", f"{summary['block_count']}개")

    st.markdown(
        f"<div class='info-panel' style='border-left: 5px solid {summary['final_color']};'>"
        f"<b>{escape_html_value(name)} 최종 액션</b><br>"
        f"<span class='highlight' style='font-size:1.08em;'>{summary['final_label']}</span><br>"
        f"{escape_html_value(summary['action'])}<br>"
        f"<span style='color:#cbd5e1;'>투자 권유가 아니라, 현재 앱 지표를 한 번에 묶은 의사결정 보조 체크입니다.</span>"
        f"</div>",
        unsafe_allow_html=True,
    )

    show_df = pd.DataFrame(rows)
    if not show_df.empty:
        show_df["상태"] = show_df["상태"].apply(lambda x: f"{x}")
    st.dataframe(show_df, width='stretch', hide_index=True)

# ─────────────────────────────────────────────────
# [삽입 위치] render_pre_buy_final_check_panel 함수
# 정의 바로 아래 (~5825라인 이후)에 이 함수를 추가
# ─────────────────────────────────────────────────

def detect_fin_trend_direction(fin_meta: dict) -> dict:
    """재무가 좋아지고 있는지 나빠지고 있는지 방향성을 감지합니다."""
    notes, metrics, _ = get_fin_meta_parts(fin_meta)
    derived = metrics.get("derived", {}) if isinstance(metrics, dict) else {}

    rev_growth = clean_float(derived.get("rev_growth"), np.nan)
    prev_rev_growth = clean_float(derived.get("prev_rev_growth"), np.nan)
    q_rev_growth = clean_float(derived.get("q_rev_growth"), np.nan)
    q_op_growth = clean_float(derived.get("q_op_growth"), np.nan)
    net_growth = clean_float(derived.get("net_growth"), np.nan)
    ocf_growth = clean_float(derived.get("ocf_growth"), np.nan)

    score = 0
    signals = []

    # 연간 성장 가속/둔화
    if finite_num(rev_growth) and finite_num(prev_rev_growth):
        delta = rev_growth - prev_rev_growth
        if delta >= 5:
            signals.append(f"✅ 매출 성장 가속 ({prev_rev_growth:.1f}%→{rev_growth:.1f}%)")
            score += 2
        elif delta <= -15 and rev_growth < 5:
            signals.append(f"🚨 매출 성장 급둔화 ({prev_rev_growth:.1f}%→{rev_growth:.1f}%)")
            score -= 3
        elif delta <= -8:
            signals.append(f"⚠️ 매출 성장 둔화 ({prev_rev_growth:.1f}%→{rev_growth:.1f}%)")
            score -= 1

    # 분기 최신 모멘텀 (가장 최신 신호)
    if finite_num(q_rev_growth):
        if q_rev_growth >= 10:
            signals.append(f"✅ 최근 분기 매출 강세 (+{q_rev_growth:.1f}%)")
            score += 2
        elif q_rev_growth <= -15:
            signals.append(f"🚨 최근 분기 매출 급감 ({q_rev_growth:.1f}%)")
            score -= 3
        elif q_rev_growth <= -5:
            signals.append(f"⚠️ 최근 분기 매출 위축 ({q_rev_growth:.1f}%)")
            score -= 1

    if finite_num(q_op_growth):
        if q_op_growth >= 15:
            signals.append(f"✅ 최근 분기 영업이익 강세 (+{q_op_growth:.1f}%)")
            score += 1
        elif q_op_growth <= -20:
            signals.append(f"🚨 최근 분기 영업이익 급감 ({q_op_growth:.1f}%)")
            score -= 2

    # 이익의 질 (순이익 + OCF 동반 방향)
    if finite_num(net_growth) and finite_num(ocf_growth):
        if net_growth < 0 and ocf_growth < 0:
            signals.append("🚨 순이익·OCF 동반 악화: 펀더멘털 훼손")
            score -= 3
        elif net_growth > 10 and ocf_growth > 0:
            signals.append("✅ 순이익·OCF 동반 성장: 이익의 질 양호")
            score += 2

    # 방향성 레이블 결정
    if score >= 4:
        label, color = "📈 강한 개선", "#16a34a"
    elif score >= 2:
        label, color = "↗️ 개선 중", "#22c55e"
    elif score >= 0:
        label, color = "➡️ 유지", "#64748b"
    elif score >= -2:
        label, color = "↘️ 둔화", "#d97706"
    else:
        label, color = "📉 훼손 진행", "#dc2626"

    return {
        "score": score,
        "label": label,
        "color": color,
        "signals": signals,
        "is_improving": score >= 2,
        "is_deteriorating": score <= -2,
        "has_data": len(signals) > 0,
    }


def render_hold_or_cut_panel(name, ticker, is_etf, fin_score, fin_meta,
                              c, my_price, has_pos):
    """
    보유 지속 vs 손절 종합 판단 패널.
    보유 중일 때만 표시. 재무 방향성 + 기술 + 손익 종합.
    """
    if not has_pos:
        return

    cur_p = clean_float(c.get("cur_p"), 0.0)
    dd = clean_float(c.get("dd"), 0.0)
    trend = str(c.get("trend", ""))
    rs_label = str(c.get("rs_label", ""))
    price_vs_avg = (cur_p / my_price - 1) if my_price > 0 and cur_p > 0 else 0.0

    st.markdown("### 🏛️ 보유 지속 vs 손절 종합 판단")
    st.caption("재무 방향성(좋아지고 있나 나빠지고 있나) + 기술 구조 + 내 손익을 종합합니다.")

    # ── 점수 계산 ──────────────────────────────
    total_score = 0
    hold_reasons = []
    cut_reasons = []
    fin_trend = {}

    # 재무 방향성 (개별주만)
    if not is_etf:
        fin_trend = detect_fin_trend_direction(fin_meta)
        total_score += fin_trend["score"]
        for sig in fin_trend.get("signals", []):
            if "✅" in sig:
                hold_reasons.append(sig)
            else:
                cut_reasons.append(sig)

        # 재무점수 스냅샷
        if fin_score >= 4:
            total_score += 2
            hold_reasons.append("재무점수 4점: 완성형 우량주")
        elif fin_score <= 1:
            total_score -= 4
            cut_reasons.append("재무점수 1점: 구조적 문제")
        elif fin_score == 2:
            total_score -= 1
            cut_reasons.append("재무점수 2점: 불안정")
    else:
        total_score += 1
        hold_reasons.append("ETF: 개별기업 부도 리스크 없음")

    # 기술 구조
    if "정배열" in trend:
        total_score += 2
        hold_reasons.append("MA 정배열: 중기 추세 유효")
    elif "역배열" in trend:
        total_score -= 2
        cut_reasons.append("MA 역배열: 추세 훼손 상태")

    if rs_label == "🚀강함":
        total_score += 2
        hold_reasons.append("RS 강함: 시장/섹터 대비 자금 유입 중")
    elif rs_label == "🐢약함":
        total_score -= 2
        cut_reasons.append("RS 약함: 돈이 다른 종목/섹터로 이동 중")

    # MDD
    if dd <= -0.30:
        total_score -= 3
        cut_reasons.append(f"고점대비 {dd*100:.1f}%: 구조적 손상 수준")
    elif dd <= -0.20:
        total_score -= 1
        cut_reasons.append(f"고점대비 {dd*100:.1f}%: 추세 훼손 주의")
    elif dd > -0.10:
        total_score += 1
        hold_reasons.append("고점 근처 유지: 추세 건전")

    # 내 손익
    if price_vs_avg <= -0.20:
        total_score -= 2
        cut_reasons.append(f"평단 대비 {price_vs_avg*100:.1f}%: 손실 규모 점검")
    elif price_vs_avg <= -0.10:
        total_score -= 1
        cut_reasons.append(f"평단 대비 {price_vs_avg*100:.1f}%: 원인 확인 필요")
    elif price_vs_avg > 0.20:
        total_score += 1
        hold_reasons.append(f"평단 대비 +{price_vs_avg*100:.1f}%: 안전마진 확보")

    # 매크로
    macro_risk = clean_float(st.session_state.get("_app_final_macro_risk", 0), 0.0)
    if macro_risk >= 4.5:
        total_score -= 2
        cut_reasons.append("퍼펙트스톰: 전체 리스크 상승")
    elif macro_risk >= 2.5:
        total_score -= 1
        cut_reasons.append(f"매크로 리스크 {macro_risk:.1f}: 보수적 접근")

    # ── 하드 손절 조건 ──────────────────────────
    hard_cut = (
        (not is_etf and fin_score <= 1) or
        (price_vs_avg <= -0.25 and dd <= -0.25 and "역배열" in trend)
    )

    # ── 최종 판정 ──────────────────────────────
    if hard_cut:
        decision, color = "❌ 손절 강력 검토", "#7f1d1d"
        action = "재무 훼손 + 기술 손상 동시 발생. 손실이 더 커지기 전에 포지션 정리를 검토하세요."
    elif total_score >= 6:
        decision, color = "💎 장기보유 적합", "#16a34a"
        action = "재무 방향성·추세·RS 모두 살아있습니다. 목표비중까지 보유 유지, 추가 확대도 검토 가능."
    elif total_score >= 3:
        decision, color = "✅ 조건부 보유", "#22c55e"
        action = "대부분 건전합니다. 다음 실적 발표에서 방향성 재확인 후 추매 여부 결정."
    elif total_score >= 0:
        decision, color = "⚠️ 모니터링 강화", "#d97706"
        action = "긍·부정 혼재. 추매 보류, 다음 트리거(실적/추세 회복)까지 대기."
    elif total_score >= -3:
        decision, color = "📉 비중 축소 검토", "#f97316"
        action = "부정 신호 우세. 일부 익절 또는 비중을 줄이고 현금화 고려."
    else:
        decision, color = "🚨 손절 검토", "#dc2626"
        action = "여러 훼손 신호 동시 발생. 손절선을 명확히 설정하고 지키세요."

    # ── UI 렌더링 ───────────────────────────────
    h1, h2, h3, h4 = st.columns(4)
    h1.metric("종합 판정", decision.split(" ", 1)[-1])
    h2.metric("종합 점수", f"{total_score:+d}점")
    h3.metric("평단 대비", f"{price_vs_avg*100:.1f}%" if finite_num(price_vs_avg) else "-")
    fin_dir_label = fin_trend.get("label", "ETF") if not is_etf else "ETF"
    h4.metric("재무 방향", fin_dir_label)

    st.markdown(
        f"<div class='info-panel' style='border-left:6px solid {color};'>"
        f"<b>{escape_html_value(name)} 보유 판단</b><br>"
        f"<span class='highlight' style='color:{color};font-size:1.15em;'>"
        f"{escape_html_value(decision)}</span><br><br>"
        f"{escape_html_value(action)}"
        f"</div>",
        unsafe_allow_html=True,
    )

    rc1, rc2 = st.columns(2)
    with rc1:
        st.markdown("**✅ 보유 근거**")
        if hold_reasons:
            for r in hold_reasons:
                st.markdown(f"- {r}")
        else:
            st.caption("보유 근거 부족")
    with rc2:
        st.markdown("**🚨 우려 근거**")
        if cut_reasons:
            for r in cut_reasons:
                st.markdown(f"- {r}")
        else:
            st.caption("주요 우려 없음")

    # 재무 방향성 상세 (개별주만)
    if not is_etf and fin_trend.get("has_data"):
        with st.expander("재무 방향성 상세"):
            st.markdown(
                f"**방향**: {fin_trend['label']} (방향점수 {fin_trend['score']:+d})<br>"
                f"분기가 가장 최신 신호입니다. 연간은 추세, 분기는 현재 모멘텀으로 봅니다.",
                unsafe_allow_html=True,
            )
            for sig in fin_trend["signals"]:
                st.markdown(f"- {sig}")
            st.caption("재무 방향성은 DART/FMP 자동 계산 데이터 기반입니다. 재무점수를 먼저 돌린 뒤 봐야 정확합니다.")


def prefetch_price_data_parallel(tickers: list, period: str = "1y", max_workers: int = 8):
    """
    [속도 개선] 여러 티커의 가격 데이터를 ThreadPoolExecutor로 병렬 선제 로딩합니다.
    load_price_df가 @st.cache_data를 사용하므로 병렬 호출 후 캐시에 저장됩니다.
    이후 순차 호출 시 캐시 히트로 즉시 반환됩니다.
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    if not tickers:
        return
    def _fetch(tkr):
        try:
            return load_price_df(tkr, period)
        except Exception:
            return None
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(_fetch, tkr): tkr for tkr in tickers}
        for future in as_completed(futures):
            future.result()  # 예외가 있으면 무시하고 계속


def build_summary_status_item(item, reason, code="DATA_UNAVAILABLE", snap_final_macro_risk=np.nan):
    """Build a visible today-queue row when a ticker cannot be judged."""
    tkr = sanitize_ticker_value(item.get("ticker", ""))
    name = sanitize_asset_name(item.get("name", ""), tkr)
    is_etf = is_fin_score_exempt_asset(tkr, item.get("is_etf", False), item.get("asset_class", ""), name)
    label = "⚠️데이터 없음: 가격조회 실패" if code == "DATA_UNAVAILABLE" else "⚠️판단 오류: 점검 필요"
    row = {
        "시장": get_dashboard_market_label(tkr),
        "유형": get_dashboard_type_label(is_etf),
        "전광판그룹": get_dashboard_group_label(tkr, is_etf),
        "종목명": name,
        "티커": tkr,
        "현재가": "-",
        "MDD": "-",
        "고점대비": "-",
        "재무점수": "해당없음" if is_etf else "-",
        "📌후보등급": "판단불가",
        "RS": "-",
        "시장벤치": "-",
        "기초자산": "-",
        "기초벤치": "-",
        "섹터벤치": "-",
        "섹터RS": "-",
        "RSI": np.nan,
        "MFI": np.nan,
        "볼린저 %B": np.nan,
        "🔥기술적 타점": label,
        "핵심근거": reason,
        "판정코드": code,
        "판정분류": DECISION_GROUP_BY_CODE.get(code) or "caution",
        "Adj점수": np.nan,
        "안전상태": "DATA",
        "매크로상태": classify_macro_state(snap_final_macro_risk),
        "데이터상태": reason,
        "bucket": str(item.get("bucket", "")),
        "버킷": str(item.get("bucket", "")),
        "비중차이": 0.0,
    }
    return {"tkr": tkr, "f_score": None, "row": row}


def is_dashboard_low_rr_caution(c: dict) -> bool:
    label = str((c or {}).get("dec", "") or "")
    rr = clean_float((c or {}).get("rr_ratio"), np.nan)
    if not np.isfinite(rr) or rr >= 1.0:
        return False
    if is_dashboard_block_or_wait_label(label):
        return False
    return any(word in label for word in ("매수", "진입", "추매", "탑승", "분할"))


def is_dashboard_block_or_wait_label(label: str) -> bool:
    return any(word in str(label or "") for word in ("금지", "차단", "보류", "대기", "관망", "정리대상"))


def is_dashboard_actionable_signal(c: dict) -> bool:
    label = str((c or {}).get("dec", "") or "")
    if is_dashboard_block_or_wait_label(label):
        return False
    return any(word in label for word in ("매수", "진입", "추매", "탑승", "분할", "눌림", "정찰", "적립"))


def format_dashboard_timing_label(c: dict) -> str:
    label = str((c or {}).get("dec", "") or "")
    if not label:
        return label
    notes = []
    if is_dashboard_low_rr_caution(c):
        notes.append("R/R<1 정찰")
    if is_dashboard_actionable_signal(c) and str((c or {}).get("mtf_bias_label", "")) == "정찰만 적합":
        if "상위과열" not in label and "정찰만" not in label:
            notes.append("상위과열 정찰")
    for note in notes:
        if note not in label:
            label = f"{label} / {note}"
    return label


def format_dashboard_candidate_grade(c: dict) -> str:
    grade = str((c or {}).get("grade", "") or "")
    label = str((c or {}).get("dec", "") or "")
    code = str((c or {}).get("decision_code", "") or "")
    curr_w = clean_float((c or {}).get("current_w"), 0.0)
    target_w = clean_float((c or {}).get("target_w"), 0.0)
    hard_codes = {
        "TARGET_ZERO_NO_ADD",
        "LEVERAGED_DAILY_DROP_NO_ADD",
        "HARD_BLOCK_OVERWEIGHT",
        "HARD_BLOCK_TARGET_FILLED",
        "HARD_BLOCK_MACRO_STORM",
        "STRUCTURE_DAMAGE_HOLDING_CHECK",
        "STRUCTURE_DAMAGE_NO_ENTRY",
        "MTF_DAMAGE_NO_ADD",
    }
    if code == "TARGET_ZERO_NO_ADD" or (curr_w > 0 and target_w <= 0):
        return "🛑후보제외(목표0%)"
    if code in hard_codes or any(word in label for word in ("추매금지", "하드차단", "구조훼손", "레버리지 급락")):
        return "🛑매수금지"
    badges = []
    if is_dashboard_low_rr_caution(c):
        badges.append("⚠️R/R<1")
    if is_dashboard_actionable_signal(c) and str((c or {}).get("mtf_bias_label", "")) == "정찰만 적합":
        badges.append("🟡정찰")
    if badges:
        return f"{grade} / {' · '.join(badges)}" if grade else " · ".join(badges)
    return grade


def format_dashboard_reason(c: dict) -> str:
    reasons = tuple((c or {}).get("decision_reasons") or ())
    base = str(reasons[0]) if reasons else ""
    if is_dashboard_actionable_signal(c) and str((c or {}).get("mtf_bias_label", "")) == "정찰만 적합":
        mtf_note = "상위 시간대 과열: 풀비중보다 정찰/대기"
        base = f"{base} / {mtf_note}" if base else mtf_note
    if is_dashboard_low_rr_caution(c):
        rr = clean_float((c or {}).get("rr_ratio"), np.nan)
        rr_note = f"R/R {rr:.2f}: 현재가 풀진입 보류"
        return f"{base} / {rr_note}" if base else rr_note
    return base


def _compute_summary_item(item, mode, snap_macro_penalty, snap_final_macro_risk, snap_total_eval,
                          snap_cash_available, snap_reserve_available):
    """워커 함수: CPU 계산만 담당. session_state 쓰기 없음 (스레드 안전).
    매크로 전역값은 호출 시점에 스냅샷으로 전달받아 스레드 안전성을 보장합니다."""
    tkr = sanitize_ticker_value(item.get("ticker", ""))
    name = sanitize_asset_name(item.get("name", ""), tkr)
    if not tkr:
        return None
    is_etf = is_fin_score_exempt_asset(tkr, item.get("is_etf", False), item.get("asset_class", ""), name)
    a_class = infer_asset_class_for_ticker(tkr, item.get("asset_class", "")) if is_etf else item.get("asset_class", "")

    try:
        df = load_price_df(tkr, "1y")
    except Exception as exc:
        return build_summary_status_item(
            item,
            f"가격 데이터 조회 예외: {type(exc).__name__}",
            code="DATA_ERROR",
            snap_final_macro_risk=snap_final_macro_risk,
        )
    if df.empty:
        return build_summary_status_item(
            item,
            "가격 데이터가 비어 있어 판단하지 않음",
            code="DATA_UNAVAILABLE",
            snap_final_macro_risk=snap_final_macro_risk,
        )
    # tail(300)으로 슬라이싱해 TA 계산량 제한 (1y ≈ 250행이라 실질적 안전망)
    try:
        df = build_indicators(df.tail(300))
    except Exception as exc:
        return build_summary_status_item(
            item,
            f"지표 계산 예외: {type(exc).__name__}",
            code="DATA_ERROR",
            snap_final_macro_risk=snap_final_macro_risk,
        )

    try:
        final_fin_score, _ = load_fin_score_meta_fast(tkr, is_etf)
        f_score = int(final_fin_score)

        my_p = get_my_price(name, tkr)
        has_p = has_position(name, tkr)
        _live_p = load_latest_price(tkr)  # 프리마켓·애프터마켓 실시간가 (캐시 TTL=60s)

        c = calc_scores_and_decision(
            name=name, ticker=tkr, is_etf=is_etf, asset_class=a_class, df=df,
            my_price=my_p, has_pos=has_p, fin_score=f_score, is_free=False, app_mode=mode,
            _macro_penalty=snap_macro_penalty,
            _final_macro_risk=snap_final_macro_risk,
            _total_eval=snap_total_eval,
            _cash_available=snap_cash_available,
            _reserve_available=snap_reserve_available,
            live_price=_live_p,
        )
        if is_dashboard_actionable_signal(c):
            try:
                mtf_pack = build_precision_multi_timeframe_pack(tkr, df)
                c = apply_precision_mtf_decision_guard(c, mtf_pack, has_pos=has_p)
            except Exception:
                pass
    except Exception as exc:
        return build_summary_status_item(
            item,
            f"판단 계산 예외: {type(exc).__name__}",
            code="DATA_ERROR",
            snap_final_macro_risk=snap_final_macro_risk,
        )

    # 벤치마크 단일 진입점 — prefetch_benchmark_info_parallel 이 선제 캐싱함
    bm = get_auto_benchmark_info(tkr, name, a_class, is_etf)
    dashboard_timing = format_dashboard_timing_label(c)
    dashboard_reason = format_dashboard_reason(c)
    dashboard_grade = format_dashboard_candidate_grade(c)
    if "후보제외" in dashboard_grade or "매수금지" in dashboard_grade:
        dashboard_group = "caution"
    elif is_dashboard_actionable_signal(c) or "R/R<1" in dashboard_grade or "🟡정찰" in dashboard_grade:
        dashboard_group = "buyish"
    else:
        dashboard_group = c.get("decision_group") or classify_decision_signal(dashboard_timing)

    row = {
        "시장": get_dashboard_market_label(tkr), "유형": get_dashboard_type_label(is_etf),
        "전광판그룹": get_dashboard_group_label(tkr, is_etf),
        "종목명": name, "티커": tkr, "현재가": format_currency(c["cur_p"], tkr), "MDD": f"{c['dd']*100:.1f}%",
        "고점대비": f"{c['dd']*100:.1f}%",
        "재무점수": "해당없음" if is_etf else f"{f_score}/4", "📌후보등급": dashboard_grade, "RS": c["rs_label"],
        "시장벤치": get_benchmark_display_name(bm["market_bench"]),
        "기초자산": bm["underlying_asset"] if bm["underlying_bench"] else "-",
        "기초벤치": get_benchmark_display_name(bm["underlying_bench"]) if bm["underlying_bench"] else "-",
        "섹터벤치": get_benchmark_display_name(bm["sector_bench"]) if bm["sector_bench"] else "-",
        "섹터RS": bm["sector_rs_label"] if bm["sector_bench"] else "-",
        "RSI": round(c["rsi"], 1), "MFI": round(c["mfi"], 1), "볼린저 %B": round(c["pct_b"], 2),
        "🔥기술적 타점": dashboard_timing,
        "핵심근거": dashboard_reason,
        "판정코드": c.get("decision_code", ""),
        "판정분류": dashboard_group,
        "Adj점수": round(c["adj"], 1),
        "안전상태": c.get("safety_state", ""),
        "매크로상태": c.get("macro_state", ""),
        "데이터상태": "OK",
        "bucket": c.get("bucket", ""),
        "버킷": c.get("bucket", ""),
        "비중차이": clean_float(c.get("target_w"), 0.0) - clean_float(c.get("current_w"), 0.0),
    }
    return {"tkr": tkr, "f_score": f_score, "row": row}


def get_all_summary(fin_score_map_items, mode, watchlist_items):
    from concurrent.futures import ThreadPoolExecutor, as_completed

    # [속도 개선] 전광판 종목 전체를 병렬로 선제 로딩 (이후 load_price_df는 캐시 히트)
    all_tickers = [
        sanitize_ticker_value(item.get("ticker", ""))
        for item in watchlist_items
        if sanitize_ticker_value(item.get("ticker", ""))
    ]
    prefetch_price_data_parallel(all_tickers, "1y")
    # [속도 개선] 벤치마크 정보 병렬 선제 캐싱 (이후 get_auto_benchmark_info 는 캐시 히트)
    prefetch_benchmark_info_parallel(watchlist_items)

    # 매크로 전역값을 워커 진입 전에 스냅샷 — 스레드 간 일관성 보장
    snap_mp, snap_fmr, snap_te = resolve_decision_runtime_inputs()
    snap_cash_available = get_cash_available_for_dca(mode)
    snap_reserve_available = get_reserve_available_for_crash_buy(mode)

    # 원래 순서를 보존하기 위해 인덱스를 키로 사용
    results_map: dict[int, dict] = {}
    with ThreadPoolExecutor(max_workers=6) as executor:
        futures = {
            executor.submit(
                _compute_summary_item,
                item, mode, snap_mp, snap_fmr, snap_te,
                snap_cash_available, snap_reserve_available,
            ): i
            for i, item in enumerate(watchlist_items)
        }
        for future in as_completed(futures):
            idx = futures[future]
            try:
                result = future.result()
            except Exception:
                result = None
            if result is not None:
                results_map[idx] = result

    # 메인 스레드에서 session_state 쓰기 + 원래 순서대로 rows 구성
    rows = []
    for i in range(len(watchlist_items)):
        r = results_map.get(i)
        if r is None:
            continue
        if r.get("f_score") is not None:
            st.session_state.fin_score_map[normalize_ticker(r["tkr"])] = r["f_score"]
        rows.append(r["row"])

    return pd.DataFrame(rows)


