# SECTION 14a: 포트폴리오 — 수학 & 계산 유틸
# MDD, 샤프, 상관관계, 드로다운, 10년 플랜
# ════════════════════════════════════════════════════════════════════════════

def calc_series_mdd(series):
    series = pd.Series(series).dropna()
    if series.empty:
        return 0.0

    running_max = series.cummax()
    drawdown = series / running_max - 1
    return float(drawdown.min()) if not drawdown.empty else 0.0


def calc_drawdown_details(portfolio_curve):
    """낙폭 구간 상세: 수중(underwater) 시리즈, 평균낙폭, MDD지속일, 회복일."""
    if portfolio_curve is None or len(portfolio_curve) < 2:
        return {}
    series = pd.Series(portfolio_curve).dropna()
    running_max = series.cummax()
    drawdown = series / running_max - 1
    underwater = drawdown * 100  # percent series

    in_dd = drawdown[drawdown < -0.001]
    avg_drawdown = float(in_dd.mean() * 100) if not in_dd.empty else 0.0

    # Longest continuous drawdown duration (trading days)
    dd_bool = (drawdown < -0.001)
    max_dur = cur_dur = 0
    for v in dd_bool:
        cur_dur = cur_dur + 1 if v else 0
        max_dur = max(max_dur, cur_dur)

    # Recovery time from MDD bottom
    mdd_idx = int(drawdown.argmin())
    peak_val = float(running_max.iloc[mdd_idx])
    recovery_days = np.nan
    if mdd_idx < len(series) - 1:
        post = series.iloc[mdd_idx:]
        recovered = post[post >= peak_val]
        if not recovered.empty:
            recovery_days = (recovered.index[0] - series.index[mdd_idx]).days

    # Count distinct drawdown periods
    n_periods = 0
    in_period = False
    for v in dd_bool:
        if v and not in_period:
            n_periods += 1
            in_period = True
        elif not v:
            in_period = False

    return {
        "underwater": underwater,
        "avg_drawdown": avg_drawdown,
        "mdd_duration_days": max_dur,
        "mdd_recovery_days": recovery_days,
        "n_drawdown_periods": n_periods,
    }


def infer_benchmark_leverage_multiplier(ticker, asset_name=""):
    text = f"{str(ticker or '').upper()} {str(asset_name or '').upper()}".replace(" ", "")

    inverse = any(k in text for k in ["INVERSE", "BEAR", "인버스", "곱버스", "SQQQ", "SOXS", "SPXU", "SDOW"])
    if any(k in text for k in ["3X", "3배", "TQQQ", "SOXL", "UPRO", "SPXL", "TECL", "FNGU"]):
        return -3.0 if inverse else 3.0
    if any(k in text for k in ["2X", "2배", "QLD", "SSO", "레버리지", "LEVERAGE", "ULTRA"]):
        return -2.0 if inverse else 2.0
    if inverse:
        return -1.0
    return 1.0


def infer_blended_benchmark_proxy(ticker, asset_name="", asset_class="", bucket=""):
    symbol = normalize_ticker(ticker)
    text = f"{symbol} {asset_name or ''} {asset_class or ''} {bucket or ''}".upper()
    compact = text.replace(" ", "").replace("-", "")

    if not symbol or "CASH" in symbol or normalize_bucket(bucket) in {"cash", "reserve"}:
        return None

    if any(k in compact for k in ["NASDAQ100", "NASDAQ", "나스닥100", "나스닥", "QQQ", "QQQM", "QLD", "TQQQ", "379810"]):
        return {"label": "나스닥100", "ticker": "379810.KS"}
    if any(k in compact for k in ["S&P500", "SP500", "SNP500", "에스앤피", "SPY", "VOO", "IVV", "SPLG", "379800"]):
        return {"label": "S&P500", "ticker": "379800.KS"}
    if any(k in compact for k in ["KOSPI", "코스피", "KODEX200", "KODEX 200", "069500", "KODEX200"]):
        return {"label": "코스피", "ticker": "069500.KS"}

    clean_symbol_only = symbol.split(".")[0]
    if is_kr_listed(symbol):
        return {"label": "코스피", "ticker": "069500.KS"}
    if clean_symbol_only in US_TECH_OR_GROWTH_TICKERS:
        return {"label": "나스닥100", "ticker": "379810.KS"}
    return {"label": "S&P500", "ticker": "379800.KS"}


def build_portfolio_blended_benchmark_spec(holdings_df):
    if holdings_df is None or getattr(holdings_df, "empty", True):
        return {}

    df = holdings_df.copy()
    if "티커" not in df.columns:
        return {}

    for col in ["목표비중", "현재비중", "전체비중", "원화환산"]:
        if col not in df.columns:
            df[col] = 0.0

    if "bucket" not in df.columns:
        df["bucket"] = "core"
    if "자산명" not in df.columns:
        df["자산명"] = df["티커"]

    df["티커"] = df["티커"].astype(str).str.strip()
    df = df[df["티커"].ne("")]
    df = df[~df["티커"].astype(str).str.upper().isin(["KRW_CASH", "USD_CASH"])]
    df = df[~df["bucket"].apply(lambda v: normalize_bucket(v) in {"cash", "reserve"})]
    if "운용대상" in df.columns:
        df = df[df["운용대상"].apply(clean_bool)]

    if df.empty:
        return {}

    target_sum = float(df["목표비중"].apply(clean_float).clip(lower=0).sum())
    current_sum = float(df["현재비중"].apply(clean_float).clip(lower=0).sum())
    total_value = float(df["원화환산"].apply(clean_float).clip(lower=0).sum())

    if target_sum > 0:
        weight_col = "목표비중"
        basis = "목표비중"
    elif current_sum > 0:
        weight_col = "현재비중"
        basis = "현재비중"
    elif total_value > 0:
        weight_col = "원화환산"
        basis = "현재금액"
    else:
        return {}

    merged = {}
    order = []
    for _, row in df.iterrows():
        ticker = str(row.get("티커", "")).strip()
        name = str(row.get("자산명", "") or ticker).strip()
        bucket = str(row.get("bucket", "core") or "core").strip()
        asset_class = str(row.get("asset_class", "") or row.get("자산군", "") or "").strip()

        raw_weight = clean_float(row.get(weight_col), 0.0)
        if weight_col == "원화환산" and total_value > 0:
            weight = raw_weight / total_value * 100
        else:
            weight = raw_weight
        if weight <= 0:
            continue

        proxy = infer_blended_benchmark_proxy(ticker, name, asset_class, bucket)
        if not proxy:
            continue
        multiplier = infer_benchmark_leverage_multiplier(ticker, name)
        key = (proxy["label"], proxy["ticker"], float(multiplier))
        if key not in merged:
            merged[key] = {
                "label": proxy["label"],
                "ticker": proxy["ticker"],
                "weight": 0.0,
                "multiplier": float(multiplier),
            }
            order.append(key)
        merged[key]["weight"] += float(weight)

    components = [merged[key] for key in order if merged[key]["weight"] > 0]
    total_weight = sum(comp["weight"] for comp in components)
    if not components or total_weight <= 0:
        return {}

    parts = []
    for comp in components:
        multiplier = clean_float(comp.get("multiplier"), 1.0)
        mult_txt = f"x{multiplier:g}" if abs(multiplier) != 1 else ""
        parts.append(f"{comp['label']}{mult_txt} {comp['weight']:.1f}%")

    return {
        "label": "내 목표비중 벤치",
        "basis": basis,
        "components": components,
        "description": f"{basis} 기준: " + " + ".join(parts),
    }


def get_current_blended_benchmark_spec():
    try:
        return build_portfolio_blended_benchmark_spec(globals().get("holdings_table", pd.DataFrame()))
    except Exception:
        return {}


def calc_benchmark_metrics_from_returns(portfolio_returns, benchmark_returns, label="", benchmark_ticker="", rf_rate=0.035):
    if portfolio_returns is None or portfolio_returns.empty or benchmark_returns is None or benchmark_returns.empty:
        return {}

    try:
        br_all = pd.Series(benchmark_returns).replace([np.inf, -np.inf], np.nan).dropna()
        br_all.index = normalize_datetime_index_no_tz(br_all.index)
        common = portfolio_returns.index.intersection(br_all.index)
        if len(common) < 20:
            return {}

        pr = pd.Series(portfolio_returns.loc[common]).replace([np.inf, -np.inf], np.nan).fillna(0.0)
        br = pd.Series(br_all.loc[common]).replace([np.inf, -np.inf], np.nan).fillna(0.0)

        bm_var = float(br.var())
        if bm_var <= 0:
            return {}

        beta = float(np.cov(pr.values, br.values)[0, 1] / bm_var)
        bm_period_ret = float((1 + br).prod() - 1)
        bm_annual = annualize_period_return(bm_period_ret, len(br)) if np.isfinite(bm_period_ret) else np.nan
        port_annual = annualize_period_return(float((1 + pr).prod() - 1), len(pr))

        alpha = np.nan
        if np.isfinite(bm_annual) and np.isfinite(port_annual):
            alpha = (port_annual - (rf_rate + beta * (bm_annual - rf_rate))) * 100

        active_ret = pr - br
        tracking_error = float(active_ret.std() * np.sqrt(252) * 100)
        info_ratio = ratio_or_nan(float(active_ret.mean() * 252 * 100), tracking_error)

        return {
            "beta": round(beta, 2),
            "alpha": round(alpha, 2) if np.isfinite(alpha) else np.nan,
            "tracking_error": round(tracking_error, 1),
            "info_ratio": round(info_ratio, 2) if np.isfinite(info_ratio) else np.nan,
            "bm_annual_return": round(bm_annual * 100, 1) if np.isfinite(bm_annual) else np.nan,
            "bm_period_return": round(bm_period_ret * 100, 1) if np.isfinite(bm_period_ret) else np.nan,
            "benchmark_ticker": benchmark_ticker,
            "benchmark_label": label,
            "n_common_days": len(common),
        }
    except Exception:
        return {}


def build_blended_benchmark_returns(benchmark_spec, period, analysis_start_date=None):
    if not benchmark_spec:
        return pd.Series(dtype=float)

    components = benchmark_spec.get("components", []) if isinstance(benchmark_spec, dict) else []
    if not components:
        return pd.Series(dtype=float)

    series_list = []
    weight_map = {}
    for idx, comp in enumerate(components):
        try:
            ticker = str(comp.get("ticker", "")).strip()
            weight = clean_float(comp.get("weight"), 0.0)
            multiplier = clean_float(comp.get("multiplier"), 1.0)
            if not ticker or weight <= 0:
                continue

            px_df = load_price_df(ticker, period)
            if px_df is None or px_df.empty or "Close" not in px_df.columns:
                continue
            close = pd.Series(px_df["Close"]).dropna()
            close.index = normalize_datetime_index_no_tz(close.index)
            if analysis_start_date is not None:
                close = close[close.index >= analysis_start_date]
            if len(close) < 20:
                continue

            key = f"bench_{idx}"
            ret = close.pct_change().replace([np.inf, -np.inf], np.nan).dropna() * multiplier
            if ret.empty:
                continue
            series_list.append(ret.rename(key))
            weight_map[key] = weight
        except Exception:
            continue

    if not series_list or not weight_map:
        return pd.Series(dtype=float)

    returns_df = pd.concat(series_list, axis=1).sort_index().ffill(limit=3).dropna(how="all").fillna(0.0)
    weights = pd.Series(weight_map, dtype=float)
    usable = [col for col in returns_df.columns if col in weights.index]
    if not usable:
        return pd.Series(dtype=float)

    weights = weights[usable]
    weight_sum = float(weights.sum())
    if weight_sum <= 0:
        return pd.Series(dtype=float)

    return returns_df[usable].mul(weights / weight_sum, axis=1).sum(axis=1).dropna()


def calc_blended_benchmark_comparison(portfolio_returns, benchmark_spec, period, rf_rate=0.035, analysis_start_date=None):
    benchmark_returns = build_blended_benchmark_returns(benchmark_spec, period, analysis_start_date=analysis_start_date)
    result = calc_benchmark_metrics_from_returns(
        portfolio_returns,
        benchmark_returns,
        label=benchmark_spec.get("label", "내 목표비중 벤치") if benchmark_spec else "",
        benchmark_ticker="BLENDED",
        rf_rate=rf_rate,
    )
    if result and benchmark_spec:
        result["benchmark_description"] = benchmark_spec.get("description", "")
    return result


def calc_benchmark_comparison(portfolio_returns, benchmark_ticker, period, rf_rate=0.035, analysis_start_date=None):
    """벤치마크 대비 Beta, Alpha(Jensen), Tracking Error, Information Ratio."""
    if portfolio_returns is None or portfolio_returns.empty:
        return {}
    try:
        bm_df = load_price_df(benchmark_ticker, period)
        if bm_df is None or bm_df.empty or "Close" not in bm_df.columns:
            return {}
        bm_close = pd.Series(bm_df["Close"]).dropna()
        bm_close.index = normalize_datetime_index_no_tz(bm_close.index)
        if analysis_start_date is not None:
            bm_close = bm_close[bm_close.index >= analysis_start_date]
        bm_returns = bm_close.pct_change().dropna()
        return calc_benchmark_metrics_from_returns(
            portfolio_returns,
            bm_returns,
            label=benchmark_ticker,
            benchmark_ticker=benchmark_ticker,
            rf_rate=rf_rate,
        )
    except Exception:
        return {}


def calc_rolling_metrics(portfolio_returns, window=63, rf_rate=0.035):
    """Rolling Sharpe(window일)·변동성 시리즈 반환."""
    if portfolio_returns is None or len(portfolio_returns) < window + 5:
        return pd.DataFrame()
    rolling_vol = portfolio_returns.rolling(window).std() * np.sqrt(252) * 100
    rolling_ret = portfolio_returns.rolling(window).mean() * 252
    rolling_sharpe = ((rolling_ret - rf_rate) / (rolling_vol / 100)).replace([np.inf, -np.inf], np.nan)
    df = pd.DataFrame({"rolling_vol": rolling_vol, "rolling_sharpe": rolling_sharpe}, index=portfolio_returns.index)
    return df.dropna(how="all")


# 역사적 위기 시나리오: (이름, 시작, 종료, 설명, 미국충격%, 한국충격%)
_STRESS_SCENARIOS = [
    ("2008 금융위기",      "2008-09-01", "2008-11-28", "리먼 파산, 글로벌 금융 시스템 붕괴",         -35.0, -30.0),
    ("2020 코로나 폭락",   "2020-02-20", "2020-03-23", "팬데믹 선언 직후 사상 최대 속도 급락",        -34.0, -35.0),
    ("2022 금리인상 충격", "2022-01-03", "2022-10-12", "Fed 급격한 금리인상, 성장주·채권 동반하락",   -25.0, -28.0),
    ("2011 유럽 재정위기", "2011-07-21", "2011-10-03", "그리스 부채·미국 신용등급 강등 동시 발생",    -20.0, -25.0),
]


def calc_historical_stress_test(price_series_dict, asset_df, total_asset):
    """각 위기 시나리오별 포트폴리오 추정 손익 산출."""
    from stock_lab_core.prices import _is_kr_ticker

    def _asset_shock(ticker, asset_name, us_s, kr_s, t_start, t_end):
        is_kr = _is_kr_ticker(ticker)
        base = kr_s if is_kr else us_s
        # 실제 가격 데이터 우선
        if ticker in price_series_dict:
            try:
                s = price_series_dict[ticker]
                mask = (s.index >= pd.Timestamp(t_start)) & (s.index <= pd.Timestamp(t_end))
                rng = s[mask]
                if len(rng) >= 10:
                    return float(rng.iloc[-1] / rng.iloc[0] - 1) * 100
            except Exception:
                pass
        # 프록시 충격 (레버리지·인버스·자산유형 반영)
        text = f"{str(ticker).upper()} {str(asset_name or '').upper()}"
        if any(k in text for k in ["SQQQ", "SOXS", "SPXU", "SDOW", "인버스", "INVERSE", "BEAR", "곱버스"]):
            return base * -1.5
        if any(k in text for k in ["3X", "TQQQ", "SOXL", "SPXL", "UPRO", "TECL", "FNGU", "BULZ"]):
            return base * 2.8
        if any(k in text for k in ["2X", "2배", "QLD", "SSO", "레버리지", "LEVERAGE"]):
            return base * 1.85
        if any(k in text for k in ["GLD", "IAU", "금커버", "GOLD"]):
            return base * 0.05
        if any(k in text for k in ["TLT", "IEF", "AGG", "BND", "채권"]):
            return base * -0.25  # 위기 시 채권은 반대 방향
        if "CASH" in text:
            return 0.0
        return base

    results = []
    for name_kr, t_start, t_end, desc, us_s, kr_s in _STRESS_SCENARIOS:
        port_shock = 0.0
        asset_breakdown = []
        for _, row in asset_df.iterrows():
            ticker = str(row.get("티커", "")).strip()
            aname = str(row.get("자산명", ""))
            wt = clean_float(row.get("전체비중"), 0.0) / 100
            if wt <= 0 or not ticker:
                continue
            shock = _asset_shock(ticker, aname, us_s, kr_s, t_start, t_end)
            contrib = wt * shock
            port_shock += contrib
            asset_breakdown.append({
                "자산명": aname or ticker,
                "개별충격(%)": round(shock, 1),
                "기여(%)": round(contrib, 2),
            })
        results.append({
            "시나리오": name_kr,
            "기간": f"{t_start[:7]} ~ {t_end[:7]}",
            "설명": desc,
            "포트 추정 손익(%)": round(port_shock, 1),
            "추정 손실액(원)": int(-total_asset * port_shock / 100) if port_shock < 0 else 0,
            "asset_breakdown": asset_breakdown,
        })
    return results


def get_active_portfolio_rows(holdings_table):
    if holdings_table is None or holdings_table.empty:
        return pd.DataFrame()

    df = holdings_table.copy()
    if "원화환산" not in df.columns or "티커" not in df.columns:
        return pd.DataFrame()

    df["원화환산"] = df["원화환산"].apply(clean_float)
    df = df[df["원화환산"] > 0].copy()

    if "bucket" in df.columns:
        df = df[~df["bucket"].apply(lambda v: normalize_bucket(v) in ["reserve", "cash"])]
    if "운용대상" in df.columns:
        df = df[df["운용대상"].apply(clean_bool)]

    df = df[~df["티커"].astype(str).str.upper().isin(["KRW_CASH", "USD_CASH"])]
    return df.reset_index(drop=True)


def add_portfolio_risk_note(notes, level, area, detail, suggestion):
    notes.append({
        "등급": level,
        "영역": area,
        "내용": detail,
        "확인/조치": suggestion,
    })


def classify_portfolio_risk(risk_index):
    if risk_index >= 70:
        return "공격/위험", "#dc2626"
    if risk_index >= 50:
        return "주의", "#f59e0b"
    if risk_index >= 30:
        return "균형", "#10b981"
    return "방어", "#3b82f6"


def classify_corr_value(value):
    if value >= 0.8:
        return "매우 높음", "거의 같은 방향으로 움직입니다. 분산 효과가 낮습니다."
    if value >= 0.5:
        return "높음", "비슷한 방향으로 움직이는 편입니다."
    if value > 0.3:
        return "보통", "어느 정도 같은 방향성이 있습니다."
    if value >= -0.3:
        return "낮음", "서로 크게 묶여 움직이지 않습니다."
    return "반대", "반대로 움직이는 경향이 있어 변동성 완충에 도움이 될 수 있습니다."


def annualize_period_return(period_return_decimal, observation_count):
    if not finite_num(period_return_decimal) or observation_count <= 0:
        return np.nan
    growth = 1 + float(period_return_decimal)
    if growth <= 0:
        return -1.0
    return float(growth ** (252 / observation_count) - 1)


def calc_downside_volatility(returns, target=0.0):
    returns = pd.Series(returns).dropna()
    if returns.empty:
        return np.nan
    downside = returns[returns < target] - target
    if downside.empty:
        return 0.0
    return float(downside.std() * np.sqrt(252))


def calc_var_cvar(returns, confidence=0.95):
    returns = pd.Series(returns).replace([np.inf, -np.inf], np.nan).dropna()
    if len(returns) < 20:
        return np.nan, np.nan

    tail_cut = float(returns.quantile(1 - confidence))
    tail = returns[returns <= tail_cut]
    cvar = float(tail.mean()) if not tail.empty else tail_cut
    return tail_cut * 100, cvar * 100


def ratio_or_nan(numer, denom):
    if not finite_num(numer) or not finite_num(denom) or float(denom) == 0:
        return np.nan
    return float(numer) / float(denom)


def build_risk_contribution_df(asset_df, aligned_returns, weights):
    columns = ["자산명", "티커", "운용비중", "연환산변동성", "리스크기여도", "비중대비리스크"]
    if asset_df is None or asset_df.empty or aligned_returns is None or aligned_returns.empty or weights is None or weights.empty:
        return pd.DataFrame(columns=columns)

    cols = [col for col in weights.index if col in aligned_returns.columns]
    if len(cols) < 2:
        return pd.DataFrame(columns=columns)

    returns = aligned_returns[cols].replace([np.inf, -np.inf], np.nan).dropna(how="all").fillna(0.0)
    weights = weights[cols].astype(float)
    weight_sum = float(weights.sum())
    if weight_sum <= 0 or returns.empty:
        return pd.DataFrame(columns=columns)
    weights = weights / weight_sum

    cov = returns.cov() * 252
    portfolio_var = float(weights.T @ cov @ weights)
    if not np.isfinite(portfolio_var) or portfolio_var <= 0:
        return pd.DataFrame(columns=columns)

    marginal = cov.dot(weights)
    contribution = (weights * marginal / portfolio_var) * 100
    vol = returns.std() * np.sqrt(252) * 100

    name_map = {
        str(row.get("티커", "")): str(row.get("자산명", "") or row.get("티커", ""))
        for _, row in asset_df.iterrows()
    }

    rows = []
    for ticker in cols:
        weight_pct = float(weights.get(ticker, 0.0) * 100)
        contrib_pct = float(contribution.get(ticker, np.nan))
        rows.append({
            "자산명": name_map.get(ticker, ticker),
            "티커": ticker,
            "운용비중": weight_pct,
            "연환산변동성": float(vol.get(ticker, np.nan)),
            "리스크기여도": contrib_pct,
            "비중대비리스크": ratio_or_nan(contrib_pct, weight_pct),
        })

    return pd.DataFrame(rows, columns=columns).sort_values("리스크기여도", ascending=False).reset_index(drop=True)


def build_asset_label_map(asset_df):
    if asset_df is None or asset_df.empty or "티커" not in asset_df.columns:
        return {}

    base_by_ticker = {}
    label_counts = {}
    for _, row in asset_df.iterrows():
        ticker = str(row.get("티커", "")).strip()
        if not ticker:
            continue
        name = str(row.get("자산명", "")).strip()
        base_label = name if name else ticker
        base_by_ticker[ticker] = base_label
        label_counts[base_label] = label_counts.get(base_label, 0) + 1

    label_map = {}
    used_labels = set()
    for ticker, base_label in base_by_ticker.items():
        label = f"{base_label} ({ticker})" if label_counts.get(base_label, 0) > 1 else base_label
        if label in used_labels:
            label = f"{base_label} ({ticker})"
        label_map[ticker] = label
        used_labels.add(label)

    return label_map


def calc_portfolio_leverage_summary(asset_df):
    columns = ["자산명", "티커", "전체비중", "운용비중", "충격배수", "레버리지환산노출", "추가노출"]
    summary = {
        "leveraged_principal_pct": 0.0,
        "effective_exposure_pct": 0.0,
        "extra_exposure_pct": 0.0,
        "active_effective_exposure_pct": 0.0,
        "max_multiplier": 1.0,
    }

    if asset_df is None or asset_df.empty:
        return summary, pd.DataFrame(columns=columns)

    rows = []
    for _, row in asset_df.iterrows():
        ticker = str(row.get("티커", "")).strip()
        name = str(row.get("자산명", "")).strip()
        multiplier = abs(clean_float(infer_scenario_shock_multiplier({
            "티커": ticker,
            "자산명": name,
        }), 1.0))

        if multiplier <= 1.05:
            continue

        total_weight = clean_float(row.get("전체비중"), 0.0)
        active_weight = clean_float(row.get("운용비중"), 0.0)
        effective_exposure = total_weight * multiplier
        active_effective_exposure = active_weight * multiplier
        extra_exposure = max(effective_exposure - total_weight, 0.0)

        rows.append({
            "자산명": name if name else ticker,
            "티커": ticker,
            "전체비중": total_weight,
            "운용비중": active_weight,
            "충격배수": multiplier,
            "레버리지환산노출": effective_exposure,
            "추가노출": extra_exposure,
            "_active_effective_exposure": active_effective_exposure,
        })

    if not rows:
        return summary, pd.DataFrame(columns=columns)

    leverage_df = pd.DataFrame(rows)
    summary["leveraged_principal_pct"] = float(leverage_df["전체비중"].sum())
    summary["effective_exposure_pct"] = float(leverage_df["레버리지환산노출"].sum())
    summary["extra_exposure_pct"] = float(leverage_df["추가노출"].sum())
    summary["active_effective_exposure_pct"] = float(leverage_df["_active_effective_exposure"].sum())
    summary["max_multiplier"] = float(leverage_df["충격배수"].max())

    return summary, leverage_df.drop(columns=["_active_effective_exposure"], errors="ignore")[columns]


def build_correlation_pair_summary(corr_df):
    if corr_df is None or corr_df.empty or len(corr_df.columns) < 2:
        return pd.DataFrame(columns=["자산 A", "자산 B", "상관계수", "구분", "해석"])

    rows = []
    cols = list(corr_df.columns)
    for i, left in enumerate(cols):
        for j in range(i + 1, len(cols)):
            right = cols[j]
            if str(left).strip() == str(right).strip():
                continue
            value = clean_float(corr_df.iloc[i, j], np.nan)
            if not np.isfinite(value):
                continue
            label, meaning = classify_corr_value(value)
            rows.append({
                "자산 A": left,
                "자산 B": right,
                "상관계수": value,
                "구분": label,
                "해석": meaning,
            })

    if not rows:
        return pd.DataFrame(columns=["자산 A", "자산 B", "상관계수", "구분", "해석"])

    df = pd.DataFrame(rows)
    df["_abs"] = df["상관계수"].abs()
    return df.sort_values(["상관계수", "_abs"], ascending=[False, False]).drop(columns="_abs").reset_index(drop=True)


def normalize_datetime_index_no_tz(index):
    idx = pd.to_datetime(index)
    if getattr(idx, "tz", None) is not None:
        idx = idx.tz_convert(None)
    return idx


def get_portfolio_analysis_start_date(monthly_logs_df):
    perf_df = prepare_monthly_performance_df(monthly_logs_df)
    if perf_df is None or perf_df.empty or "month_end" not in perf_df.columns:
        return None

    month_end = pd.to_datetime(perf_df["month_end"], errors="coerce").dropna()
    if month_end.empty:
        return None

    first_month = pd.Timestamp(month_end.min())
    if getattr(first_month, "tzinfo", None) is not None:
        first_month = first_month.tz_convert(None)
    return first_month.replace(day=1).normalize()


def render_correlation_interpretation(corr_df, avg_corr):
    st.markdown("""
**읽는 법**
- 화면 표시는 티커가 아니라 자산명 기준입니다. 같은 자산명이 있으면 뒤에 티커를 붙여 구분합니다.
- 빨강에 가까울수록 같이 움직입니다. 여러 종목을 들고 있어도 한 방향으로 크게 흔들릴 수 있습니다.
- 흰색에 가까울수록 관계가 약합니다. 분산 효과가 상대적으로 있습니다.
- 파랑에 가까울수록 반대로 움직입니다. 하락 방어에 도움이 될 수 있지만 수익도 서로 상쇄될 수 있습니다.
    """)

    if np.isfinite(avg_corr):
        if avg_corr >= 0.7:
            st.warning(f"평균 상관계수는 {avg_corr:.2f}입니다. 포트폴리오가 한 방향으로 같이 움직이는 편입니다.")
        elif avg_corr >= 0.4:
            st.info(f"평균 상관계수는 {avg_corr:.2f}입니다. 일부 분산은 있지만 같은 방향성도 있습니다.")
        else:
            st.success(f"평균 상관계수는 {avg_corr:.2f}입니다. 자산 간 움직임이 비교적 덜 묶여 있습니다.")

    pair_df = build_correlation_pair_summary(corr_df)
    if not pair_df.empty:
        st.markdown("##### 상관관계 높은 조합")
        top_pairs = pair_df.head(5).copy()
        top_pairs["상관계수"] = top_pairs["상관계수"].apply(lambda v: f"{v:.2f}")
        st.dataframe(top_pairs, width='stretch', hide_index=True)


def build_portfolio_analysis_report(holdings_table, krw_cash, usd_cash, usdkrw, reserve_target_weight, period="1y", analysis_start_date=None):
    if analysis_start_date is not None:
        analysis_start_date = pd.Timestamp(analysis_start_date).normalize()

    total_asset = (
        float(holdings_table["원화환산"].sum()) if holdings_table is not None and not holdings_table.empty and "원화환산" in holdings_table.columns else 0.0
    ) + clean_float(krw_cash) + clean_float(usd_cash) * clean_float(usdkrw, 1400.0)

    full_df = append_cash_rows(
        holdings_table.copy() if holdings_table is not None else pd.DataFrame(),
        krw_cash,
        usd_cash,
        usdkrw,
        total_asset,
    )
    reserve_summary = calc_reserve_summary(full_df, reserve_target_weight)
    active_df = get_active_portfolio_rows(full_df)
    blended_benchmark_spec = build_portfolio_blended_benchmark_spec(full_df)

    asset_rows = []
    strategy_rows = []
    price_series = {}
    notes = []

    if active_df.empty:
        add_portfolio_risk_note(notes, "참고", "분석 대상", "운용대상 보유자산이 없습니다.", "보유 종목을 등록하면 포트폴리오 분석이 표시됩니다.")

    active_value = float(active_df["원화환산"].sum()) if not active_df.empty else 0.0
    for _, row in active_df.iterrows():
        ticker = str(row.get("티커", "")).strip()
        name = str(row.get("자산명", "")).strip()
        value_krw = clean_float(row.get("원화환산"), 0.0)
        weight_total = value_krw / total_asset * 100 if total_asset > 0 else 0.0
        weight_active = value_krw / active_value * 100 if active_value > 0 else 0.0

        target_weight = clean_float(row.get("목표비중"), 0.0)
        bucket = normalize_bucket(row.get("bucket", "core"))
        timing_text = str(row.get("기술적타점", "") or "").strip()
        row_info = {
            "자산명": name,
            "티커": ticker,
            "버킷": bucket,
            "원화환산": value_krw,
            "전체비중": weight_total,
            "목표비중": target_weight,
            "비중차이": target_weight - weight_total,
            "운용비중": weight_active,
            "기간수익률": np.nan,
            "연환산변동성": np.nan,
            "MDD": np.nan,
            "데이터": "부족",
        }
        strategy_rows.append({
            "자산명": name or ticker,
            "티커": ticker,
            "버킷": bucket,
            "기술적타점": timing_text,
            "현재비중": weight_total,
            "목표비중": target_weight,
            "비중차이": target_weight - weight_total,
        })

        try:
            px_df = load_price_df(ticker, period)
        except Exception:
            px_df = pd.DataFrame()

        if px_df is not None and not px_df.empty and "Close" in px_df.columns:
            close = pd.Series(px_df["Close"]).dropna()
            close.index = normalize_datetime_index_no_tz(close.index)
            if analysis_start_date is not None:
                close = close[close.index >= analysis_start_date]
            if len(close) >= 20:
                returns = close.pct_change().dropna()
                row_info["기간수익률"] = (float(close.iloc[-1]) / float(close.iloc[0]) - 1) * 100 if close.iloc[0] else np.nan
                row_info["연환산변동성"] = float(returns.std() * np.sqrt(252) * 100) if not returns.empty else np.nan
                row_info["MDD"] = calc_series_mdd(close) * 100
                row_info["데이터"] = "정상"
                price_series[ticker] = close.rename(ticker)

        if row_info["데이터"] == "부족":
            add_portfolio_risk_note(notes, "참고", "가격 데이터", ticker, "가격 데이터가 부족해 변동성/MDD 계산에서 제외했습니다.")

        asset_rows.append(row_info)

    asset_df = pd.DataFrame(asset_rows, columns=[
        "자산명", "티커", "버킷", "원화환산", "전체비중", "목표비중", "비중차이", "운용비중", "기간수익률", "연환산변동성", "MDD", "데이터"
    ])

    if not asset_df.empty:
        asset_df = asset_df.sort_values("전체비중", ascending=False).reset_index(drop=True)
    strategy_df = pd.DataFrame(strategy_rows)
    asset_label_map = build_asset_label_map(asset_df)
    leverage_summary, leverage_df = calc_portfolio_leverage_summary(asset_df)

    top1_weight = float(asset_df["전체비중"].max()) if not asset_df.empty else 0.0
    top3_weight = float(asset_df["전체비중"].head(3).sum()) if not asset_df.empty else 0.0
    hhi = float(((asset_df["전체비중"] / 100) ** 2).sum()) if not asset_df.empty else 0.0
    target_top3_weight = 0.0
    target_concentration_gap = np.nan
    leverage_control = {
        "has_leverage": False,
        "blocked_count": 0,
        "overweight_block_count": 0,
        "active_buy_count": 0,
        "signals": [],
    }
    core_control = {
        "core_count": 0,
        "overheat_count": 0,
        "under_target_count": 0,
    }
    if not strategy_df.empty:
        sorted_strategy = strategy_df.sort_values("현재비중", ascending=False).reset_index(drop=True)
        target_top3_weight = float(sorted_strategy["목표비중"].head(3).apply(clean_float).sum())
        target_concentration_gap = top3_weight - target_top3_weight

        lev_df = strategy_df[strategy_df["버킷"].astype(str).eq("leverage")].copy()
        if not lev_df.empty:
            lev_signals = lev_df["기술적타점"].fillna("").astype(str)
            blocked_mask = lev_signals.str.contains("하드차단|구조훼손|과열패스|추매금지|비중 초과|비중 충족", regex=True)
            overweight_mask = lev_signals.str.contains("비중 초과|비중 충족", regex=True)
            buy_mask = lev_signals.str.contains("매수|DCA|진입", regex=True) & ~blocked_mask
            leverage_control = {
                "has_leverage": True,
                "blocked_count": int(blocked_mask.sum()),
                "overweight_block_count": int(overweight_mask.sum()),
                "active_buy_count": int(buy_mask.sum()),
                "signals": [s for s in lev_signals.tolist() if s],
            }

        core_df = strategy_df[strategy_df["버킷"].astype(str).eq("core")].copy()
        if not core_df.empty:
            core_signals = core_df["기술적타점"].fillna("").astype(str)
            core_control = {
                "core_count": int(len(core_df)),
                "overheat_count": int(core_signals.str.contains("과열", regex=False).sum()),
                "under_target_count": int((core_df["비중차이"].apply(clean_float) > 0.2).sum()),
            }
    if not asset_df.empty:
        data_ok_mask = asset_df["데이터"].astype(str).eq("정상")
        usable_asset_count = int(data_ok_mask.sum())
        missing_asset_count = int((~data_ok_mask).sum())
        usable_total_weight = float(asset_df.loc[data_ok_mask, "전체비중"].sum())
        missing_total_weight = float(asset_df.loc[~data_ok_mask, "전체비중"].sum())
        usable_active_weight = float(asset_df.loc[data_ok_mask, "운용비중"].sum())
        missing_active_weight = float(asset_df.loc[~data_ok_mask, "운용비중"].sum())
        missing_asset_names = [
            str(row.get("자산명") or row.get("티커") or "").strip()
            for _, row in asset_df.loc[~data_ok_mask, ["자산명", "티커"]].head(8).iterrows()
        ]
    else:
        usable_asset_count = 0
        missing_asset_count = 0
        usable_total_weight = 0.0
        missing_total_weight = 0.0
        usable_active_weight = 0.0
        missing_active_weight = 0.0
        missing_asset_names = []

    portfolio_returns = pd.Series(dtype=float)
    portfolio_curve = pd.Series(dtype=float)
    corr_df = pd.DataFrame()
    portfolio_vol = np.nan
    portfolio_mdd = np.nan
    portfolio_period_return = np.nan
    portfolio_annual_return = np.nan
    portfolio_downside_vol = np.nan
    sharpe_ratio = np.nan
    sortino_ratio = np.nan
    calmar_ratio = np.nan
    daily_var_95 = np.nan
    daily_cvar_95 = np.nan
    monthly_var_95 = np.nan
    active_var_95_krw = np.nan
    active_cvar_95_krw = np.nan
    risk_contrib_df = pd.DataFrame()
    avg_corr = np.nan
    portfolio_observation_count = 0
    drawdown_details = {}
    benchmark_metrics_blended = {}
    benchmark_metrics_voo = {}
    benchmark_metrics_kr = {}
    rolling_df = pd.DataFrame()
    stress_results = []

    if price_series:
        prices = pd.concat(price_series.values(), axis=1).sort_index().ffill(limit=3)
        returns_df = prices.pct_change().replace([np.inf, -np.inf], np.nan).dropna(how="all").fillna(0.0)

        usable_cols = [col for col in returns_df.columns if col in set(asset_df["티커"])]
        if usable_cols:
            # 전체비중(현금 포함 총자산 기준) 사용 — 운용비중으로 재정규화하면 현금의 리스크 완충 효과가 사라짐
            weight_map = {
                str(row["티커"]): clean_float(row["전체비중"], 0.0) / 100
                for _, row in asset_df.iterrows()
                if str(row["티커"]) in usable_cols
            }
            weight_sum = sum(weight_map.values())
            if weight_sum > 0:
                weights = pd.Series({ticker: weight for ticker, weight in weight_map.items()})
                aligned_returns = returns_df[weights.index].copy()
                portfolio_returns = aligned_returns.mul(weights, axis=1).sum(axis=1)
                if not portfolio_returns.empty:
                    portfolio_observation_count = int(len(portfolio_returns))
                    portfolio_curve = (1 + portfolio_returns).cumprod()
                    portfolio_vol_decimal = float(portfolio_returns.std() * np.sqrt(252))
                    portfolio_vol = portfolio_vol_decimal * 100
                    portfolio_mdd_decimal = calc_series_mdd(portfolio_curve)
                    portfolio_mdd = portfolio_mdd_decimal * 100
                    portfolio_period_return = (float(portfolio_curve.iloc[-1]) - 1) * 100
                    annual_return_decimal = annualize_period_return(portfolio_period_return / 100, len(portfolio_returns))
                    downside_vol_decimal = calc_downside_volatility(portfolio_returns)
                    portfolio_annual_return = annual_return_decimal * 100 if np.isfinite(annual_return_decimal) else np.nan
                    portfolio_downside_vol = downside_vol_decimal * 100 if np.isfinite(downside_vol_decimal) else np.nan
                    _rf_rate = 0.035  # 무위험이율 3.5% (한국 기준금리 근방)
                    sharpe_ratio = ratio_or_nan(annual_return_decimal - _rf_rate, portfolio_vol_decimal)
                    sortino_ratio = ratio_or_nan(annual_return_decimal - _rf_rate, downside_vol_decimal)
                    calmar_ratio = ratio_or_nan(annual_return_decimal, abs(portfolio_mdd_decimal))
                    daily_var_95, daily_cvar_95 = calc_var_cvar(portfolio_returns, 0.95)
                    monthly_var_95 = daily_var_95 * np.sqrt(21) if np.isfinite(daily_var_95) else np.nan
                    # 전체자산 기준으로 VaR/CVaR 원화 손실액 산출 (현금 비중이 이미 수익률에 반영됨)
                    active_var_95_krw = total_asset * abs(daily_var_95) / 100 if np.isfinite(daily_var_95) else np.nan
                    active_cvar_95_krw = total_asset * abs(daily_cvar_95) / 100 if np.isfinite(daily_cvar_95) else np.nan
                    risk_contrib_df = build_risk_contribution_df(asset_df, aligned_returns, weights)
                    drawdown_details = calc_drawdown_details(portfolio_curve)
                    rolling_df = calc_rolling_metrics(portfolio_returns)
                    benchmark_metrics_blended = calc_blended_benchmark_comparison(
                        portfolio_returns, blended_benchmark_spec, period, analysis_start_date=analysis_start_date
                    )
                    benchmark_metrics_voo = calc_benchmark_comparison(
                        portfolio_returns, "VOO", period, analysis_start_date=analysis_start_date
                    )
                    benchmark_metrics_kr = calc_benchmark_comparison(
                        portfolio_returns, "069500.KS", period, analysis_start_date=analysis_start_date
                    )

                if len(weights.index) >= 2:
                    corr_df = aligned_returns.corr()
                    upper = corr_df.where(np.triu(np.ones(corr_df.shape), k=1).astype(bool))
                    avg_corr = float(np.nanmean(upper.values)) if np.isfinite(upper.values).any() else np.nan
                    corr_df = corr_df.rename(index=asset_label_map, columns=asset_label_map)

    vol_component = min(max(float(portfolio_vol) if np.isfinite(portfolio_vol) else 0.0, 0.0) * 1.1, 30)
    mdd_component = min(abs(float(portfolio_mdd)) if np.isfinite(portfolio_mdd) else 0.0, 30)
    concentration_component = min(top1_weight * 0.45 + top3_weight * 0.2 + hhi * 100 * 0.6, 25)
    corr_component = min(max(float(avg_corr) if np.isfinite(avg_corr) else 0.0, 0.0) * 15, 15)
    leverage_component = min(max(float(leverage_summary.get("extra_exposure_pct", 0.0)), 0.0) * 0.9, 20)
    reserve_gap = max(float(reserve_target_weight) - float(reserve_summary.get("waiting_pct", 0.0)), 0.0)
    reserve_component = min(reserve_gap * 1.5, 15)
    risk_index = min(vol_component + mdd_component + concentration_component + corr_component + leverage_component + reserve_component, 100)
    risk_grade, risk_color = classify_portfolio_risk(risk_index)
    risk_components = [
        {
            "영역": "변동성",
            "점수": vol_component,
            "최대": 30,
            "판단근거": f"연환산 변동성 {portfolio_vol:.1f}%" if np.isfinite(portfolio_vol) else "가격 데이터 부족",
        },
        {
            "영역": "MDD",
            "점수": mdd_component,
            "최대": 30,
            "판단근거": f"분석기간 MDD {portfolio_mdd:.1f}%" if np.isfinite(portfolio_mdd) else "가격 데이터 부족",
        },
        {
            "영역": "집중도",
            "점수": concentration_component,
            "최대": 25,
            "판단근거": f"1위 {top1_weight:.1f}%, 상위3개 {top3_weight:.1f}%",
        },
        {
            "영역": "상관관계",
            "점수": corr_component,
            "최대": 15,
            "판단근거": f"평균 상관계수 {avg_corr:.2f}" if np.isfinite(avg_corr) else "상관관계 산출 불가",
        },
        {
            "영역": "레버리지",
            "점수": leverage_component,
            "최대": 20,
            "판단근거": f"추가 환산노출 {leverage_summary.get('extra_exposure_pct', 0.0):.1f}%",
        },
        {
            "영역": "대기자금",
            "점수": reserve_component,
            "최대": 15,
            "판단근거": f"목표 대비 부족 {reserve_gap:.1f}%p" if reserve_gap > 0 else "목표 이상 확보",
        },
    ]

    if top1_weight >= 35:
        add_portfolio_risk_note(notes, "주의", "집중도", f"1위 자산 비중이 {top1_weight:.1f}%입니다.", "단일 종목/ETF 의존도가 높은지 확인하세요.")
    if top3_weight >= 65:
        add_portfolio_risk_note(notes, "주의", "집중도", f"상위 3개 자산 비중이 {top3_weight:.1f}%입니다.", "의도한 집중 투자라면 괜찮지만, 분산 목적이면 비중을 나눠보세요.")
    if np.isfinite(portfolio_vol) and portfolio_vol >= 28:
        add_portfolio_risk_note(notes, "주의", "변동성", f"연환산 변동성이 {portfolio_vol:.1f}%입니다.", "매수 규모와 현금 비중을 보수적으로 점검하세요.")
    if np.isfinite(portfolio_mdd) and portfolio_mdd <= -25:
        add_portfolio_risk_note(notes, "주의", "낙폭", f"분석기간 MDD가 {portfolio_mdd:.1f}%입니다.", "큰 하락을 견딜 수 있는 포지션 크기인지 확인하세요.")
    if np.isfinite(avg_corr) and avg_corr >= 0.7:
        add_portfolio_risk_note(notes, "참고", "상관관계", f"평균 상관계수가 {avg_corr:.2f}입니다.", "종목 수가 많아도 비슷하게 움직일 수 있습니다.")
    if leverage_summary.get("leveraged_principal_pct", 0.0) > 0:
        leverage_level = "주의" if leverage_summary.get("extra_exposure_pct", 0.0) >= 8 or leverage_summary.get("effective_exposure_pct", 0.0) >= 15 else "참고"
        add_portfolio_risk_note(
            notes,
            leverage_level,
            "레버리지",
            (
                f"레버리지 ETF 원금비중은 {leverage_summary.get('leveraged_principal_pct', 0.0):.1f}%이고 "
                f"2배/3배 환산 노출은 {leverage_summary.get('effective_exposure_pct', 0.0):.1f}%입니다."
            ),
            "전체 위험도가 균형이어도 레버리지 환산 노출과 손실 속도는 별도로 확인하세요.",
        )
    if reserve_summary.get("waiting_pct", 0.0) + 0.1 < float(reserve_target_weight):
        add_portfolio_risk_note(notes, "참고", "방어력", f"대기자금 비중이 목표보다 {reserve_gap:.1f}%p 낮습니다.", "시장 변동성이 클 때 투입 여력을 따로 확보할지 확인하세요.")
    if np.isfinite(sharpe_ratio) and sharpe_ratio < 0:
        add_portfolio_risk_note(notes, "참고", "위험대비수익", f"Sharpe가 {sharpe_ratio:.2f}입니다.", "분석기간에는 변동성 대비 수익 보상이 낮았습니다.")
    if np.isfinite(daily_cvar_95) and daily_cvar_95 <= -4:
        add_portfolio_risk_note(notes, "주의", "꼬리위험", f"95% CVaR 기준 나쁜 날 평균 손실이 {daily_cvar_95:.1f}%입니다.", "급락일에 감내 가능한 손실 규모인지 확인하세요.")
    if risk_contrib_df is not None and not risk_contrib_df.empty:
        top_risk = risk_contrib_df.iloc[0]
        if clean_float(top_risk.get("리스크기여도"), 0.0) >= 45:
            add_portfolio_risk_note(notes, "주의", "리스크기여도", f"{top_risk.get('자산명')} 리스크 기여도가 {clean_float(top_risk.get('리스크기여도')):.1f}%입니다.", "비중보다 실제 변동성 영향이 큰 자산인지 확인하세요.")

    # 스트레스 테스트는 asset_df 구성 후 실행
    if not asset_df.empty:
        stress_results = calc_historical_stress_test(price_series, asset_df, total_asset)

    notes_df = pd.DataFrame(notes, columns=["등급", "영역", "내용", "확인/조치"])
    metrics = {
        "risk_index": risk_index,
        "risk_grade": risk_grade,
        "risk_color": risk_color,
        "portfolio_vol": portfolio_vol,
        "portfolio_mdd": portfolio_mdd,
        "portfolio_period_return": portfolio_period_return,
        "portfolio_annual_return": portfolio_annual_return,
        "portfolio_downside_vol": portfolio_downside_vol,
        "sharpe_ratio": sharpe_ratio,
        "sortino_ratio": sortino_ratio,
        "calmar_ratio": calmar_ratio,
        "daily_var_95": daily_var_95,
        "daily_cvar_95": daily_cvar_95,
        "monthly_var_95": monthly_var_95,
        "active_var_95_krw": active_var_95_krw,
        "active_cvar_95_krw": active_cvar_95_krw,
        "avg_corr": avg_corr,
        "top1_weight": top1_weight,
        "top3_weight": top3_weight,
        "target_top3_weight": target_top3_weight,
        "target_concentration_gap": target_concentration_gap,
        "hhi": hhi,
        "active_value": active_value,
        "total_asset": total_asset,
        "reserve_summary": reserve_summary,
        "leverage_summary": leverage_summary,
        "leverage_df": leverage_df,
        "leverage_component": leverage_component,
        "reserve_gap": reserve_gap,
        "reserve_target_weight": reserve_target_weight,
        "risk_components": risk_components,
        "leverage_control": leverage_control,
        "core_control": core_control,
        "data_coverage": {
            "usable_asset_count": usable_asset_count,
            "missing_asset_count": missing_asset_count,
            "usable_total_weight": usable_total_weight,
            "missing_total_weight": missing_total_weight,
            "usable_active_weight": usable_active_weight,
            "missing_active_weight": missing_active_weight,
            "missing_asset_names": missing_asset_names,
        },
        "usable_asset_count": usable_asset_count,
        "portfolio_observation_count": portfolio_observation_count,
        "analysis_start_date": analysis_start_date,
        "drawdown_details": drawdown_details,
        "benchmark_blended": benchmark_metrics_blended,
        "blended_benchmark_spec": blended_benchmark_spec,
        "benchmark_voo": benchmark_metrics_voo,
        "benchmark_kr": benchmark_metrics_kr,
        "rolling_df": rolling_df,
        "stress_results": stress_results,
    }

    return metrics, asset_df, notes_df, corr_df, portfolio_curve, risk_contrib_df


def format_metric_pct(value, digits=1):
    return "-" if not np.isfinite(clean_float(value, np.nan)) else f"{clean_float(value):.{digits}f}%"


def format_metric_ratio(value, digits=2):
    return "-" if not np.isfinite(clean_float(value, np.nan)) else f"{clean_float(value):.{digits}f}"


def format_metric_money(value):
    return "-" if not np.isfinite(clean_float(value, np.nan)) else f"{clean_float(value):,.0f}원"


def render_portfolio_sample_warning(metrics):
    observation_count = int(clean_float(metrics.get("portfolio_observation_count", 0), 0))
    if observation_count <= 0:
        return

    if observation_count < 63:
        st.warning(
            f"가격 표본이 {observation_count}거래일뿐이라 연환산 수익률, Sharpe, Sortino가 크게 왜곡될 수 있습니다. "
            "최근 흐름 참고용으로만 보세요."
        )
    elif observation_count < 126:
        st.info(
            f"가격 표본이 {observation_count}거래일입니다. 연환산 지표는 아직 짧은 기간을 1년으로 늘린 값이라 "
            "실제 장기 성과처럼 해석하면 안 됩니다."
        )


def render_portfolio_decision_summary(metrics, asset_df, monthly_logs_df=None):
    risk_index = clean_float(metrics.get("risk_index"), 0.0)
    risk_grade = str(metrics.get("risk_grade", "-"))
    risk_color = str(metrics.get("risk_color", "#f97316"))
    components = metrics.get("risk_components", []) or []
    coverage = metrics.get("data_coverage", {}) or {}
    leverage_summary = metrics.get("leverage_summary", {}) or {}
    leverage_control = metrics.get("leverage_control", {}) or {}
    core_control = metrics.get("core_control", {}) or {}

    if risk_index >= 70:
        status = "위험 관리 우선"
        tone = "공격성은 살아 있지만 하락장 충격을 먼저 점검해야 하는 구간입니다."
    elif risk_index >= 50:
        status = "공격형 점검"
        tone = "수익 추구 비중이 있는 포트폴리오입니다. 집중도와 대기자금을 같이 봐야 합니다."
    elif risk_index >= 30:
        status = "균형 유지"
        tone = "현재는 무리한 위험 신호보다 균형 관리가 더 중요한 구간입니다."
    else:
        status = "안정권"
        tone = "가격 변동 위험은 낮은 편입니다. 기회비용과 목표비중 미달 여부를 같이 보세요."

    driver_components = sorted(
        [c for c in components if clean_float(c.get("점수"), 0.0) > 0.5],
        key=lambda c: clean_float(c.get("점수"), 0.0),
        reverse=True,
    )
    if driver_components:
        driver_text = ", ".join(
            f"{c.get('영역')} {clean_float(c.get('점수'), 0.0):.1f}점"
            for c in driver_components[:3]
        )
    else:
        driver_text = "도드라진 단일 위험요인 없음"

    actions = []
    reserve_gap = clean_float(metrics.get("reserve_gap"), 0.0)
    top1 = clean_float(metrics.get("top1_weight"), 0.0)
    top3 = clean_float(metrics.get("top3_weight"), 0.0)
    target_top3 = clean_float(metrics.get("target_top3_weight"), np.nan)
    target_gap = clean_float(metrics.get("target_concentration_gap"), np.nan)
    target_designed_concentration = np.isfinite(target_top3) and target_top3 >= 70 and np.isfinite(target_gap) and abs(target_gap) <= 5
    if target_designed_concentration and "집중도" in driver_text:
        driver_text = driver_text.replace("집중도", "집중도(목표설계)")
    extra_exposure = clean_float(leverage_summary.get("extra_exposure_pct"), 0.0)
    leverage_blocked = int(clean_float(leverage_control.get("blocked_count"), 0)) > 0
    leverage_overweight_blocked = int(clean_float(leverage_control.get("overweight_block_count"), 0)) > 0
    missing_weight = clean_float(coverage.get("missing_total_weight"), 0.0)
    observation_count = int(clean_float(metrics.get("portfolio_observation_count"), 0))

    if reserve_gap > 2:
        actions.append(f"대기자금이 목표보다 {reserve_gap:.1f}%p 부족하니 신규 매수 속도를 조절하세요.")
    if target_designed_concentration:
        tone = "목표비중 자체가 공격형 집중 구조입니다. 나쁜 상태라는 뜻보다 하락장 충격을 감수하는 설계인지 확인하는 신호입니다."
        actions.append(f"상위 3개 {top3:.1f}%는 목표 설계({target_top3:.1f}%)와 거의 일치합니다. 매도 신호가 아니라 집중형 전략 확인 신호입니다.")
    elif top1 >= 35:
        actions.append(f"1위 자산 비중이 {top1:.1f}%라 추가매수 전 상한을 먼저 정하세요.")
    elif top3 >= 65:
        actions.append(f"상위 3개 자산이 {top3:.1f}%라 보완 섹터나 현금 비중을 같이 점검하세요.")
    if extra_exposure >= 8:
        if leverage_overweight_blocked:
            actions.append(f"레버리지는 이미 비중 초과/충족으로 차단 중입니다. 추가매수보다 코어 부족분과 대기자금 복구를 우선하세요.")
        elif leverage_blocked:
            actions.append(f"레버리지는 현재 차단 신호가 있습니다. 단계별 DCA 기준이 풀릴 때까지 추가매수는 보류하세요.")
        else:
            actions.append(f"레버리지 추가 환산노출이 {extra_exposure:.1f}%p라 손실 허용폭을 별도 기준으로 두세요.")
    elif int(clean_float(core_control.get("under_target_count"), 0)) > 0 and int(clean_float(core_control.get("overheat_count"), 0)) > 0:
        actions.append("코어는 과열이어도 목표 미달분을 천천히 적립하는 구조입니다. 일괄매수보다 정해둔 투입률을 지키세요.")
    if missing_weight >= 10:
        actions.append(f"가격 데이터 부족 자산이 {missing_weight:.1f}%라 차트/수동 점검을 병행하세요.")
    if observation_count and observation_count < 126:
        actions.append("가격 표본이 짧아 연환산 수익률보다 구조와 비중을 우선 보세요.")
    if not actions:
        actions.append("현재 비중을 유지하되 목표비중 미달 자산만 천천히 분할 점검하세요.")
    actions = actions[:3]

    action_html = "<br>".join(f"{idx}. {html.escape(item)}" for idx, item in enumerate(actions, 1))
    log_state = "월별 기록 있음" if isinstance(monthly_logs_df, pd.DataFrame) and not monthly_logs_df.empty else "월별 기록 없음"

    st.markdown(f"""
<div class='info-panel' style='border-left:5px solid {risk_color}; margin-bottom:12px;'>
<b>포트폴리오 결론</b><br>
<span class='highlight'>{html.escape(status)}</span> · 위험도 {html.escape(risk_grade)} ({risk_index:.0f}/100)<br>
주요 원인: {html.escape(driver_text)}<br>
{html.escape(tone)}<br><br>
<b>이번 달 우선순위</b><br>
{action_html}
</div>
""", unsafe_allow_html=True)

    analysis_start = metrics.get("analysis_start_date")
    start_text = analysis_start.strftime("%Y-%m") if isinstance(analysis_start, pd.Timestamp) else "선택 기간"
    st.caption(
        f"분석 기준: 실제 투자 성과는 월별 성과 기록({log_state})으로 보고, "
        f"아래 위험지표는 {start_text} 이후 현재 보유비중을 가격 흐름에 적용한 참고 분석입니다."
    )


def render_portfolio_data_coverage_notice(metrics):
    coverage = metrics.get("data_coverage", {}) or {}
    usable_count = int(clean_float(coverage.get("usable_asset_count"), 0))
    missing_count = int(clean_float(coverage.get("missing_asset_count"), 0))
    usable_weight = clean_float(coverage.get("usable_total_weight"), 0.0)
    missing_weight = clean_float(coverage.get("missing_total_weight"), 0.0)
    missing_names = [name for name in coverage.get("missing_asset_names", []) if str(name).strip()]

    if missing_count <= 0:
        st.caption(f"가격 데이터 커버리지: 정상 {usable_count}개, 총자산 기준 {usable_weight:.1f}%가 위험지표 계산에 반영됐습니다.")
        return

    names_text = ", ".join(missing_names)
    more_text = " 등" if missing_count > len(missing_names) else ""
    asset_text = f"({names_text}{more_text})" if names_text else ""
    st.warning(
        f"가격 데이터 부족 자산 {missing_count}개가 있습니다"
        f"{asset_text}. 총자산 기준 {missing_weight:.1f}%는 변동성/MDD/상관관계가 덜 반영될 수 있습니다."
    )


def render_portfolio_risk_breakdown(metrics):
    components = metrics.get("risk_components", []) or []
    if not components:
        return

    comp_df = pd.DataFrame(components)
    if comp_df.empty:
        return

    comp_df["점수값"] = comp_df["점수"].apply(lambda v: clean_float(v, 0.0))
    comp_df = comp_df.sort_values("점수값", ascending=False).reset_index(drop=True)
    show_df = comp_df[["영역", "점수", "최대", "판단근거"]].copy()
    show_df["점수"] = show_df.apply(
        lambda row: f"{clean_float(row['점수'], 0.0):.1f} / {clean_float(row['최대'], 0.0):.0f}",
        axis=1,
    )
    show_df = show_df.drop(columns=["최대"])

    st.markdown("#### 위험점수 분해")
    st.caption("위험도 총점이 어디서 올라왔는지 보여줍니다. 점수가 높은 항목부터 이번 달 점검 우선순위로 보면 됩니다.")
    st.dataframe(show_df, width='stretch', hide_index=True)


