TODAY_MARKET_GUARD_BENCHMARKS = [
    ("SPY", "S&P500"),
    ("QQQ", "나스닥100"),
    ("IWM", "러셀2000"),
    ("069500.KS", "KOSPI200"),
    ("229200.KS", "KOSDAQ150"),
]

TODAY_MARKET_GUARD_MACRO_ORDER = ["10Y 금리", "환율", "VIX", "MOVE", "유가"]


def _format_today_signed_pct(value, digits=1):
    if not finite_num(value):
        return "-"
    return f"{float(value) * 100:+.{digits}f}%"


def _calc_today_benchmark_guard_row(ticker: str, label: str) -> dict:
    row = {
        "시장": label,
        "티커": ticker,
        "1일": np.nan,
        "5일": np.nan,
        "20일": np.nan,
        "20일고점대비": np.nan,
        "MA20": "-",
        "MA50": "-",
        "연속하락": 0,
        "데이터": "부족",
    }
    try:
        df = load_price_df(ticker, "3mo")
        if df is None or df.empty or "Close" not in df.columns:
            return row
        close = pd.to_numeric(df["Close"], errors="coerce").dropna()
        if len(close) < 25:
            return row
        last = float(close.iloc[-1])
        row["1일"] = (last / float(close.iloc[-2]) - 1) if len(close) >= 2 and close.iloc[-2] else np.nan
        row["5일"] = (last / float(close.iloc[-6]) - 1) if len(close) >= 6 and close.iloc[-6] else np.nan
        row["20일"] = (last / float(close.iloc[-21]) - 1) if len(close) >= 21 and close.iloc[-21] else np.nan
        recent_high = float(close.tail(20).max())
        row["20일고점대비"] = (last / recent_high - 1) if recent_high else np.nan
        ma20 = float(close.tail(20).mean())
        ma50 = float(close.tail(min(50, len(close))).mean())
        row["MA20"] = "하회" if last < ma20 else "상회"
        row["MA50"] = "하회" if last < ma50 else "상회"
        diffs = close.diff().tail(8).dropna()
        streak = 0
        for v in reversed(diffs.tolist()):
            if v < 0:
                streak += 1
            else:
                break
        row["연속하락"] = int(streak)
        row["데이터"] = "정상"
    except Exception:
        return row
    return row


def build_today_macro_guard_table(macro_data=None) -> tuple[pd.DataFrame, int, int, str]:
    macro_data = macro_data if isinstance(macro_data, dict) else globals().get("macro_res", {})
    rows = []
    pressure_count = 0
    relief_count = 0

    for name in TODAY_MARKET_GUARD_MACRO_ORDER:
        info = macro_data.get(name, {}) if isinstance(macro_data, dict) else {}
        val = clean_float(info.get("val"), np.nan)
        chg = clean_float(info.get("chg"), np.nan)
        icon = str(info.get("icon", "-") or "-")
        storm = bool(info.get("storm", False))
        state = "미수집"
        note = "데이터 없음"

        if finite_num(val):
            state = "중립"
            note = "큰 경고 없음"

            if name == "10Y 금리":
                if storm or float(val) >= 4.7:
                    state, note = "경고", "성장주·레버리지 부담"
                elif float(val) >= 4.4 and icon == "🔺":
                    state, note = "주의", "금리 압박 확대"
                elif icon == "🔻":
                    state, note = "완화", "금리 부담 완화"
            elif name == "환율":
                if storm or float(val) >= 1450:
                    state, note = "경고", "원화 약세·해외자산 변동성 확대"
                elif float(val) >= 1400 and icon == "🔺":
                    state, note = "주의", "환율 부담 확대"
                elif icon == "🔻":
                    state, note = "완화", "환율 부담 완화"
            elif name == "VIX":
                if storm or float(val) >= 30:
                    state, note = "경고", "단기 공포 확대"
                elif float(val) >= 22 and icon == "🔺":
                    state, note = "주의", "변동성 상승"
                elif float(val) <= 18 and icon == "🔻":
                    state, note = "완화", "공포 완화"
            elif name == "MOVE":
                if float(val) >= 120:
                    state, note = "경고", "채권시장 변동성 확대"
                elif float(val) >= 100:
                    state, note = "주의", "금리 변동성 주의"
                elif float(val) < 90:
                    state, note = "완화", "채권 변동성 안정"
            elif name == "유가":
                if float(val) >= 90 and icon == "🔺":
                    state, note = "주의", "인플레 압박 가능"
                elif icon == "🔻":
                    state, note = "완화", "인플레 압박 완화"

            if state == "경고":
                pressure_count += 2
            elif state == "주의":
                pressure_count += 1
            elif state == "완화":
                relief_count += 1

        rows.append({
            "지표": name,
            "현재값": "-" if not finite_num(val) else f"{float(val):,.1f}",
            "1개월변화": "-" if not finite_num(chg) else f"{float(chg):+.1f}%",
            "방향": icon,
            "상태": state,
            "해석": note,
        })

    if pressure_count >= 4:
        note = "금리·환율·변동성 경고가 겹쳐 신규매수보다 현금과 비중 점검이 우선입니다."
    elif pressure_count >= 2:
        note = "매크로 부담이 일부 있어 신규매수는 정찰·분할 접근이 적합합니다."
    elif relief_count >= 2:
        note = "매크로 부담은 낮아지는 편이며, 지수 추세와 종목 타점을 중심으로 보면 됩니다."
    else:
        note = "매크로는 중립권이라 가격 추세와 돈흐름 신호를 우선 봅니다."

    return pd.DataFrame(rows), int(pressure_count), int(relief_count), note


def build_today_market_guard(snapshot=None, summary_df=None) -> dict:
    benchmark_rows = [
        _calc_today_benchmark_guard_row(ticker, label)
        for ticker, label in TODAY_MARKET_GUARD_BENCHMARKS
    ]
    bench_df = pd.DataFrame(benchmark_rows)
    valid = bench_df[bench_df["데이터"].eq("정상")].copy() if not bench_df.empty else pd.DataFrame()

    score = 0
    reasons = []

    valid_count = max(len(valid), 1)
    below20 = int(valid["MA20"].eq("하회").sum()) if not valid.empty else 0
    below50 = int(valid["MA50"].eq("하회").sum()) if not valid.empty else 0
    down3 = int(valid["연속하락"].ge(3).sum()) if not valid.empty else 0
    weak5 = int(valid["5일"].apply(lambda v: finite_num(v) and float(v) <= -0.03).sum()) if not valid.empty else 0
    sharp_day = int(valid["1일"].apply(lambda v: finite_num(v) and float(v) <= -0.015).sum()) if not valid.empty else 0
    rebound_count = int(valid["1일"].apply(lambda v: finite_num(v) and float(v) >= 0.015).sum()) if not valid.empty else 0
    strong_rebound_count = int(valid["1일"].apply(lambda v: finite_num(v) and float(v) >= 0.03).sum()) if not valid.empty else 0
    max_day_gain = clean_float(valid["1일"].max(), np.nan) if not valid.empty and "1일" in valid.columns else np.nan

    if below20 >= 3:
        score += 2
        reasons.append(f"주요지수 {below20}개가 MA20 아래")
    elif below20 >= 2:
        score += 1
        reasons.append(f"주요지수 {below20}개가 MA20 아래")
    if below50 >= 2:
        score += 2
        reasons.append(f"주요지수 {below50}개가 MA50 아래")
    if down3 >= 2:
        score += 2
        reasons.append(f"연속 하락 3일 이상 지수 {down3}개")
    if weak5 >= 2:
        score += 2
        reasons.append(f"5거래일 -3% 이하 지수 {weak5}개")
    if sharp_day >= 2:
        score += 1
        reasons.append(f"하루 -1.5% 이하 급락 지수 {sharp_day}개")

    flow_breadth = np.nan
    flow_accel = np.nan
    if snapshot:
        flow_df = snapshot.get("flow_df", pd.DataFrame())
        if flow_df is not None and not flow_df.empty:
            flow_calc = flow_df[flow_df.get("구분", pd.Series("", index=flow_df.index)).astype(str).ne("매크로")].copy()
            if "3개월수익률" in flow_calc.columns and not flow_calc.empty:
                flow_breadth = float((flow_calc["3개월수익률"].fillna(0) > 0).mean())
                if flow_breadth < 0.35:
                    score += 2
                    reasons.append(f"돈흐름 3M 상승 비율 {flow_breadth*100:.0f}%")
                elif flow_breadth < 0.50:
                    score += 1
                    reasons.append(f"돈흐름 3M 상승 비율 {flow_breadth*100:.0f}%")
            if "가속도" in flow_calc.columns and not flow_calc.empty:
                flow_accel = float((flow_calc["가속도"].fillna(0) > 0).mean())
                if flow_accel < 0.35:
                    score += 1
                    reasons.append(f"가속 ETF 비율 {flow_accel*100:.0f}%")

    macro_df, macro_pressure, macro_relief, macro_note = build_today_macro_guard_table()
    event_df, event_risk, event_count = build_macro_event_risk_table()
    macro_risk = clean_float(globals().get("final_macro_risk", np.nan), np.nan)
    macro_score = 0
    if macro_pressure >= 4:
        macro_score += 2
    elif macro_pressure >= 2:
        macro_score += 1
    if finite_num(macro_risk):
        if float(macro_risk) >= 4.5:
            macro_score += 2
        elif float(macro_risk) >= 3.5:
            macro_score += 1
    macro_score = min(macro_score, 3)
    if macro_score > 0:
        score += macro_score
        risk_text = "-" if not finite_num(macro_risk) else f"{float(macro_risk):.1f}"
        reasons.append(f"매크로 경고 {macro_pressure}점/리스크 {risk_text}")
    if event_risk > 0:
        event_score = 2 if event_risk >= 2.0 else 1
        score += event_score
        reasons.append(f"이벤트 임박 {event_count}개/점수 {event_risk:.1f}")

    hard_count = 0
    caution_count = 0
    if summary_df is not None and not summary_df.empty:
        code_series = summary_df.get("판정코드", pd.Series("", index=summary_df.index)).astype(str)
        label_series = summary_df.get("🔥기술적 타점", pd.Series("", index=summary_df.index)).astype(str)
        hard_count = int((code_series.str.contains("HARD_BLOCK", na=False) | label_series.str.contains("하드차단", na=False)).sum())
        caution_count = int(label_series.str.contains("구조훼손|추매금지|진입 보류|과열|차단", regex=True, na=False).sum())
        if hard_count >= 3:
            score += 2
            reasons.append(f"내 관심목록 하드차단 {hard_count}개")
        elif hard_count >= 1:
            score += 1
            reasons.append(f"내 관심목록 하드차단 {hard_count}개")

    flow_recovery_ok = (
        (finite_num(flow_breadth) and float(flow_breadth) >= 0.55)
        or (finite_num(flow_accel) and float(flow_accel) >= 0.50)
    )
    tactical_rebound = (
        score >= 8
        and flow_recovery_ok
        and (strong_rebound_count >= 2 or (finite_num(max_day_gain) and float(max_day_gain) >= 0.05))
    )

    if score >= 8:
        if tactical_rebound:
            mode, level, action = "위험장 반등", "warning", "추격 금지 · 코어/강섹터 소액 전술 참여"
            if finite_num(max_day_gain):
                reasons.insert(0, f"당일 강반등 지수 {strong_rebound_count}개/최대 {float(max_day_gain)*100:.1f}%")
            actions = [
                "전면 관망보다 코어 ETF·강한 섹터 후보만 목표금액의 25~33% 이내로 정찰",
                "개별 급등주와 52주 고점권 종목은 추격하지 말고 다음 눌림을 대기",
                "레버리지는 기존 DCA 규칙 안에서만 소액, 당일 반등 추격 배팅은 금지",
                "반등 후 종가가 MA20 회복 또는 다음 거래일 후속 매수 확인 전까지 추가 확대 보류",
            ]
        else:
            mode, level, action = "위험", "danger", "신규매수 중단 · 현금/리스크 점검"
            actions = [
                "신규 후보 탐색보다 보유 종목 손실 단계와 비중 초과를 먼저 확인",
                "레버리지 추가매수는 평단 하락 조건이 와도 시장 안정 신호 확인 전 보류",
                "현금이 부족하면 반등 매수보다 현금 확보 계획을 우선",
            ]
    elif score >= 5:
        mode, level, action = "방어", "warning", "정찰만 · 현금 확보 우선"
        actions = [
            "신규매수는 목표금액의 일부만 정찰",
            "코어 적립은 유지하되 과열/구조훼손 종목은 제외",
            "레버리지는 정해둔 DCA 배율 외 추가 판단 금지",
        ]
    elif score >= 2:
        mode, level, action = "주의", "caution", "분할 접근 · 후보만 선별"
        actions = [
            "후보는 전광판/정밀관측소에서 눌림 확인 후 분할",
            "현금 비중이 목표보다 낮으면 신규매수 속도 조절",
        ]
    else:
        mode, level, action = "정상", "normal", "선별 매수 가능"
        actions = [
            "돈흐름과 정밀관측소 타점이 같이 맞는 후보만 선별",
            "목표비중 초과 종목은 추가매수 제외",
        ]

    if not reasons:
        reasons.append("주요 위험 신호 제한적")

    return {
        "mode": mode,
        "level": level,
        "score": int(score),
        "action": action,
        "reasons": reasons[:5],
        "actions": actions,
        "bench_df": bench_df,
        "flow_breadth": flow_breadth,
        "flow_accel": flow_accel,
        "rebound_count": rebound_count,
        "strong_rebound_count": strong_rebound_count,
        "max_day_gain": max_day_gain,
        "tactical_rebound": tactical_rebound,
        "macro_risk": macro_risk,
        "macro_df": macro_df,
        "event_df": event_df,
        "event_risk": event_risk,
        "event_count": event_count,
        "macro_pressure": macro_pressure,
        "macro_relief": macro_relief,
        "macro_note": macro_note,
        "hard_count": hard_count,
        "caution_count": caution_count,
    }


def render_today_market_guard_panel(guard: dict):
    if not guard:
        return

    mode = guard.get("mode", "주의")
    level = guard.get("level", "caution")
    color_map = {
        "normal": "#22c55e",
        "caution": "#f59e0b",
        "warning": "#fb923c",
        "danger": "#ef4444",
    }
    color = color_map.get(level, "#f59e0b")
    reason_text = " · ".join(str(x) for x in guard.get("reasons", []) if str(x).strip())
    action_text = str(guard.get("action", "-"))
    macro_note = str(guard.get("macro_note", "") or "")

    st.markdown("#### 1. 시장 안전벨트")
    st.markdown(
        f"""
<div class='info-panel' style='border-left:5px solid {color}; margin-bottom:10px;'>
<b>시장 모드: <span style='color:{color};'>{html.escape(mode)}</span></b><br>
<span class='highlight'>{html.escape(action_text)}</span><br>
<span style='color:#94a3b8;'>근거: {html.escape(reason_text)}</span><br>
<span style='color:#cbd5e1;'>매크로 해석: {html.escape(macro_note)}</span>
</div>
        """,
        unsafe_allow_html=True,
    )

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("위험점수", f"{guard.get('score', 0)}점")
    flow_breadth = guard.get("flow_breadth", np.nan)
    flow_accel = guard.get("flow_accel", np.nan)
    macro_risk = guard.get("macro_risk", np.nan)
    c2.metric("돈흐름 상승폭", "-" if not finite_num(flow_breadth) else f"{float(flow_breadth)*100:.0f}%")
    c3.metric("가속 ETF 비율", "-" if not finite_num(flow_accel) else f"{float(flow_accel)*100:.0f}%")
    c4.metric("매크로 리스크", "-" if not finite_num(macro_risk) else f"{float(macro_risk):.1f}")
    if guard.get("tactical_rebound"):
        max_day_gain = guard.get("max_day_gain", np.nan)
        st.caption(
            "전술 반등 감지: "
            f"+3% 이상 반등 지수 {int(guard.get('strong_rebound_count', 0))}개"
            + ("" if not finite_num(max_day_gain) else f" · 최대 당일상승 {float(max_day_gain)*100:.1f}%")
            + " · 단, 위험점수는 유지하므로 추격/과대비중은 금지"
        )

    with st.expander("시장 안전벨트 세부 지표", expanded=False):
        bench_df = guard.get("bench_df", pd.DataFrame())
        if bench_df is None or bench_df.empty:
            st.info("시장 지표 데이터가 부족합니다.")
        else:
            show = bench_df.copy()
            for col in ["1일", "5일", "20일", "20일고점대비"]:
                if col in show.columns:
                    show[col] = show[col].apply(_format_today_signed_pct)
            st.dataframe(show, width='stretch', hide_index=True)

        macro_df = guard.get("macro_df", pd.DataFrame())
        if macro_df is not None and not macro_df.empty:
            st.markdown("##### 매크로 경고등")
            st.dataframe(macro_df, width='stretch', hide_index=True)

        event_df = guard.get("event_df", pd.DataFrame())
        if event_df is not None and not event_df.empty:
            st.markdown("##### 이벤트 캘린더")
            st.caption("수동 등록 일정에 Fed 공식 일정, 국내 만기 규칙, ForexFactory 주간 고영향 일정을 6시간 캐시로 자동 보강합니다.")
            st.dataframe(event_df, width='stretch', hide_index=True)


def build_today_market_memo_universe(summary_df=None):
    records: dict[str, dict] = {}
    status_map: dict[str, str] = {}

    if isinstance(summary_df, pd.DataFrame) and not summary_df.empty and "티커" in summary_df.columns:
        for _, row in summary_df.iterrows():
            key = normalize_ticker(row.get("티커", ""))
            if not key:
                continue
            status_map[key] = str(row.get("🔥기술적 타점", "") or row.get("판정분류", "") or "")

    def add_record(ticker, name="", source="관심", asset_class="", is_etf=False):
        ticker = sanitize_ticker_value(ticker)
        key = normalize_ticker(ticker)
        if not key:
            return
        prev = records.get(key, {})
        merged_source = source
        if prev.get("source") == "보유" or source == "보유":
            merged_source = "보유"
        records[key] = {
            "ticker": ticker,
            "name": str(name or prev.get("name") or ticker),
            "source": merged_source,
            "asset_class": str(asset_class or prev.get("asset_class") or ""),
            "is_etf": bool(is_etf or prev.get("is_etf", False)),
            "status": status_map.get(key, prev.get("status", "")),
        }

    table = globals().get("holdings_table", pd.DataFrame())
    if isinstance(table, pd.DataFrame) and not table.empty:
        for _, row in table.iterrows():
            ticker = row.get("티커", "")
            qty = clean_float(row.get("보유량", 0.0), 0.0)
            value = clean_float(row.get("원화환산", 0.0), 0.0)
            source = "보유" if qty > 0 or value > 0 else "자산"
            add_record(
                ticker,
                row.get("자산명", ticker),
                source,
                row.get("asset_class", row.get("유형", "")),
                clean_bool(row.get("is_etf", False)),
            )

    for item in st.session_state.get("watchlist", []) or []:
        item = sanitize_watchlist_item(item)
        add_record(
            item.get("ticker", ""),
            item.get("name", ""),
            "관심",
            item.get("asset_class", ""),
            clean_bool(item.get("is_etf", False)),
        )

    return list(records.values()), status_map


def select_today_auto_newspick_targets(universe, summary_df=None, max_count=5):
    targets: list[dict] = []
    seen: set[str] = set()

    def add_target(ticker, name="", reason="", priority=10):
        ticker = sanitize_ticker_value(ticker)
        key = normalize_ticker(ticker)
        if not key or key in seen:
            return
        seen.add(key)
        targets.append({
            "ticker": ticker,
            "name": str(name or ticker),
            "reason": str(reason or "관심"),
            "priority": int(priority),
        })

    if isinstance(summary_df, pd.DataFrame) and not summary_df.empty and "티커" in summary_df.columns:
        work = summary_df.copy()
        label = work.get("🔥기술적 타점", pd.Series("", index=work.index)).astype(str)
        code = work.get("판정코드", pd.Series("", index=work.index)).astype(str)
        score = work.get("Adj점수", pd.Series(0.0, index=work.index)).apply(clean_float)
        work["_newspick_priority"] = 6
        work.loc[label.str.contains("매수|진입|DCA|적립|눌림|탑승", regex=True, na=False), "_newspick_priority"] = 1
        work.loc[code.str.contains("HARD_BLOCK", na=False) | label.str.contains("하드차단|구조훼손|추매금지", regex=True, na=False), "_newspick_priority"] = 2
        work["_newspick_score"] = score
        for _, row in work.sort_values(["_newspick_priority", "_newspick_score"], ascending=[True, False]).head(max_count * 2).iterrows():
            add_target(
                row.get("티커", ""),
                row.get("종목명", ""),
                row.get("🔥기술적 타점", "오늘점검"),
                row.get("_newspick_priority", 6),
            )
            if len(targets) >= max_count:
                return targets

    for item in universe or []:
        if str(item.get("source", "")) == "보유":
            add_target(item.get("ticker", ""), item.get("name", ""), "보유", 3)
        if len(targets) >= max_count:
            return targets

    for item in universe or []:
        add_target(item.get("ticker", ""), item.get("name", ""), item.get("source", "관심"), 5)
        if len(targets) >= max_count:
            return targets
    return targets[:max_count]


def collect_today_auto_newspick_news(universe, summary_df=None, max_count=5):
    news_rows = []
    targets = select_today_auto_newspick_targets(universe, summary_df, max_count=max_count)
    for target in targets:
        ticker = target.get("ticker", "")
        name = target.get("name", ticker)
        if not ticker:
            continue
        try:
            items, _logs = get_ticker_news(ticker, name, debug=False)
        except Exception:
            items = []
        for item in (items or [])[:2]:
            row = dict(item)
            row["ticker"] = ticker
            row["name"] = name
            row["target_reason"] = target.get("reason", "")
            news_rows.append(row)
    return dedupe_today_auto_newspick_news_rows(news_rows), targets


def _today_newspick_news_key(row):
    title = str((row or {}).get("title", "") or "").strip().lower()
    publisher = str((row or {}).get("publisher", "") or "").strip().lower()
    title = re.sub(r"\s+", " ", re.sub(r"\s+-\s+.+$", "", title))
    return (publisher, title[:140])


def dedupe_today_auto_newspick_news_rows(news_rows):
    deduped = []
    seen = set()
    for row in news_rows or []:
        key = _today_newspick_news_key(row)
        if key[1] and key in seen:
            continue
        seen.add(key)
        deduped.append(row)
    return deduped


